window.BANCO = {"versao": "1.0", "gerado_em": "2026-11-15", "autor": {"nome": "Leônidas Leandro de Souza", "instagram": "@prof.tenebroso", "instituicao": "CESAR School", "curso": "Gestão da Tecnologia da Informação (GTI) - 5º período"}, "disciplinas": [{"id": "gsc", "nome": "Gestão de Segurança Cibernética", "codigo": "GTI026"}, {"id": "gov", "nome": "Governança em TI", "codigo": "GTI022"}, {"id": "eag", "nome": "Estudos Avançados em GTI", "codigo": "GTI027"}], "tipos_de_questao": {"multipla_escolha": "alternativas + corretas (lista de letras; multipla_resposta=true quando houver mais de uma)", "verdadeiro_falso": "alternativas {a: Verdadeiro, b: Falso} + corretas", "lacunas": "texto_lacunas com marcadores {{1}}, {{2}}...; opcoes_lacunas = banco de palavras; corretas[i] = resposta da lacuna i+1", "associacao": "pares [{item, resposta}]; opcoes_associacao = respostas possíveis; corretas[i] = resposta do item i"}, "fonte_gabarito": {"oficial": "confirmado pela revisão/correção do Moodle", "especialista": "respondido pelo especialista; Moodle ainda não liberou o gabarito"}, "questoes": [{"id": "GSC-U1-Q01", "disciplina": "gsc", "unidade": 1, "origem": {"questionario": "1.3 Quiz", "tipo": "quiz"}, "tema": "Aspectos/camadas da segurança", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Uma startup de tecnologia percebeu que, embora seus servidores fossem robustos, qualquer pessoa podia entrar na sala de máquinas sem identificação. Com base nos aspectos de segurança, qual camada está sendo negligenciada?", "alternativas": {"a": "Aspecto lógico", "b": "Aspecto físico", "c": "Aspecto humano", "d": "Aspecto estratégico"}, "corretas": ["b"], "explicacao": "O aspecto físico cuida da proteção do ambiente e dos equipamentos: controle de acesso a salas e datacenters, crachás, catracas, câmeras, fechaduras. Se qualquer pessoa entra na sala de máquinas sem se identificar, é o controle de acesso físico que está falhando. Os servidores serem 'robustos' (proteção lógica/técnica) não resolve isso.", "por_que_erradas": {"a": "O aspecto lógico trata de controles digitais (firewall, senhas, criptografia, permissões de sistema). O enunciado diz que essa parte está boa ('servidores robustos'); o problema é entrar na sala.", "c": "O aspecto humano envolve conscientização, treinamento e comportamento das pessoas (ex.: engenharia social). Aqui não se descreve erro ou falta de treinamento de alguém, e sim a ausência de uma barreira física de identificação.", "d": "O aspecto estratégico envolve governança, políticas e alinhamento da segurança aos objetivos do negócio. A falha descrita é operacional e concreta: o acesso à sala."}, "fonte_gabarito": "oficial"}, {"id": "GSC-U1-Q02", "disciplina": "gsc", "unidade": 1, "origem": {"questionario": "1.3 Quiz", "tipo": "quiz"}, "tema": "Fator humano", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Um gestor de TI precisa decidir entre comprar um firewall de última geração ou treinar a equipe, sabendo que 80% dos riscos vêm de dentro da empresa. Considerando o \"Fator Humano\", qual deve ser o foco para mitigar a maior fonte de riscos?", "alternativas": {"a": "Focar na criptografia", "b": "Ignorar ameaças externas", "c": "Investir apenas em hardware", "d": "Treinamento e conscientização"}, "corretas": ["d"], "explicacao": "Se 80% dos riscos vêm de dentro (erros, descuidos, phishing, uso indevido de acessos), a medida que ataca a maior fonte de risco é atuar sobre as pessoas: treinamento e conscientização. O firewall protege o perímetro contra ameaças externas, mas não impede que um funcionário clique num link malicioso, compartilhe senha ou vaze dados. As pessoas são o 'elo mais fraco' da segurança.", "por_que_erradas": {"a": "Criptografia é um controle técnico/lógico que protege dados, mas não muda o comportamento de quem tem acesso legítimo a eles. Um usuário autorizado e mal orientado continua sendo o risco.", "b": "Ignorar ameaças externas nunca é recomendado. Segurança é feita em camadas; priorizar o interno não significa abandonar o externo.", "c": "'Apenas hardware' é tecnologia, justamente o que não resolve o fator humano. A palavra 'apenas' torna a alternativa radical e incorreta."}, "fonte_gabarito": "especialista", "gabarito_oficial_moodle": ["a"], "observacao": "No Moodle, a alternativa d apareceu marcada com X vermelho, mas o próprio feedback dela diz que está correta ('O elemento humano é o elo mais vulnerável...'). Nenhuma outra alternativa é defensável; provável erro de configuração do gabarito. Vale pedir revisão ao professor."}, {"id": "GSC-U1-Q03", "disciplina": "gsc", "unidade": 1, "origem": {"questionario": "1.3 Quiz", "tipo": "quiz"}, "tema": "Tríade CIA (CID)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Uma empresa sofre um ataque de negação de serviço (DoS) e seu site de vendas fica fora do ar por 48 horas durante a Black Friday. Considerando o comprometimento da continuidade do serviço, qual pilar da segurança foi afetado?", "alternativas": {"a": "Integridade", "b": "Confidencialidade", "c": "Legalidade", "d": "Disponibilidade"}, "corretas": ["d"], "explicacao": "Disponibilidade é garantir que a informação e os serviços estejam acessíveis aos usuários autorizados sempre que necessário. Um ataque DoS (Denial of Service, 'negação de serviço') tem exatamente esse objetivo: sobrecarregar o sistema para que ele fique fora do ar. Site fora do ar = disponibilidade comprometida.", "por_que_erradas": {"a": "Integridade é garantir que os dados não sejam alterados de forma indevida. O DoS não modifica dados; ele só impede o acesso ao serviço.", "b": "Confidencialidade é garantir que só pessoas autorizadas acessem a informação. Não houve vazamento nem acesso indevido a dados, só indisponibilidade.", "c": "Legalidade (conformidade com leis, como a LGPD) é um princípio complementar, não faz parte da tríade CID, e não é o que um ataque DoS afeta diretamente."}, "fonte_gabarito": "oficial"}, {"id": "GSC-U1-Q04", "disciplina": "gsc", "unidade": 1, "origem": {"questionario": "1.3 Quiz", "tipo": "quiz"}, "tema": "Tríade CIA (CID)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Um colaborador de uma empresa de RH enviou por engano a folha de pagamento de toda a diretoria para um grupo público de mensagens. Qual pilar da tríade CIA foi diretamente violado neste caso?", "alternativas": {"a": "Integridade", "b": "Confidencialidade", "c": "Conformidade", "d": "Disponibilidade"}, "corretas": ["b"], "explicacao": "Confidencialidade é garantir que a informação só seja acessada por pessoas autorizadas. Salários da diretoria são informação sigilosa; ao enviá-los a um grupo público, pessoas não autorizadas passaram a ter acesso. Não importa que tenha sido por engano (incidente acidental/fator humano): o pilar violado continua sendo a confidencialidade.", "por_que_erradas": {"a": "Integridade seria violada se os valores da folha fossem alterados. Os dados foram expostos, mas continuam corretos.", "c": "Conformidade (compliance) não faz parte da tríade CIA. Pode até haver consequência legal (ex.: LGPD), mas a pergunta pede o pilar da tríade diretamente violado.", "d": "Disponibilidade seria afetada se a folha ficasse inacessível para quem precisa dela. Ela continua disponível; o problema é que ficou visível para quem não devia."}, "fonte_gabarito": "oficial"}, {"id": "GSC-U1-Q05", "disciplina": "gsc", "unidade": 1, "origem": {"questionario": "1.3 Quiz", "tipo": "quiz"}, "tema": "Tríade CIA (CID)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Durante uma atualização de sistema, um banco de dados foi corrompido, o que resultou na alteração dos saldos das contas de clientes, mesmo sem a ocorrência de um ataque externo. O incidente descrito afetou qual princípio fundamental da segurança?", "alternativas": {"a": "Continuidade", "b": "Integridade", "c": "Conformidade", "d": "Disponibilidade"}, "corretas": ["b"], "explicacao": "Integridade é garantir que a informação seja exata, completa e não sofra alterações indevidas ou não autorizadas. Os saldos foram alterados por uma corrupção do banco de dados, então os dados deixaram de ser confiáveis. A integridade pode ser violada sem ataque nenhum: falha técnica, bug, erro humano ou corrupção de arquivo também contam.", "por_que_erradas": {"a": "Continuidade (de negócios) não é um dos pilares da tríade CIA; é um tema de gestão (plano de continuidade). Além disso, o problema descrito é dado errado, não serviço interrompido.", "c": "Conformidade (compliance) não é pilar da tríade e não descreve o que aconteceu com os dados.", "d": "Disponibilidade seria afetada se o sistema ou os saldos ficassem inacessíveis. Aqui os dados continuam acessíveis, mas com valores errados."}, "fonte_gabarito": "oficial"}, {"id": "GSC-U1-Q06", "disciplina": "gsc", "unidade": 1, "origem": {"questionario": "1.6 Avaliação Final - Unidade 1", "tipo": "avaliacao_final"}, "tema": "Gestão de incidentes e continuidade de negócio", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A gestão de incidentes é uma parte vital da estratégia de segurança, pois assume que falhas podem ocorrer apesar das proteções. Em um plano de continuidade de negócio, o objetivo principal é:", "alternativas": {"a": "punir os responsáveis pelo erro.", "b": "comprar novos servidores físicos.", "c": "instalar novos softwares antivírus.", "d": "manter as operações durante crises."}, "corretas": ["d"], "explicacao": "O Plano de Continuidade de Negócios (PCN, ou BCP em inglês) existe para garantir que as funções críticas da organização continuem funcionando, ou voltem rapidamente, durante e após uma crise (ataque, desastre, queda de energia, pandemia). A ideia central é: incidentes vão acontecer; o importante é a empresa sobreviver a eles e continuar operando.", "por_que_erradas": {"a": "Punir responsáveis não é objetivo do PCN. A gestão de incidentes busca aprender com o erro e corrigir o processo (lições aprendidas), não encontrar culpados.", "b": "Comprar servidores pode até ser uma ação dentro de um plano, mas é um meio, não o objetivo. O PCN é sobre processos e estratégias, não sobre aquisição de hardware.", "c": "Antivírus é um controle preventivo. O PCN parte justamente do princípio de que a prevenção pode falhar e foca em continuar operando mesmo assim."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U1-Q07", "disciplina": "gsc", "unidade": 1, "origem": {"questionario": "1.6 Avaliação Final - Unidade 1", "tipo": "avaliacao_final"}, "tema": "Análise custo-benefício", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A implementação de controles de segurança em uma organização não deve ser vista como um custo isolado, mas como um investimento estratégico. Sobre o princípio da análise custo-benefício na proteção da informação, é correto afirmar que:", "alternativas": {"a": "controles tecnológicos dispensam a análise de viabilidade financeira.", "b": "a segurança deve ser implementada independentemente dos custos envolvidos.", "c": "o custo do controle deve ser sempre superior ao valor do ativo.", "d": "o investimento em segurança deve ser proporcional ao valor dos ativos e à redução de riscos."}, "corretas": ["d"], "explicacao": "Pela análise custo-benefício, o quanto se gasta para proteger algo deve ser proporcional ao valor desse ativo e ao risco que o controle reduz. Não faz sentido gastar R$ 100 mil para proteger uma informação que vale R$ 10 mil; também não faz sentido economizar na proteção de algo crítico. Regra prática: o custo do controle deve ser MENOR que o prejuízo que ele evita.", "por_que_erradas": {"a": "Nenhum controle dispensa análise financeira. Tecnologia custa dinheiro (compra, licença, manutenção, pessoal) e precisa se justificar.", "b": "'Independentemente dos custos' ignora a realidade do negócio. Segurança infinita é impossível e inviável; o risco é gerenciado, não eliminado a qualquer preço.", "c": "É o contrário: se o controle custa mais que o ativo, é mais barato perder o ativo do que protegê-lo. O custo do controle deve ser inferior ao valor do ativo/prejuízo evitado."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U1-Q08", "disciplina": "gsc", "unidade": 1, "origem": {"questionario": "1.6 Avaliação Final - Unidade 1", "tipo": "avaliacao_final"}, "tema": "Desafios da segurança em multinacionais", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A proteção da informação em grandes corporações enfrenta obstáculos que vão além da tecnologia, esbarrando em estruturas complexas. Qual fator dificulta a implementação de políticas de segurança globais em organizações multinacionais?", "alternativas": {"a": "uso excessivo de criptografia.", "b": "A ausência de internet nas filiais.", "c": "A diversidade de culturas locais.", "d": "A falta de hardware no mercado."}, "corretas": ["c"], "explicacao": "Em multinacionais, uma política de segurança global precisa funcionar em países com culturas, idiomas, comportamentos, leis (LGPD no Brasil, GDPR na Europa) e práticas de trabalho diferentes. O que é aceito ou natural em um país pode não ser em outro. Por isso a diversidade cultural (que envolve o fator humano) é o grande obstáculo — e o enunciado já avisa: 'obstáculos que vão além da tecnologia'.", "por_que_erradas": {"a": "Criptografia é um controle técnico; o enunciado diz que o obstáculo vai além da tecnologia. Além disso, 'uso excessivo de criptografia' não é um problema típico de implementação de políticas.", "b": "Multinacionais não operam filiais sem internet; é uma premissa irreal e também tecnológica.", "d": "Falta de hardware é um problema de mercado/tecnologia, não uma barreira estrutural ou cultural à aplicação de políticas."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U1-Q09", "disciplina": "gsc", "unidade": 1, "origem": {"questionario": "1.6 Avaliação Final - Unidade 1", "tipo": "avaliacao_final"}, "tema": "Dimensões da segurança (técnica)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A segurança da informação é descrita como um continuum que abrange desde políticas de alto nível até configurações técnicas detalhadas. Sobre a dimensão técnica da segurança da informação, assinale a alternativa correta.", "alternativas": {"a": "Trata exclusivamente da legislação e marcos regulatórios como a LGPD.", "b": "Envolve a configuração de controles tecnológicos e permissões de acesso.", "c": "Refere-se apenas à proteção física de prédios e no-breaks.", "d": "Foca apenas no treinamento de usuários e mudança de cultura."}, "corretas": ["b"], "explicacao": "A dimensão técnica (ou lógica) é a ponta 'operacional' do continuum: firewalls, antivírus, criptografia, autenticação, controle de acesso, permissões de usuários, configurações de sistemas. No outro extremo ficam as políticas de alto nível (dimensão estratégica/gestão). Cada alternativa errada descreve outra dimensão: legal, física e humana.", "por_que_erradas": {"a": "Legislação e regulação (LGPD) pertencem à dimensão legal/de conformidade, não à técnica. E o 'exclusivamente' já torna a alternativa radical.", "c": "Proteção de prédios e no-breaks é a dimensão física. O 'apenas' também é sinal de alternativa errada.", "d": "Treinamento e cultura são a dimensão humana. De novo, o 'apenas' restringe indevidamente."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U1-Q10", "disciplina": "gsc", "unidade": 1, "origem": {"questionario": "1.6 Avaliação Final - Unidade 1", "tipo": "avaliacao_final"}, "tema": "Política de Segurança da Informação (PSI)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "De acordo com Fraser (1997), a política de segurança é uma declaração formal de regras para o acesso a bens de tecnologia e informação. Um elemento essencial que deve constar em uma Política de Segurança da Informação eficaz é:", "alternativas": {"a": "o código-fonte dos sistemas.", "b": "a classificação das informações.", "c": "a lista de salários da TI.", "d": "o histórico de navegação dos diretores."}, "corretas": ["b"], "explicacao": "A classificação da informação (ex.: pública, interna, confidencial, restrita) é base da PSI: só se protege adequadamente o que se sabe quanto vale e quão sensível é. É ela que define quem pode acessar o quê e quais controles aplicar a cada tipo de informação, o que se encaixa na definição de Fraser (regras para acesso aos bens de informação). Também se liga à análise custo-benefício: proteção proporcional ao valor.", "por_que_erradas": {"a": "Código-fonte é um ativo a ser protegido pela política, não um conteúdo dela. A PSI é um documento de regras e diretrizes, não um repositório de sistemas; incluir o código seria até um risco de segurança.", "c": "Salários são informação confidencial de RH; não fazem parte de uma política de segurança e expô-los seria violar a confidencialidade (lembre da U1-Q04).", "d": "Histórico de navegação de diretores é dado pessoal/monitoramento, não um elemento da política. A PSI pode prever regras de uso da internet, mas não conter históricos de pessoas."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U1-Q11", "disciplina": "gsc", "unidade": 1, "origem": {"questionario": "1.6 Avaliação Final - Unidade 1", "tipo": "avaliacao_final"}, "tema": "Conformidade e melhoria contínua", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Estudos indicam que a grande maioria das organizações tem itens em desconformidade com suas próprias políticas de segurança. Diante dessa realidade de \"não conformidade\", qual abordagem é necessária para manter a eficácia dos controles?", "alternativas": {"a": "Substituir todos os funcionários.", "b": "Eliminar as políticas de segurança.", "c": "Melhoria contínua e monitoramento.", "d": "Focar apenas em ameaças externas."}, "corretas": ["c"], "explicacao": "Segurança não é um projeto com fim, é um processo contínuo. Como ambiente, ameaças e pessoas mudam o tempo todo, a organização precisa monitorar (auditorias, indicadores, logs) e corrigir desvios continuamente. É a lógica do ciclo PDCA (Planejar, Executar, Verificar, Agir), base da ISO/IEC 27001: encontrar a não conformidade, tratar e melhorar.", "por_que_erradas": {"a": "Substituir todos os funcionários é radical e inútil: os novos também precisariam de treinamento e cometeriam desvios. O caminho é conscientizar, não trocar pessoas.", "b": "Eliminar as políticas porque ninguém cumpre é inverter a lógica: sem política não há nem referência do que é conforme. O certo é ajustar e reforçar a política.", "d": "Focar apenas em ameaças externas ignora que a não conformidade é interna (pessoas e processos da própria empresa). E o 'apenas' de novo."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U1-Q12", "disciplina": "gsc", "unidade": 1, "origem": {"questionario": "1.6 Avaliação Final - Unidade 1", "tipo": "avaliacao_final"}, "tema": "Ameaças externas e gestão de riscos", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Hackers e crackers representam uma ameaça externa persistente, embora as estatísticas mostrem que o volume de ataques internos seja superior. Com base na gestão de riscos e ameaças externas, é correto afirmar que:", "alternativas": {"a": "possuem alto potencial destrutivo e exigem investimento equilibrado.", "b": "são irrelevantes frente ao fator humano organizacional.", "c": "exigem o fim do uso de redes de computadores.", "d": "devem ser ignoradas por representarem poucos ataques."}, "corretas": ["a"], "explicacao": "Risco não é só frequência (quantos ataques), é também impacto (quanto estrago). Ataques externos são menos numerosos que os internos, mas um único ataque externo bem-sucedido (ransomware, invasão, DDoS) pode ser devastador. Por isso a gestão de riscos pede investimento equilibrado: proteger contra ameaças internas E externas, proporcionalmente ao risco de cada uma.", "por_que_erradas": {"b": "Chamar de 'irrelevantes' é extremo. O fator humano gera mais incidentes, mas isso não anula ameaças externas; segurança é feita em camadas.", "c": "Acabar com o uso de redes é absurdo: inviabiliza o negócio. A gestão de riscos busca reduzir riscos a um nível aceitável, não eliminar a atividade.", "d": "Ignorar uma ameaça por ser menos frequente esquece o impacto. Um ataque raro, mas catastrófico, pode ser o maior risco da empresa."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U1-Q13", "disciplina": "gsc", "unidade": 1, "origem": {"questionario": "1.6 Avaliação Final - Unidade 1", "tipo": "avaliacao_final"}, "tema": "Ciclo de vida da informação", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "O ciclo de vida da informação compreende diversas fases, desde o momento em que um dado é gerado até sua eliminação definitiva da organização. Na fase de \"Destruição\" do ciclo de vida, qual é a principal preocupação do gestor de segurança?", "alternativas": {"a": "Garantir a classificação inicial.", "b": "Assegurar o processamento rápido.", "c": "Monitorar a transmissão via rede.", "d": "Garantir a eliminação segura dos dados."}, "corretas": ["d"], "explicacao": "Na fase de descarte/destruição, o risco é a informação 'sobreviver' ao descarte: HD vendido sem formatação segura, papel jogado no lixo sem triturar, backup antigo esquecido. A preocupação é eliminar de forma segura e irrecuperável (trituração, desmagnetização, sobrescrita, destruição física da mídia). Fases do ciclo: Manuseio/Criação → Armazenamento → Transporte → Descarte.", "por_que_erradas": {"a": "Classificação é feita no início do ciclo (criação/manuseio), não na destruição.", "b": "Processamento rápido se relaciona ao uso/manuseio da informação, não ao seu descarte.", "c": "Monitorar transmissão em rede é preocupação da fase de transporte."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U1-Q14", "disciplina": "gsc", "unidade": 1, "origem": {"questionario": "1.6 Avaliação Final - Unidade 1", "tipo": "avaliacao_final"}, "tema": "Legislação (LGPD)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "O ordenamento jurídico brasileiro evoluiu para punir o uso inadequado de recursos tecnológicos e proteger a privacidade dos dados. Qual legislação regula especificamente o tratamento de dados pessoais no Brasil?", "alternativas": {"a": "O Decreto de Segurança Nacional.", "b": "O Marco Civil da Internet.", "c": "A Lei Geral de Proteção de Dados (LGPD).", "d": "O Código de Defesa do Consumidor."}, "corretas": ["c"], "explicacao": "A LGPD (Lei nº 13.709/2018) é a lei específica sobre tratamento de dados pessoais no Brasil: define bases legais, direitos dos titulares, papéis (controlador, operador, encarregado/DPO) e sanções aplicadas pela ANPD. A palavra-chave do enunciado é 'especificamente'.", "por_que_erradas": {"a": "Não existe um 'Decreto de Segurança Nacional' que regule dados pessoais; é distrator.", "b": "O Marco Civil da Internet (Lei 12.965/2014) trata de direitos e deveres no uso da internet (neutralidade, guarda de registros). Toca em privacidade, mas não é a lei específica de dados pessoais. É o distrator mais forte.", "d": "O CDC protege o consumidor nas relações de consumo; pode ser aplicado em vazamentos, mas não regula especificamente o tratamento de dados."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U1-Q15", "disciplina": "gsc", "unidade": 1, "origem": {"questionario": "1.6 Avaliação Final - Unidade 1", "tipo": "avaliacao_final"}, "tema": "Aspectos/camadas da segurança", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Para proteger a informação de forma holística, a organização deve equilibrar ferramentas que atuam em diferentes frentes de vulnerabilidade. Com base nisso, assinale a alternativa que apresenta apenas ferramentas voltadas aos aspectos lógicos e técnicos.", "alternativas": {"a": "Firewall, antivírus e criptografia.", "b": "Cerca elétrica, câmeras e alarmes.", "c": "Biometria, extintores e UPS.", "d": "Treinamento, RH e auditoria."}, "corretas": ["a"], "explicacao": "Firewall (filtra tráfego de rede), antivírus (detecta código malicioso) e criptografia (protege os dados) são todos controles lógicos/técnicos, que atuam em software e dados.", "por_que_erradas": {"b": "Cerca elétrica, câmeras e alarmes são todos controles físicos.", "c": "Mistura: biometria pode ser controle de acesso (físico ou lógico), mas extintores e UPS (no-break) são físicos/ambientais. Como a questão pede 'apenas' lógicos, está errada.", "d": "Treinamento, RH e auditoria são controles humanos/administrativos (gestão), não técnicos."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U2-Q01", "disciplina": "gsc", "unidade": 2, "origem": {"questionario": "2.5 Quiz", "tipo": "quiz"}, "tema": "Gestão de incidentes (fases)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Após um ataque de ransomware que paralisou as operações por 72 horas, a equipe de resposta conseguiu restaurar os sistemas a partir de backups. Qual fase do framework de gestão de incidentes deve ser conduzida imediatamente após a recuperação?", "alternativas": {"a": "Detecção e reporte", "b": "Contenção do incidente", "c": "Lições aprendidas", "d": "Planejamento e preparação"}, "corretas": ["c"], "explicacao": "A ordem clássica (NIST/ISO 27035) é: Preparação → Detecção e análise → Contenção → Erradicação → Recuperação → Lições aprendidas (atividade pós-incidente). Depois de recuperar os sistemas, a equipe analisa o que aconteceu, por que aconteceu e o que mudar para não se repetir.", "por_que_erradas": {"a": "Detecção e reporte acontecem no início: é quando o incidente é percebido. Aqui ele já foi resolvido.", "b": "Contenção vem antes da recuperação (isolar o ransomware para não se espalhar). Já passou.", "d": "Planejamento e preparação é a primeira fase do ciclo. As lições aprendidas alimentam uma nova preparação depois, mas não é a fase imediatamente seguinte à recuperação."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U2-Q02", "disciplina": "gsc", "unidade": 2, "origem": {"questionario": "2.5 Quiz", "tipo": "quiz"}, "tema": "Política de Segurança da Informação (PSI)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "O diretor de TI de uma empresa precisa apresentar à diretoria um argumento para a criação de uma Política de Segurança da Informação formal. Qual é o principal benefício estratégico da PSI que deve ser destacado?", "alternativas": {"a": "Estabelece diretrizes claras e responsabilidades, alinhando a segurança aos objetivos do negócio", "b": "Garante conformidade automática com todas as legislações vigentes.", "c": "Permite a eliminação completa de todos os riscos de segurança", "d": "Substitui a necessidade de investimentos em tecnologia de segurança."}, "corretas": ["a"], "explicacao": "A PSI é o documento-mestre da segurança: define regras, papéis e responsabilidades e mostra como a segurança apoia os objetivos do negócio. Esse alinhamento estratégico é o argumento para a diretoria.", "por_que_erradas": {"b": "Nenhuma política garante conformidade 'automática' com 'todas' as leis. Ela ajuda, mas exige implementação, monitoramento e atualização.", "c": "Risco zero não existe. A PSI reduz e gerencia riscos, não elimina 'completamente' 'todos'.", "d": "A PSI não substitui tecnologia; ela orienta onde e como investir. Política e controles técnicos se complementam."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U2-Q03", "disciplina": "gsc", "unidade": 2, "origem": {"questionario": "2.5 Quiz", "tipo": "quiz"}, "tema": "Gestão de riscos (priorização)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Uma empresa de comércio eletrônico identificou que seus servidores web estão expostos a ataques de força bruta, mas não possui recursos financeiros para implementar todas as correções simultaneamente. Considerando a gestão de riscos, qual abordagem deve ser priorizada?", "alternativas": {"a": "Desativar os servidores até que o orçamento seja aprovado.", "b": "Aplicar controles proporcionais ao risco, priorizando os ativos mais críticos.", "c": "Transferir toda a responsabilidade para o provedor de hospedagem.", "d": "Ignorar o risco até que um incidente ocorra para justificar o investimento."}, "corretas": ["b"], "explicacao": "Com recursos limitados, a gestão de riscos prioriza: trata primeiro os ativos mais críticos e os riscos mais altos (probabilidade × impacto), com controles proporcionais. É a mesma lógica de custo-benefício da Unidade 1.", "por_que_erradas": {"a": "Desligar os servidores de um e-commerce para o negócio. É indisponibilidade autoinfligida, não gestão de risco.", "c": "Pode-se transferir parte do risco (seguro, terceirização), mas não 'toda' a responsabilidade; a empresa continua responsável pelos dados (inclusive pela LGPD).", "d": "Ignorar risco conhecido esperando um incidente é negligência; 'aceitar o risco' só vale como decisão consciente e documentada, não para forçar orçamento."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U2-Q04", "disciplina": "gsc", "unidade": 2, "origem": {"questionario": "2.5 Quiz", "tipo": "quiz"}, "tema": "Desafios da PSI (segurança x usabilidade)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Uma organização implementou uma política que exige autenticação multifator para todos os sistemas, mas os colaboradores estão compartilhando tokens de autenticação por conveniência. Esse cenário ilustra qual desafio na implementação da PSI?", "alternativas": {"a": "Falta de recursos tecnológicos adequados.", "b": "Falha na segregação de funções do departamento de TI.", "c": "Desequilíbrio entre segurança e usabilidade, gerando contorno dos controles pelos usuários.", "d": "Ausência de regulamentação legal aplicável."}, "corretas": ["c"], "explicacao": "Quando um controle é incômodo demais, as pessoas criam 'atalhos' (compartilhar token, anotar senha no post-it). A tecnologia existe (MFA), mas o equilíbrio entre segurança e usabilidade falhou e o controle foi contornado. Liga-se ao fator humano.", "por_que_erradas": {"a": "A tecnologia existe e foi implementada (MFA). O problema é o uso, não a falta de recurso.", "b": "Segregação de funções é separar tarefas críticas entre pessoas diferentes dentro da TI. O cenário fala de usuários comuns compartilhando tokens.", "d": "Não há relação com lei: o desafio é comportamental, interno à organização."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U2-Q05", "disciplina": "gsc", "unidade": 2, "origem": {"questionario": "2.5 Quiz", "tipo": "quiz"}, "tema": "Gestão de incidentes (evento x incidente)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Uma instituição financeira detectou, através do seu SIEM, múltiplas tentativas de acesso a contas de clientes originadas de endereços IP de países onde a empresa não opera. Considerando o framework de gestão de incidentes, essa situação deve ser classificada inicialmente como:", "alternativas": {"a": "Um evento de segurança que deve ser avaliado para determinar se constitui um incidente.", "b": "Um incidente de segurança confirmado de severidade crítica.", "c": "Não há indícios que comprovem o falso positivo. O incidente deve ser investigado", "d": "Uma falha de sistema que requer manutenção preventiva."}, "corretas": ["a"], "explicacao": "Evento é qualquer ocorrência observável (alerta do SIEM, login falho). Incidente é um evento que, após análise (triagem), se confirma como ameaça real à segurança. A palavra-chave é 'inicialmente': primeiro se registra e avalia o evento, depois se decide se é incidente.", "por_que_erradas": {"b": "Ainda não está 'confirmado'. Pular a triagem e já chamar de crítico gera alarmes falsos e desperdiça a equipe.", "c": "Já chama a situação de 'incidente' antes da avaliação. A investigação é correta, mas a classificação inicial é de evento.", "d": "Tentativas de acesso de IPs estrangeiros são indício de ataque, não falha técnica de manutenção."}, "fonte_gabarito": "especialista", "observacao": "Questão em formato de múltiplas respostas (checkbox). A alternativa c tem redação diferente das outras e pode ter sido incluída pelo professor como correta também. Pela teoria, a classificação INICIAL é 'evento'; confirme no gabarito após o envio."}, {"id": "GSC-U2-Q06", "disciplina": "gsc", "unidade": 2, "origem": {"questionario": "2.7 Avaliação Final - Unidade 2", "tipo": "avaliacao_final"}, "tema": "Gestão de riscos (cálculo do risco)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A gestão de riscos de segurança da informação envolve a identificação sistemática de ameaças e vulnerabilidades que possam impactar os ativos organizacionais. Sobre o cálculo de risco, assinale a alternativa correta.", "alternativas": {"a": "O risco é determinado exclusivamente pelo valor monetário do ativo afetado.", "b": "Riscos com baixa probabilidade devem ser ignorados no processo de análise.", "c": "O risco é calculado pela relação entre ameaça e vulnerabilidade, considerando o impacto potencial.", "d": "A avaliação de riscos deve ser realizada apenas por empresas de consultoria externa."}, "corretas": ["c"], "explicacao": "Risco existe quando uma AMEAÇA pode explorar uma VULNERABILIDADE de um ativo, gerando um IMPACTO. Fórmula usual: Risco = Ameaça × Vulnerabilidade × Impacto (ou Probabilidade × Impacto). Sem vulnerabilidade, a ameaça não se concretiza; sem ameaça, a vulnerabilidade não é explorada.", "por_que_erradas": {"a": "'Exclusivamente' pelo valor do ativo ignora ameaça, vulnerabilidade e probabilidade. O valor do ativo entra no impacto, mas não é o único fator.", "b": "Baixa probabilidade não significa risco baixo: se o impacto for catastrófico, o risco pode ser alto (lembre da U1-Q12).", "d": "A avaliação pode e deve ser feita internamente (gestores conhecem o negócio); consultoria é opcional. O 'apenas' denuncia o erro."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U2-Q07", "disciplina": "gsc", "unidade": 2, "origem": {"questionario": "2.7 Avaliação Final - Unidade 2", "tipo": "avaliacao_final"}, "tema": "Análise de riscos (qualitativa x quantitativa)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A análise de riscos pode seguir abordagens quantitativas ou qualitativas. A respeito da abordagem qualitativa, assinale a alternativa correta.", "alternativas": {"a": "Baseia-se no conhecimento e na experiência do analista para classificar riscos por prioridade.", "b": "Utiliza exclusivamente cálculos matemáticos e estatísticos para determinar o nível de risco.", "c": "Produz resultados mais precisos do que a análise quantitativa em todos os cenários.", "d": "Requer investimento em ferramentas de simulação computacional avançada."}, "corretas": ["a"], "explicacao": "A análise QUALITATIVA usa escalas descritivas (baixo/médio/alto, matriz de probabilidade × impacto) e o julgamento/experiência dos analistas para priorizar riscos. É mais rápida e barata. A QUANTITATIVA usa valores numéricos e financeiros (ex.: ALE = SLE × ARO).", "por_que_erradas": {"b": "Cálculos matemáticos e estatísticos descrevem a análise quantitativa, não a qualitativa.", "c": "A qualitativa é mais subjetiva, logo geralmente menos precisa; e 'em todos os cenários' é absoluto.", "d": "Simulação computacional avançada é típica da quantitativa (ex.: Monte Carlo). A qualitativa é justamente a opção simples e de baixo custo."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U2-Q08", "disciplina": "gsc", "unidade": 2, "origem": {"questionario": "2.7 Avaliação Final - Unidade 2", "tipo": "avaliacao_final"}, "tema": "Gestão de incidentes (evento x incidente)", "tipo": "verdadeiro_falso", "multipla_resposta": false, "enunciado": "A ISO/IEC 27002 define que a organização deve estabelecer procedimentos claros para a gestão de incidentes de segurança da informação. Com base nisso, avalie se a informação a seguir é verdadeira ou falsa. Sobre a distinção entre evento e incidente de segurança, todo evento de segurança constitui um incidente.", "alternativas": {"a": "Verdadeiro", "b": "Falso"}, "corretas": ["b"], "explicacao": "Falso. Todo incidente é um evento, mas nem todo evento é um incidente. Evento é qualquer ocorrência observável (um login falho, um alerta). Ele só vira incidente quando, após avaliação, se confirma que compromete ou pode comprometer a segurança (CID). Mesma lógica da U2-Q05.", "por_que_erradas": {"a": "Se todo evento fosse incidente, cada login errado acionaria a equipe de resposta. A triagem existe justamente para separar eventos comuns de incidentes reais."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U2-Q09", "disciplina": "gsc", "unidade": 2, "origem": {"questionario": "2.7 Avaliação Final - Unidade 2", "tipo": "avaliacao_final"}, "tema": "Gestão de incidentes (preparação, ISO 27002 controle 5.24)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "O controle 5.24 da ISO/IEC 27002:2022 orienta o planejamento e a preparação da gestão de incidentes. Qual das alternativas a seguir representa uma ação recomendada na fase de preparação?", "alternativas": {"a": "Restringir o conhecimento dos procedimentos de resposta apenas ao departamento de TI.", "b": "Eliminar todos os sistemas de monitoramento para reduzir custos operacionais.", "c": "Designar responsabilidades claras e treinar uma equipe de resposta a incidentes (CSIRT).", "d": "Aguardar a ocorrência de um incidente para então definir os procedimentos de resposta."}, "corretas": ["c"], "explicacao": "Preparar é organizar tudo ANTES do incidente: definir papéis e responsabilidades, montar e treinar o CSIRT, criar procedimentos, canais de comunicação e ferramentas.", "por_que_erradas": {"a": "Todos precisam saber, ao menos, como reportar um incidente; restringir 'apenas' à TI atrasa a detecção.", "b": "Sem monitoramento não há detecção. Eliminar 'todos' é o oposto de se preparar.", "d": "Esperar o incidente para criar procedimentos é a negação da fase de preparação: na hora da crise não há tempo para planejar."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U2-Q10", "disciplina": "gsc", "unidade": 2, "origem": {"questionario": "2.7 Avaliação Final - Unidade 2", "tipo": "avaliacao_final"}, "tema": "Gestão de incidentes (contenção)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Durante o tratamento de um incidente de segurança, a fase de contenção tem como principal objetivo limitar a propagação e o impacto da ameaça. Qual ação é tipicamente realizada nesta fase?", "alternativas": {"a": "Publicar um comunicado de imprensa detalhando o incidente.", "b": "Isolar os sistemas afetados para evitar a disseminação do ataque.", "c": "Conduzir a análise de lições aprendidas com toda a equipe.", "d": "Aplicar patches de segurança em todos os servidores da organização."}, "corretas": ["b"], "explicacao": "Contenção = 'estancar o sangramento': desconectar da rede, isolar máquinas infectadas, bloquear contas/IPs, segmentar. O objetivo é impedir que o ataque se espalhe enquanto se prepara a erradicação.", "por_que_erradas": {"a": "Comunicação pública é parte da gestão de crise/comunicação e geralmente vem depois, com informações confirmadas; não limita a propagação.", "c": "Lições aprendidas é a última fase, após a recuperação (U2-Q01).", "d": "Aplicar patches é erradicação/correção da causa. E 'todos os servidores' de uma vez não é a ação imediata de contenção."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U2-Q11", "disciplina": "gsc", "unidade": 2, "origem": {"questionario": "2.7 Avaliação Final - Unidade 2", "tipo": "avaliacao_final"}, "tema": "Política de Segurança da Informação (PSI)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A Política de Segurança da Informação (PSI) é o documento estratégico que norteia todas as ações de proteção dos ativos informacionais. A PSI deve:", "alternativas": {"a": "ser construída exclusivamente pela equipe de TI, sendo um documento técnico.", "b": "ser um documento privado da organização, sendo protegido pelo sigilo.", "c": "ser aprovada pela alta direção e comunicada a todos os colaboradores da organização.", "d": "constar todos os procedimentos organizacionais referentes à TI."}, "corretas": ["c"], "explicacao": "A PSI precisa do apoio (aprovação) da alta direção para ter autoridade, e precisa ser divulgada a todos, pois todos devem cumpri-la. Ninguém cumpre uma regra que não conhece.", "por_que_erradas": {"a": "A PSI é estratégica, não um documento técnico, e deve envolver várias áreas (RH, jurídico, negócio, TI). 'Exclusivamente' denuncia o erro.", "b": "Se for sigilosa, os colaboradores não a conhecem e não podem cumpri-la. Detalhes técnicos sensíveis ficam em normas/procedimentos internos, não na PSI.", "d": "A PSI é de alto nível (diretrizes). Procedimentos detalhados ficam em documentos abaixo dela: normas e procedimentos operacionais."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U2-Q12", "disciplina": "gsc", "unidade": 2, "origem": {"questionario": "2.7 Avaliação Final - Unidade 2", "tipo": "avaliacao_final"}, "tema": "ISO/IEC 27002:2022 (categorias de controles)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A ISO/IEC 27002:2022 reorganizou seus controles em quatro categorias principais. Qual das alternativas apresenta corretamente essas categorias?", "alternativas": {"a": "Controles de rede, controles de aplicação, controles de banco de dados e controles de endpoint.", "b": "Controles preventivos, controles detectivos, controles corretivos e controles compensatórios.", "c": "Controles organizacionais, controles de pessoas, controles físicos e controles tecnológicos.", "d": "Controles financeiros, controles operacionais, controles estratégicos e controles táticos."}, "corretas": ["c"], "explicacao": "A versão 2022 da ISO/IEC 27002 tem 93 controles em 4 temas: Organizacionais (cláusula 5, 37 controles), Pessoas (cláusula 6, 8), Físicos (cláusula 7, 14) e Tecnológicos (cláusula 8, 34). Macete: O-P-F-T.", "por_que_erradas": {"a": "Rede, aplicação, banco de dados e endpoint são camadas técnicas, não as categorias da norma.", "b": "Preventivo, detectivo e corretivo são TIPOS (funções) de controle. A 27002:2022 até usa isso como atributo, mas não como as 4 categorias principais. É o distrator mais forte.", "d": "Financeiro, operacional, estratégico e tático são níveis/áreas de gestão, não categorias da norma."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U2-Q13", "disciplina": "gsc", "unidade": 2, "origem": {"questionario": "2.7 Avaliação Final - Unidade 2", "tipo": "avaliacao_final"}, "tema": "Tratamento de riscos (transferir)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Uma das estratégias de tratamento de riscos consiste em transferir o risco para terceiros. Qual das opções a seguir exemplifica essa estratégia?", "alternativas": {"a": "Contratar um seguro cibernético para cobrir perdas financeiras decorrentes de ataques.", "b": "Aceitar o risco e documentar a decisão no registro de riscos.", "c": "Implementar um firewall de próxima geração na rede corporativa.", "d": "Encerrar a operação do serviço que apresenta o risco identificado."}, "corretas": ["a"], "explicacao": "As 4 estratégias de tratamento: MITIGAR (reduzir com controles), TRANSFERIR (passar o impacto financeiro a terceiros: seguro, terceirização), ACEITAR (assumir conscientemente) e EVITAR (eliminar a atividade que gera o risco). Seguro cibernético é o exemplo clássico de transferência.", "por_que_erradas": {"b": "Aceitar e documentar é a estratégia de ACEITAÇÃO.", "c": "Implementar um firewall é MITIGAÇÃO (reduz a probabilidade).", "d": "Encerrar o serviço é EVITAR o risco."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U2-Q14", "disciplina": "gsc", "unidade": 2, "origem": {"questionario": "2.7 Avaliação Final - Unidade 2", "tipo": "avaliacao_final"}, "tema": "Gestão de incidentes (CSIRT)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Na estrutura organizacional para resposta a incidentes, o Computer Security Incident Response Team (CSIRT) desempenha um papel central. Sobre o CSIRT, é correto afirmar que:", "alternativas": {"a": "sua atuação se restringe ao monitoramento de redes, sem envolvimento na resposta.", "b": "opera de forma independente, sem necessidade de reportar à alta direção.", "c": "deve ser composto exclusivamente por profissionais de desenvolvimento de software.", "d": "é um grupo multidisciplinar responsável pela coordenação da resposta a incidentes de segurança."}, "corretas": ["d"], "explicacao": "O CSIRT reúne pessoas de várias áreas (segurança, infraestrutura, jurídico, comunicação, RH, gestão) porque um incidente afeta técnica, leis, imagem e pessoas. Seu papel é coordenar a resposta: detectar, conter, erradicar, recuperar e comunicar.", "por_que_erradas": {"a": "O 'R' de CSIRT é Response: ele atua na resposta, não só no monitoramento.", "b": "O CSIRT deve reportar à alta direção, que toma decisões de negócio (comunicar clientes, acionar seguro, notificar a ANPD).", "c": "'Exclusivamente' desenvolvedores contradiz o caráter multidisciplinar."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U2-Q15", "disciplina": "gsc", "unidade": 2, "origem": {"questionario": "2.7 Avaliação Final - Unidade 2", "tipo": "avaliacao_final"}, "tema": "Melhoria contínua da PSI (PDCA)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "O processo de melhoria contínua da Política de Segurança da Informação é essencial para mantê-la atualizada. Qual ciclo é recomendado como base para essa evolução constante?", "alternativas": {"a": "Ciclo ITIL (Incident, Transition, Implementation, Learning).", "b": "Ciclo PDCA (Plan, Do, Check, Act).", "c": "Ciclo OODA (Observe, Orient, Decide, Act).", "d": "Ciclo SDLC (Software Development Life Cycle)."}, "corretas": ["b"], "explicacao": "O PDCA (Planejar, Executar, Verificar, Agir) é a base da ISO/IEC 27001 para o SGSI e para a melhoria contínua da PSI (lembre da U1-Q11).", "por_que_erradas": {"a": "ITIL é um framework de gestão de serviços de TI, e essa sigla 'Incident, Transition, Implementation, Learning' é inventada; ITIL não é um ciclo com essas fases.", "c": "OODA é um ciclo de tomada de decisão rápida (origem militar), usado às vezes em resposta a incidentes, mas não é a base de melhoria contínua da PSI.", "d": "SDLC é o ciclo de vida de desenvolvimento de software, não de gestão de políticas."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U3-Q01", "disciplina": "gsc", "unidade": 3, "origem": {"questionario": "3.4 Quiz", "tipo": "quiz"}, "tema": "Tipos de ataque (DDoS)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Um site de vendas online ficou inacessível após receber tráfego massivo originado de milhares de computadores comprometidos em diversos países. Qual tipo de ataque foi realizado?", "alternativas": {"a": "Ataque DDoS (Distributed Denial of Service)", "b": "SYN Flood", "c": "SQL Injection", "d": "Phishing"}, "corretas": ["a"], "explicacao": "DDoS (negação de serviço distribuída) usa milhares de máquinas comprometidas (zumbis de uma botnet), espalhadas pelo mundo, para inundar o alvo de tráfego até derrubá-lo. 'Milhares de computadores comprometidos em diversos países' + 'site inacessível' = DDoS. Pilar afetado: disponibilidade.", "por_que_erradas": {"b": "SYN Flood é uma técnica específica de DoS (abusa do handshake TCP); pode até ser usada dentro de um DDoS, mas o enunciado destaca a origem distribuída, que define o DDoS.", "c": "SQL Injection insere comandos SQL maliciosos em formulários para ler/alterar o banco de dados. Afeta confidencialidade/integridade, não derruba o site por volume de tráfego.", "d": "Phishing é engenharia social por mensagens falsas para roubar dados; não gera tráfego massivo."}, "fonte_gabarito": "especialista", "gabarito_oficial_moodle": ["c"], "observacao": "ERRO NO GABARITO DO MOODLE: na tentativa 1 o sistema marcou DDoS como errado e indicou 'SQL Injection' como correta, mas o próprio feedback da alternativa DDoS descreve exatamente o cenário. SQL Injection não derruba site com tráfego. Mesmo tipo de erro da U1-Q02; vale pedir revisão."}, {"id": "GSC-U3-Q02", "disciplina": "gsc", "unidade": 3, "origem": {"questionario": "3.4 Quiz", "tipo": "quiz"}, "tema": "Engenharia social (personificação)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Um atacante ligou para o help desk de uma empresa se passando por um diretor de TI e, usando tom de autoridade e urgência, convenceu o atendente a resetar a senha de um administrador do sistema. Qual técnica de ataque foi empregada?", "alternativas": {"a": "Dumpster diving", "b": "Ataque de força bruta", "c": "Engenharia social por personificação", "d": "Phishing"}, "corretas": ["c"], "explicacao": "Personificação (pretexting/impersonation) é fingir ser outra pessoa — aqui, um diretor — explorando o princípio da autoridade e a urgência. É exatamente o caso do help desk da SecurePay.", "por_que_erradas": {"a": "Dumpster diving é vasculhar o lixo da empresa atrás de informações (papéis, mídias).", "b": "Força bruta é testar muitas senhas automaticamente; aqui a senha foi obtida por manipulação humana.", "d": "Phishing usa mensagens falsas (e-mail, SMS, links). O ataque foi por telefone com identidade falsa (seria 'vishing', mas a técnica central é a personificação)."}, "fonte_gabarito": "oficial"}, {"id": "GSC-U3-Q03", "disciplina": "gsc", "unidade": 3, "origem": {"questionario": "3.4 Quiz", "tipo": "quiz"}, "tema": "Pentest (tipos de teste)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Durante um teste de penetração autorizado, o auditor recebeu acesso completo ao código-fonte, documentação técnica e diagramas de rede da empresa. Que tipo de teste de penetração está sendo realizado?", "alternativas": {"a": "Red Team Testing", "b": "White Box Testing", "c": "Gray Box Testing", "d": "Black Box Testing"}, "corretas": ["b"], "explicacao": "White Box (caixa branca): o testador conhece TUDO (código, documentação, rede). Gray Box: conhece parte (ex.: um login de usuário comum). Black Box: não conhece nada, como um atacante externo.", "por_que_erradas": {"a": "Red Team simula um adversário real de forma ampla e furtiva (técnico, físico, social) para testar a capacidade de detecção e resposta; não se define pelo acesso total à documentação.", "c": "Gray Box é conhecimento parcial; aqui o acesso foi completo.", "d": "Black Box é sem nenhuma informação prévia, o oposto do cenário."}, "fonte_gabarito": "oficial"}, {"id": "GSC-U3-Q04", "disciplina": "gsc", "unidade": 3, "origem": {"questionario": "3.4 Quiz", "tipo": "quiz"}, "tema": "Malware (ransomware)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Um hospital teve seus sistemas paralisados após funcionários abrirem um anexo de e-mail aparentemente legítimo. Os arquivos médicos foram criptografados e os atacantes exigiram pagamento em Bitcoin para liberar o acesso. Que tipo de malware foi utilizado neste ataque?", "alternativas": {"a": "Cavalo de Tróia", "b": "Worm", "c": "Ransomware", "d": "Vírus de macro"}, "corretas": ["c"], "explicacao": "Ransomware criptografa os arquivos da vítima e exige resgate (ransom), geralmente em criptomoeda. 'Arquivos criptografados + pagamento em Bitcoin' = ransomware (caso HealthMed).", "por_que_erradas": {"a": "Cavalo de Tróia se disfarça de programa legítimo para abrir a porta ao atacante; pode até ser o meio de entrada, mas não é o que criptografa e pede resgate.", "b": "Worm se propaga sozinho pela rede; a característica descrita (sequestro de dados) é do ransomware.", "d": "Vírus de macro infecta documentos (Word/Excel) via macros; não define sequestro de dados com resgate."}, "fonte_gabarito": "oficial"}, {"id": "GSC-U3-Q05", "disciplina": "gsc", "unidade": 3, "origem": {"questionario": "3.4 Quiz", "tipo": "quiz"}, "tema": "Metodologia de ataque (reconhecimento)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Uma empresa de e-commerce sofreu um ataque em que hackers coletaram informações sobre a infraestrutura de TI através de redes sociais de funcionários e registros de domínio públicos, sem interagir diretamente com os sistemas. Qual fase da metodologia de ataques essa ação representa?", "alternativas": {"a": "Reconhecimento passivo", "b": "Escaneamento", "c": "Manutenção do acesso", "d": "Obtenção de acesso"}, "corretas": ["a"], "explicacao": "Reconhecimento passivo = coletar informações públicas (OSINT: redes sociais, LinkedIn, WHOIS, GitHub) SEM tocar nos sistemas do alvo. A pista é 'sem interagir diretamente'. Fases: Reconhecimento → Escaneamento → Obtenção de acesso → Manutenção do acesso → Cobertura de rastros/ações sobre o objetivo.", "por_que_erradas": {"b": "Escaneamento já interage com os sistemas (varredura de portas e serviços).", "c": "Manutenção do acesso ocorre depois da invasão (backdoors, escalada de privilégios).", "d": "Obtenção de acesso é a invasão em si (explorar vulnerabilidade, usar credenciais)."}, "fonte_gabarito": "oficial"}, {"id": "GSC-U3-Q06", "disciplina": "gsc", "unidade": 3, "origem": {"questionario": "3.6 Avaliação Final - Unidade 3", "tipo": "avaliacao_final"}, "tema": "Metodologia de ataque (escaneamento)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A metodologia de ataques a sistemas de informação é composta por cinco fases sequenciais. Sobre a fase de escaneamento, assinale a alternativa correta.", "alternativas": {"a": "Envolve a coleta de informações em redes sociais dos funcionários.", "b": "Tem como objetivo identificar vulnerabilidades específicas nos serviços e sistemas descobertos.", "c": "Foca na eliminação de evidências da presença do atacante.", "d": "Consiste na instalação de backdoors para acesso contínuo."}, "corretas": ["b"], "explicacao": "No escaneamento o atacante interage com o alvo para descobrir portas abertas, serviços, versões e vulnerabilidades específicas (ferramentas: Nmap, Nessus, OpenVAS). É a fase mais fácil de detectar, pois gera ruído nos logs/IDS.", "por_que_erradas": {"a": "Redes sociais = reconhecimento (fase 1).", "c": "Eliminar evidências = cobertura de rastros (última fase).", "d": "Backdoors = manutenção do acesso (fase 4)."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U3-Q07", "disciplina": "gsc", "unidade": 3, "origem": {"questionario": "3.6 Avaliação Final - Unidade 3", "tipo": "avaliacao_final"}, "tema": "Malware (worm x vírus)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Os worms se diferenciam dos vírus tradicionais por uma característica fundamental. Assinale a alternativa que identifica corretamente essa diferença.", "alternativas": {"a": "Worms só infectam documentos com macros.", "b": "Worms necessitam de arquivo hospedeiro para se propagar.", "c": "Worms não podem causar sobrecarga em sistemas.", "d": "Worms possuem capacidade de propagação autônoma através de redes."}, "corretas": ["d"], "explicacao": "Worm se autorreplica e se espalha sozinho pela rede, explorando vulnerabilidades, sem precisar de arquivo hospedeiro nem de ação do usuário. Vírus precisa se anexar a um arquivo/programa e ser executado.", "por_que_erradas": {"a": "Infectar documentos com macros é característica do vírus de macro.", "b": "É o contrário: quem precisa de hospedeiro é o vírus.", "c": "Worms frequentemente sobrecarregam redes e sistemas justamente pela replicação em massa."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U3-Q08", "disciplina": "gsc", "unidade": 3, "origem": {"questionario": "3.6 Avaliação Final - Unidade 3", "tipo": "avaliacao_final"}, "tema": "Engenharia social (princípios psicológicos)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A engenharia social explora vulnerabilidades no comportamento humano para obter acesso não autorizado. Qual dos princípios psicológicos abaixo é explorado quando um atacante se passa por um executivo para pressionar um funcionário?", "alternativas": {"a": "Curiosidade tecnológica.", "b": "Busca por eficiência.", "c": "Tendência de acreditar nas pessoas e deferir à autoridade.", "d": "Desejo de compartilhar informações."}, "corretas": ["c"], "explicacao": "Fingir ser executivo explora o princípio da AUTORIDADE: as pessoas tendem a confiar e obedecer a quem parece ter poder, sem questionar. Outros princípios comuns (Cialdini): urgência/escassez, reciprocidade, prova social, afinidade, compromisso.", "por_que_erradas": {"a": "Curiosidade é explorada em iscas (pendrive 'esquecido', link 'veja suas fotos'), não na personificação de chefe.", "b": "Busca por eficiência não é o gatilho principal; o funcionário cede por respeito/medo da autoridade.", "d": "Desejo de compartilhar existe, mas o cenário destaca a pressão hierárquica."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U3-Q09", "disciplina": "gsc", "unidade": 3, "origem": {"questionario": "3.6 Avaliação Final - Unidade 3", "tipo": "avaliacao_final"}, "tema": "Ethical hacking (autorização)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "No contexto do ethical hacking, qual é o requisito fundamental que diferencia um teste de penetração legítimo de uma invasão criminosa?", "alternativas": {"a": "A autorização explícita e documentada dos proprietários dos sistemas.", "b": "A capacidade técnica do profissional.", "c": "O relatório final entregue ao cliente.", "d": "O uso de ferramentas como Metasploit."}, "corretas": ["a"], "explicacao": "A diferença entre pentest e crime é a AUTORIZAÇÃO formal, por escrito, com escopo definido (o que pode ser testado, quando e como). As técnicas e ferramentas são as mesmas que um criminoso usaria; sem permissão, é invasão (no Brasil, Lei 12.737/2012, 'Lei Carolina Dieckmann').", "por_que_erradas": {"b": "Criminosos também podem ter alta capacidade técnica; habilidade não torna o ato legal.", "c": "O relatório é consequência de um teste legítimo, não o que o torna legítimo.", "d": "Metasploit é usado tanto por profissionais quanto por criminosos; a ferramenta não define a legalidade."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U3-Q10", "disciplina": "gsc", "unidade": 3, "origem": {"questionario": "3.6 Avaliação Final - Unidade 3", "tipo": "avaliacao_final"}, "tema": "Criptografia x esteganografia", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A criptografia e a esteganografia são técnicas distintas de proteção da informação. Sobre a diferença fundamental entre elas, assinale a alternativa correta.", "alternativas": {"a": "Ambas utilizam a mesma técnica de substituição de caracteres.", "b": "A criptografia oculta a existência da mensagem, enquanto a esteganografia transforma seu conteúdo.", "c": "A criptografia é mais antiga que a esteganografia.", "d": "A esteganografia oculta a existência da comunicação, enquanto a criptografia torna seu conteúdo ininteligível."}, "corretas": ["d"], "explicacao": "Esteganografia ESCONDE que existe uma mensagem (ex.: texto escondido nos pixels de uma imagem). Criptografia deixa claro que há uma mensagem, mas a torna ILEGÍVEL sem a chave. Macete: estegano = 'escondido'; cripto = 'embaralhado'.", "por_que_erradas": {"a": "São técnicas diferentes; esteganografia não depende de substituição de caracteres.", "b": "Inverteu as definições: é a pegadinha da questão.", "c": "A esteganografia é muito antiga (Grécia antiga: mensagens tatuadas no couro cabeludo, tabuletas com cera). Não é critério de diferença."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U3-Q11", "disciplina": "gsc", "unidade": 3, "origem": {"questionario": "3.6 Avaliação Final - Unidade 3", "tipo": "avaliacao_final"}, "tema": "História da criptografia (Vigenère)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A cifra de Vigenère representou um avanço significativo na história da criptografia. Qual característica principal a tornou superior às cifras monoalfabéticas?", "alternativas": {"a": "Era imune à análise de frequência por ser polialfabética.", "b": "Usava chaves de 256 bits.", "c": "Utilizava dispositivos eletromecânicos.", "d": "Foi desenvolvida por Alan Turing."}, "corretas": ["a"], "explicacao": "Cifras monoalfabéticas (como a de César) trocam cada letra sempre pela mesma, então a frequência das letras denuncia o texto. Vigenère é POLIALFABÉTICA: usa uma palavra-chave e a mesma letra pode virar letras diferentes, resistindo à análise de frequência simples (foi considerada 'indecifrável' por séculos, até Kasiski/Babbage no séc. XIX).", "por_que_erradas": {"b": "Chaves de 256 bits são da criptografia moderna (ex.: AES-256), não de uma cifra do século XVI.", "c": "Dispositivos eletromecânicos são da era da máquina Enigma (séc. XX).", "d": "Alan Turing atuou na quebra da Enigma na 2ª Guerra; Vigenère é do século XVI."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U3-Q12", "disciplina": "gsc", "unidade": 3, "origem": {"questionario": "3.6 Avaliação Final - Unidade 3", "tipo": "avaliacao_final"}, "tema": "RSA (fundamento matemático)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "O algoritmo RSA é amplamente utilizado em criptografia de chave pública. Sua segurança é fundamentada em qual problema matemático?", "alternativas": {"a": "Geração de números aleatórios.", "b": "Dificuldade computacional de fatorar números inteiros grandes em seus fatores primos.", "c": "Resolução de equações diferenciais.", "d": "Cálculo de logaritmos naturais."}, "corretas": ["b"], "explicacao": "No RSA é fácil multiplicar dois primos grandes, mas extremamente difícil fazer o caminho inverso (fatorar o produto). Essa assimetria de dificuldade protege a chave privada.", "por_que_erradas": {"a": "Números aleatórios são usados para gerar chaves, mas não são o problema que sustenta a segurança.", "c": "Equações diferenciais não têm relação com o RSA.", "d": "Logaritmo DISCRETO (não natural) é a base de Diffie-Hellman e ECC, não do RSA."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U3-Q13", "disciplina": "gsc", "unidade": 3, "origem": {"questionario": "3.6 Avaliação Final - Unidade 3", "tipo": "avaliacao_final"}, "tema": "Funções hash (propriedades)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Funções hash criptográficas são essenciais para a segurança da informação. Assinale a alternativa que apresenta uma propriedade fundamental dessas funções.", "alternativas": {"a": "Resistência a colisões: é computacionalmente inviável encontrar duas entradas distintas com o mesmo digest.", "b": "Produzem saídas de tamanho variável conforme a entrada.", "c": "São reversíveis, permitindo recuperar a mensagem original.", "d": "Requerem chave secreta para serem calculadas."}, "corretas": ["a"], "explicacao": "Propriedades do hash: tamanho FIXO de saída, determinismo, mão única (irreversível), efeito avalanche, resistência à pré-imagem, à segunda pré-imagem e a COLISÕES (difícil achar duas entradas com o mesmo hash).", "por_que_erradas": {"b": "A saída tem tamanho FIXO (SHA-256 sempre gera 256 bits), qualquer que seja a entrada.", "c": "Hash é de mão única: não dá para recuperar a mensagem a partir do hash.", "d": "Hash comum não usa chave; quem usa chave é o HMAC (hash com chave)."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U3-Q14", "disciplina": "gsc", "unidade": 3, "origem": {"questionario": "3.6 Avaliação Final - Unidade 3", "tipo": "avaliacao_final"}, "tema": "Criptografia híbrida (TLS)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "O protocolo TLS combina criptografia simétrica e assimétrica para comunicações seguras na Internet. Qual é a razão para essa abordagem híbrida?", "alternativas": {"a": "A criptografia assimétrica é utilizada para autenticação e troca de chaves, enquanto a simétrica cifra os dados com maior eficiência.", "b": "Ambas são usadas simultaneamente para cifrar cada byte.", "c": "A combinação elimina a necessidade de certificados digitais.", "d": "A criptografia simétrica é mais segura que a assimétrica."}, "corretas": ["a"], "explicacao": "A assimétrica resolve a troca segura de chaves e a autenticação (certificado), mas é lenta. A simétrica (AES) é rápida, mas precisa de uma chave combinada. O TLS usa a assimétrica no início (handshake) para combinar a chave de sessão e a simétrica para cifrar todo o tráfego.", "por_que_erradas": {"b": "Não se cifra cada byte com as duas; cada uma tem seu papel em momentos diferentes.", "c": "O TLS DEPENDE de certificados digitais para autenticar o servidor.", "d": "O motivo é desempenho, não 'segurança maior'. Ambas são seguras quando bem usadas."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U3-Q15", "disciplina": "gsc", "unidade": 3, "origem": {"questionario": "3.6 Avaliação Final - Unidade 3", "tipo": "avaliacao_final"}, "tema": "Computação quântica (Shor e pós-quântica)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A computação quântica representa uma ameaça potencial à criptografia moderna. Qual algoritmo quântico poderia quebrar o RSA e como a comunidade científica está respondendo?", "alternativas": {"a": "Algoritmo de Dijkstra, desenvolvendo firewalls quânticos.", "b": "Algoritmo de Shor, desenvolvendo criptografia pós-quântica baseada em reticulados.", "c": "Algoritmo de Grover, aumentando o tamanho das chaves simétricas para 512 bits.", "d": "Algoritmo de Turing, substituindo RSA por cifras monoalfabéticas."}, "corretas": ["b"], "explicacao": "O algoritmo de Shor fatora números grandes em tempo polinomial num computador quântico, quebrando RSA e ECC. A resposta é a criptografia pós-quântica (PQC); o NIST padronizou algoritmos baseados em reticulados (lattices), como CRYSTALS-Kyber (ML-KEM) e Dilithium (ML-DSA).", "por_que_erradas": {"a": "Dijkstra é um algoritmo clássico de menor caminho em grafos; 'firewall quântico' não é a resposta da comunidade.", "c": "Grover acelera a busca por força bruta e afeta a criptografia SIMÉTRICA (a resposta é dobrar a chave, ex.: AES-256), mas não quebra o RSA.", "d": "Não existe 'algoritmo quântico de Turing' para isso, e cifras monoalfabéticas são inseguras."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U4-Q01", "disciplina": "gsc", "unidade": 4, "origem": {"questionario": "4.4 Quiz", "tipo": "quiz"}, "tema": "Criptografia simétrica x assimétrica (desempenho)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Uma empresa de e-commerce precisa proteger as transações de pagamento de seus clientes. O arquiteto de segurança propõe usar apenas criptografia assimétrica (RSA) para cifrar todo o tráfego. Qual é o principal problema dessa abordagem?", "alternativas": {"a": "A criptografia assimétrica é 100-1000× mais lenta, tornando inviável cifrar todo o tráfego.", "b": "O RSA não pode ser usado em comunicações pela internet.", "c": "Não há problemas, pois o RSA é suficiente para todas as necessidades.", "d": "A criptografia assimétrica não garante confidencialidade."}, "corretas": ["a"], "explicacao": "A assimétrica é muito mais lenta que a simétrica. Por isso sistemas reais (TLS) são híbridos: RSA/ECDHE só para trocar a chave e AES para cifrar os dados.", "por_que_erradas": {"b": "O RSA é usado na internet o tempo todo (certificados, handshake TLS).", "c": "Há problema sim: desempenho. 'Suficiente para todas as necessidades' é absoluto.", "d": "A assimétrica garante confidencialidade (cifrar com a chave pública do destinatário); o problema é a velocidade."}, "fonte_gabarito": "oficial"}, {"id": "GSC-U4-Q02", "disciplina": "gsc", "unidade": 4, "origem": {"questionario": "4.4 Quiz", "tipo": "quiz"}, "tema": "Criptografia pós-quântica (harvest now, decrypt later)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Um banco está preocupado com a ameaça \"harvest now, decrypt later\", na qual atacantes capturam dados criptografados hoje para decifrá-los no futuro com computadores quânticos. Qual medida proativa é mais adequada para mitigar esse risco?", "alternativas": {"a": "Aumentar o tamanho das chaves RSA para 8192 bits.", "b": "Usar apenas criptografia simétrica AES-128.", "c": "Iniciar a migração para algoritmos de criptografia pós-quântica como CRYSTALS-Kyber.", "d": "Abandonar completamente o uso de criptografia."}, "corretas": ["c"], "explicacao": "Como os dados roubados hoje poderão ser decifrados no futuro, é preciso migrar desde já para algoritmos pós-quânticos (CRYSTALS-Kyber/ML-KEM, baseado em reticulados), resistentes ao algoritmo de Shor.", "por_que_erradas": {"a": "Aumentar a chave RSA só adia o problema; Shor quebra RSA de qualquer tamanho viável em tempo polinomial.", "b": "AES-128 fica enfraquecido pelo algoritmo de Grover (segurança efetiva cai para ~64 bits); o recomendado seria AES-256. E 'apenas simétrica' não resolve a troca de chaves.", "d": "Abandonar a criptografia exporia tudo imediatamente: absurdo."}, "fonte_gabarito": "oficial"}, {"id": "GSC-U4-Q03", "disciplina": "gsc", "unidade": 4, "origem": {"questionario": "4.4 Quiz", "tipo": "quiz"}, "tema": "Armazenamento de senhas (salt)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Um desenvolvedor precisa armazenar senhas de usuários em um banco de dados. Ele decide usar SHA-256 diretamente sobre as senhas. Qual vulnerabilidade essa implementação apresenta?", "alternativas": {"a": "Senhas iguais gerarão hashes idênticos, permitindo ataques de rainbow tables.", "b": "O SHA-256 é um algoritmo obsoleto e inseguro.", "c": "Uma organização recebe um arquivo importante por e-mail e deseja verificar se ele não foi adulterado durante o envio. O remetente forneceu o hash SHA-256 do arquivo original. Qual propriedade da função hash está sendo utilizada nessa verificação?", "d": "Não há vulnerabilidade; SHA-256 é adequado para armazenamento de senhas."}, "corretas": ["a"], "explicacao": "Sem salt, a mesma senha sempre gera o mesmo hash: o atacante usa tabelas pré-calculadas (rainbow tables) e descobre senhas comuns de vários usuários de uma vez. Além disso, SHA-256 é rápido demais, facilitando força bruta. Correto: bcrypt, Argon2 ou PBKDF2, com salt aleatório por usuário.", "por_que_erradas": {"b": "SHA-256 não é obsoleto; é seguro para integridade. O problema é usá-lo puro, sem salt, para senhas.", "c": "Não é uma resposta: é o texto de outra questão colado por engano.", "d": "Há vulnerabilidade: falta de salt e algoritmo rápido demais para senhas."}, "fonte_gabarito": "oficial", "observacao": "A alternativa c no Moodle é, por erro do professor, uma cópia do enunciado de outra questão (U4-Q05). Mantida como está."}, {"id": "GSC-U4-Q04", "disciplina": "gsc", "unidade": 4, "origem": {"questionario": "4.4 Quiz", "tipo": "quiz"}, "tema": "Nuvem (responsabilidade compartilhada, IaaS)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Uma empresa está migrando seus servidores para a nuvem e o CISO levantou preocupações sobre a segurança dos dados. Considerando o modelo de responsabilidade compartilhada, em um modelo IaaS, a criptografia dos dados em repouso é responsabilidade de quem?", "alternativas": {"a": "Da autoridade certificadora.", "b": "Exclusivamente do provedor de nuvem.", "c": "Do fabricante do hardware dos servidores.", "d": "Do cliente (organização)."}, "corretas": ["d"], "explicacao": "No IaaS o provedor cuida da infraestrutura física (prédio, hardware, rede, virtualização). Sistema operacional, aplicações, dados, criptografia e controle de acesso ficam com o CLIENTE. Quanto mais 'gerenciado' o serviço (IaaS → PaaS → SaaS), mais responsabilidade passa ao provedor, mas os DADOS são sempre responsabilidade do cliente.", "por_que_erradas": {"a": "A autoridade certificadora emite certificados digitais; não criptografa os dados do cliente.", "b": "'Exclusivamente' do provedor contradiz o modelo de responsabilidade compartilhada.", "c": "O fabricante do hardware não tem relação com os dados do cliente."}, "fonte_gabarito": "oficial"}, {"id": "GSC-U4-Q05", "disciplina": "gsc", "unidade": 4, "origem": {"questionario": "4.4 Quiz", "tipo": "quiz"}, "tema": "Funções hash (integridade, segunda pré-imagem)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Uma organização recebe um arquivo importante por e-mail e deseja verificar se ele não foi adulterado durante o envio. O remetente forneceu o hash SHA-256 do arquivo original. Qual propriedade da função hash está sendo utilizada nessa verificação?", "alternativas": {"a": "Criptografia simétrica do conteúdo.", "b": "Verificação de integridade por resistência à segunda pré-imagem.", "c": "Autenticação da identidade do remetente.", "d": "Garantia de confidencialidade dos dados."}, "corretas": ["b"], "explicacao": "Resistência à segunda pré-imagem: dado um arquivo, é inviável criar OUTRO arquivo com o mesmo hash. Assim, se o hash do arquivo recebido bate com o original, ele não foi alterado: integridade.", "por_que_erradas": {"a": "Hash não é criptografia: não cifra o conteúdo nem tem chave.", "c": "Hash sozinho não prova QUEM enviou; para autenticidade é preciso assinatura digital ou HMAC.", "d": "O arquivo continua legível; hash não oferece confidencialidade."}, "fonte_gabarito": "oficial"}, {"id": "GSC-U4-Q06", "disciplina": "gsc", "unidade": 4, "origem": {"questionario": "4.6 Avaliação Final", "tipo": "avaliacao_final"}, "tema": "Nuvem (ISO 27002, SLAs)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A computação em nuvem opera sob o modelo de responsabilidade compartilhada entre provedor e cliente. Segundo a ISO/IEC 27002, qual é uma recomendação fundamental para segurança em ambientes de nuvem?", "alternativas": {"a": "Armazenar dados exclusivamente em um único data center para simplificar a gestão.", "b": "Transferir toda a responsabilidade de segurança exclusivamente ao provedor.", "c": "Estabelecer SLAs que contemplem requisitos de segurança e criptografia de dados.", "d": "Eliminar completamente o uso de criptografia para reduzir latência."}, "corretas": ["c"], "explicacao": "A ISO 27002:2022 (controle 5.23, segurança no uso de serviços em nuvem) orienta definir em contrato/SLA os requisitos de segurança: criptografia, disponibilidade, notificação de incidentes, localização dos dados, auditoria e saída do serviço.", "por_que_erradas": {"a": "Um único data center é ponto único de falha; boas práticas pedem redundância.", "b": "Responsabilidade é compartilhada; 'toda' e 'exclusivamente' denunciam o erro.", "d": "Eliminar criptografia expõe os dados; latência não justifica abrir mão de segurança."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U4-Q07", "disciplina": "gsc", "unidade": 4, "origem": {"questionario": "4.6 Avaliação Final", "tipo": "avaliacao_final"}, "tema": "RSA (características)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A criptografia assimétrica resolveu o problema histórico de distribuição de chaves ao introduzir o conceito de pares de chaves. Sobre o algoritmo RSA, é correto afirmar que:", "alternativas": {"a": "É utilizado exclusivamente para cifragem de dados, sem aplicação em assinaturas digitais.", "b": "Foi desenvolvido na década de 1990 como substituto do AES.", "c": "Sua segurança baseia-se na dificuldade de fatorar números inteiros grandes.", "d": "Utiliza chaves idênticas para cifrar e decifrar mensagens."}, "corretas": ["c"], "explicacao": "RSA (Rivest, Shamir e Adleman, 1977) é assimétrico (par de chaves pública/privada) e sua segurança vem da dificuldade de fatorar o produto de dois primos grandes (mesmo conceito da U3-Q12).", "por_que_erradas": {"a": "RSA é muito usado em assinaturas digitais (assina com a chave privada, verifica com a pública).", "b": "RSA é de 1977; o AES é de 2001. RSA nem é do mesmo tipo (assimétrico x simétrico).", "d": "Chaves idênticas = criptografia simétrica. RSA usa par de chaves diferentes."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U4-Q08", "disciplina": "gsc", "unidade": 4, "origem": {"questionario": "4.6 Avaliação Final", "tipo": "avaliacao_final"}, "tema": "Criptografia pós-quântica (CRYSTALS-Kyber)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A criptografia pós-quântica busca algoritmos resistentes a ataques por computadores quânticos. O CRYSTALS-Kyber, selecionado pelo NIST como padrão primário para criptografia de chave pública pós-quântica, é baseado em:", "alternativas": {"a": "Curvas elípticas sobre corpos finitos.", "b": "Fatoração de números primos grandes.", "c": "Reticulados criptográficos (lattice-based).", "d": "Logaritmos discretos em grupos cíclicos."}, "corretas": ["c"], "explicacao": "Kyber (padronizado como ML-KEM) é baseado em reticulados (problema Module-LWE), que não tem solução eficiente conhecida nem em computadores quânticos.", "por_que_erradas": {"a": "Curvas elípticas são a base do ECC, que o algoritmo de Shor também quebra.", "b": "Fatoração é a base do RSA, vulnerável a Shor.", "d": "Logaritmo discreto é base de Diffie-Hellman/ECC, também vulnerável a Shor."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U4-Q09", "disciplina": "gsc", "unidade": 4, "origem": {"questionario": "4.6 Avaliação Final", "tipo": "avaliacao_final"}, "tema": "Criptografia simétrica (AES)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A criptografia simétrica utiliza a mesma chave para cifragem e decifragem, sendo amplamente aplicada em cenários que demandam alto desempenho. Sobre os algoritmos de criptografia simétrica, é correto afirmar que:", "alternativas": {"a": "O AES é o padrão atual adotado pelo NIST, suportando chaves de 128, 192 ou 256 bits.", "b": "O RSA é o principal exemplo de algoritmo simétrico utilizado em comunicações seguras.", "c": "A criptografia simétrica é mais lenta que a assimétrica em todos os cenários.", "d": "Algoritmos simétricos não necessitam de gerenciamento de chaves entre as partes."}, "corretas": ["a"], "explicacao": "O AES (Advanced Encryption Standard, NIST 2001) é o padrão simétrico atual, com chaves de 128, 192 ou 256 bits. Substituiu o DES/3DES.", "por_que_erradas": {"b": "RSA é ASSIMÉTRICO.", "c": "É o contrário: a simétrica é muito mais RÁPIDA (U4-Q01).", "d": "O maior desafio da simétrica é justamente distribuir e gerenciar a chave secreta entre as partes."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U4-Q10", "disciplina": "gsc", "unidade": 4, "origem": {"questionario": "4.6 Avaliação Final", "tipo": "avaliacao_final"}, "tema": "Inteligência artificial (uso ofensivo)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A inteligência artificial apresenta uso dual na segurança da informação, podendo fortalecer defesas ou sofisticar ataques. Um exemplo de uso ofensivo da IA é:", "alternativas": {"a": "A resposta automatizada a incidentes de segurança.", "b": "A geração de e-mails de phishing altamente personalizados por modelos de linguagem.", "c": "A priorização automatizada de patches de segurança.", "d": "A detecção de anomalias em tráfego de rede."}, "corretas": ["b"], "explicacao": "Uso ofensivo = a IA a serviço do atacante. Modelos de linguagem geram phishing convincente, sem erros de português e personalizado para cada vítima (spear phishing em escala). Outros exemplos: deepfakes de voz/vídeo e malware polimórfico.", "por_que_erradas": {"a": "Resposta automatizada (SOAR) é uso DEFENSIVO.", "c": "Priorizar patches é uso DEFENSIVO (gestão de vulnerabilidades).", "d": "Detecção de anomalias (UEBA, IDS com ML) é uso DEFENSIVO."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U4-Q11", "disciplina": "gsc", "unidade": 4, "origem": {"questionario": "4.6 Avaliação Final", "tipo": "avaliacao_final"}, "tema": "Funções hash (resistência a colisões)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Funções hash criptográficas possuem propriedades essenciais para garantir a segurança da informação. A propriedade que torna computacionalmente inviável encontrar duas entradas distintas que produzam o mesmo hash é denominada:", "alternativas": {"a": "Determinismo.", "b": "Resistência a colisões.", "c": "Resistência à pré-imagem.", "d": "Efeito avalanche."}, "corretas": ["b"], "explicacao": "Colisão = duas entradas DIFERENTES com o MESMO hash. Resistência a colisões = ser inviável encontrar qualquer par assim. (Segunda pré-imagem: dada UMA entrada específica, achar outra com o mesmo hash — U4-Q05.)", "por_que_erradas": {"a": "Determinismo: a mesma entrada sempre gera o mesmo hash.", "c": "Resistência à pré-imagem: dado um hash, é inviável descobrir a entrada que o gerou (mão única).", "d": "Efeito avalanche: mudar 1 bit na entrada muda drasticamente o hash."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U4-Q12", "disciplina": "gsc", "unidade": 4, "origem": {"questionario": "4.6 Avaliação Final", "tipo": "avaliacao_final"}, "tema": "Computação quântica (algoritmo de Shor)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "O algoritmo de Shor, executado em um computador quântico suficientemente poderoso, representa uma ameaça significativa para a criptografia atual porque:", "alternativas": {"a": "Elimina a necessidade de chaves criptográficas.", "b": "Torna todas as funções hash completamente inseguras.", "c": "Pode quebrar qualquer tipo de criptografia, incluindo simétrica e assimétrica.", "d": "Pode fatorar números inteiros grandes em tempo polinomial, quebrando RSA e ECC."}, "corretas": ["d"], "explicacao": "Shor resolve fatoração e logaritmo discreto em tempo polinomial, quebrando a criptografia ASSIMÉTRICA atual (RSA, ECC, Diffie-Hellman). Simétrica e hash são afetadas apenas parcialmente (pelo algoritmo de Grover), o que se resolve dobrando o tamanho da chave/saída.", "por_que_erradas": {"a": "Shor não elimina chaves; ele descobre a chave privada a partir da pública.", "b": "Shor não afeta hashes de forma relevante; Grover apenas reduz a segurança deles.", "c": "'Qualquer tipo' é exagero: AES-256 e SHA-384/512 continuam considerados seguros."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U4-Q13", "disciplina": "gsc", "unidade": 4, "origem": {"questionario": "4.6 Avaliação Final", "tipo": "avaliacao_final"}, "tema": "Certificados digitais (X.509, PKI)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Os certificados digitais são componentes fundamentais da Infraestrutura de Chave Pública (PKI). Sobre certificados X.509, é correto afirmar que:", "alternativas": {"a": "Dispensam verificação de cadeia de confiança hierárquica.", "b": "São emitidos e assinados por Autoridades Certificadoras (CAs) confiáveis.", "c": "Não possuem prazo de validade, sendo permanentes.", "d": "Contêm apenas a chave privada do titular para fins de autenticação."}, "corretas": ["b"], "explicacao": "O certificado X.509 liga uma identidade (pessoa, empresa, site) a uma CHAVE PÚBLICA e é assinado digitalmente por uma Autoridade Certificadora confiável (no Brasil, cadeia ICP-Brasil). Ele tem validade, pode ser revogado e é verificado pela cadeia de confiança.", "por_que_erradas": {"a": "A verificação da cadeia de confiança (raiz → intermediária → certificado) é essencial.", "c": "Certificados têm data de validade e podem ser revogados (CRL/OCSP).", "d": "O certificado contém a chave PÚBLICA. A chave privada NUNCA vai no certificado; fica só com o titular."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U4-Q14", "disciplina": "gsc", "unidade": 4, "origem": {"questionario": "4.6 Avaliação Final", "tipo": "avaliacao_final"}, "tema": "Criptografia híbrida (TLS)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Sistemas híbridos combinam criptografia simétrica e assimétrica para obter vantagens de ambas as abordagens. No protocolo TLS, a criptografia assimétrica é utilizada para:", "alternativas": {"a": "Estabelecer a chave de sessão simétrica de forma segura.", "b": "Realizar verificação de integridade dos pacotes transmitidos.", "c": "Substituir completamente a criptografia simétrica.", "d": "Cifrar todo o tráfego de dados da sessão."}, "corretas": ["a"], "explicacao": "No handshake do TLS, a criptografia assimétrica (RSA/ECDHE + certificado) serve para autenticar o servidor e combinar com segurança a chave de sessão. Depois, o AES (simétrico) cifra o tráfego. Mesmo conceito da U3-Q14 e U4-Q01.", "por_que_erradas": {"b": "Integridade dos pacotes é feita por MAC/AEAD (ex.: AES-GCM, HMAC), não pela assimétrica.", "c": "Não substitui: as duas trabalham juntas.", "d": "Cifrar todo o tráfego é papel da SIMÉTRICA, por ser mais rápida."}, "fonte_gabarito": "especialista"}, {"id": "GSC-U4-Q15", "disciplina": "gsc", "unidade": 4, "origem": {"questionario": "4.6 Avaliação Final", "tipo": "avaliacao_final"}, "tema": "Armazenamento de senhas (salt)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Sobre o armazenamento seguro de senhas, a prática recomendada utiliza funções de derivação de chave como bcrypt ou Argon2. A principal razão para usar salt aleatório em conjunto com o hash é:", "alternativas": {"a": "Prevenir ataques de rainbow tables, garantindo hashes únicos mesmo para senhas idênticas.", "b": "Aumentar a velocidade de verificação das senhas.", "c": "Permitir que senhas possam ser recuperadas em texto claro quando necessário.", "d": "Reduzir o tamanho do digest armazenado no banco de dados."}, "corretas": ["a"], "explicacao": "O salt é um valor aleatório diferente para cada usuário, adicionado à senha antes do hash. Assim, duas pessoas com a senha '123456' terão hashes diferentes, e tabelas pré-calculadas (rainbow tables) ficam inúteis. Complementa a U4-Q03.", "por_que_erradas": {"b": "O salt não acelera nada; bcrypt/Argon2 são até propositalmente LENTOS para dificultar força bruta.", "c": "Hash é irreversível: nem com salt é possível recuperar a senha original.", "d": "O salt não reduz o tamanho do hash; ele ainda precisa ser armazenado junto."}, "fonte_gabarito": "especialista"}, {"id": "EAG-U1-Q01", "disciplina": "eag", "unidade": 1, "origem": {"questionario": "Quiz - Fundamentos Computacionais", "tipo": "quiz"}, "tema": "Operadores lógicos e rastreamento de condição aninhada", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Algoritmos | Tema: Operadores lógicos e rastreamento de condição aninhada\n\n  \n\n    Um painel luminoso é representado por uma matriz quadrada de ordem n, com n ímpar. A cor de cada célula é definida pela atribuição a cor[i,j]. A função par(x) devolve verdadeiro quando x é um número par. O trecho a seguir foi escrito para produzir um padrão no painel e será executado com n = 5.\n\n  \n  Trecho de código\n  \n    m = (n + 1) / 2\npara i = 1 até n faça\n    para j = 1 até n faça\n        se ( (par(i) e par(j)) e ( (i - j = 0) ou ((i + j) = (n + 1))\n                                   ou (i = m) ou (j = m) ) ) então\n            cor[i,j] = preto\n        senão\n            cor[i,j] = branco\n        fimse\n    fimpara\nfimpara\n  \n  \n    Rastreando a execução do trecho para n = 5, as células pretas do painel são", "alternativas": {"a": "quatro, nos cruzamentos das linhas pares com as colunas pares, formando um quadrado interno ao painel.", "b": "duas, sobre a diagonal principal, nas posições em que o índice de linha é igual ao índice de coluna.", "c": "dezessete, distribuídas pelas duas diagonais, pela linha central e pela coluna central do painel.", "d": "nove, nas diagonais e no cruzamento central, restritas às linhas e colunas de índice ímpar."}, "corretas": ["a"], "explicacao": "Correta. O filtro de paridade restringe i e j a {2, 4}; os quatro pares resultantes satisfazem uma das condições de diagonal, e as condições de linha e coluna central nunca se aplicam, pois m = 3 é ímpar.\n\nO ponto decisivo é a conjunção externa. A condição geométrica — diagonal principal, diagonal secundária, linha central ou coluna central — só é avaliada depois que par(i) e par(j) resulta verdadeiro. Com n = 5, isso restringe i e j ao conjunto {2, 4}, ou seja, a quatro pares possíveis.\n    Testando os quatro: (2,2) e (4,4) satisfazem i − j = 0; (2,4) e (4,2) satisfazem i + j = 6 = n + 1. As condições i = m e j = m nunca se verificam, porque m = 3 é ímpar e i e j já foram restringidos a valores pares. O resultado é um quadrado interno de quatro células. Quem lê o ou antes do e enxerga um X sobreposto a uma cruz e conta 17 células.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-U1-Q02", "disciplina": "eag", "unidade": 1, "origem": {"questionario": "Quiz - Fundamentos Computacionais", "tipo": "quiz"}, "tema": "Estrutura de decisão e definição de faixa inclusiva", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Algoritmos | Tema: Estrutura de decisão e definição de faixa inclusiva\n\n  \n\n    Uma distribuidora de energia concede desconto de 12% na fatura aos clientes residenciais cujo consumo mensal fique entre 150 kWh e 300 kWh, incluídos os dois limites. Fora dessa faixa, o sistema apenas informa que o cliente não tem direito ao desconto. O analista escreveu o algoritmo a seguir e deixou a linha 06 em aberto.\n\n  \n  Algoritmo em elaboração\n  \n    01: algoritmo \"desconto_residencial\"\n02: var\n03:     consumo, desconto : real\n04: inicio\n05:     leia(consumo)\n06:     se (_______) entao\n07:         desconto := (consumo * 12) / 100\n08:         escreva(\"Desconto concedido: \", desconto)\n09:     senao\n10:         escreva(\"Consumo fora da faixa de desconto.\")\n11:     fimse\n12: fimalgoritmo\n  \n  \n    A linha 06 que atende à regra do desconto, nos termos definidos pela distribuidora, é", "alternativas": {"a": "se ((consumo >= 150.00) ou (consumo <= 300.00)) entao", "b": "se ((consumo > 150.00) e (consumo < 300.00)) entao", "c": "se ((consumo >= 150.00) e (consumo <= 300.00)) entao", "d": "se ((leitura >= 150.00) e (leitura <= 300.00)) entao"}, "corretas": ["c"], "explicacao": "Correta. A conjunção exige que as duas comparações sejam satisfeitas simultaneamente, e os operadores com igualdade preservam os dois limites da faixa, como determina a regra.\n\nA regra tem duas exigências que decidem o item: as duas condições precisam valer ao mesmo tempo, e os dois limites pertencem à faixa. Isso obriga ao operador e e aos operadores >= e <=.\n    Trocar e por ou produz uma expressão sempre verdadeira: qualquer consumo é maior que 150 ou menor que 300, de modo que todo cliente receberia desconto. Usar > e < exclui justamente 150 kWh e 300 kWh, que a regra manda incluir. E referenciar uma variável não declarada no bloco var impede a execução do algoritmo.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-U1-Q03", "disciplina": "eag", "unidade": 1, "origem": {"questionario": "Quiz - Fundamentos Computacionais", "tipo": "quiz"}, "tema": "Equação de tempo de CPU e escolha de processador sob restrição de janela", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Arquitetura de computadores | Tema: Equação de tempo de CPU e escolha de processador sob restrição de janela\n\n  \n\n    Uma rede de farmácias executa a rotina de fechamento contábil durante a madrugada. A rotina processa 2,4 × 1012 instruções em um servidor cujo processador opera a 2,5 GHz, com CPI médio de 2,0. O código roda em um único fluxo sequencial e não há versão paralela prevista para o exercício.\n    O contrato com a matriz passou a exigir que o fechamento termine em até 25 minutos. O monitoramento do servidor registra uso de processador próximo de 100% durante toda a execução, fila de disco praticamente nula e os dados do fechamento já residentes em memória. A equipe de TI dispõe de verba para uma única substituição de componente.\n\n  \n  \n    Aplicando a equação de tempo de CPU aos dados apresentados, a substituição que atende ao prazo contratado é", "alternativas": {"a": "processador de 3,0 GHz com a mesma microarquitetura, que preserva o CPI médio de 2,0 e o número de instruções da rotina.", "b": "processador de 2,5 GHz com microarquitetura que reduz o CPI médio para 1,4, preservando o número de instruções da rotina.", "c": "processador de 2,5 GHz com o dobro de núcleos, que preserva o CPI médio de 2,0 e o número de instruções da rotina.", "d": "subsistema de armazenamento com discos SSD em RAID 10, que preserva o processador de 2,5 GHz e o CPI médio de 2,0."}, "corretas": ["b"], "explicacao": "Correta. Com CPI 1,4 e período de 0,4 ns, o tempo cai para 1.344 s, dentro dos 1.500 s. O CPI é fator da equação com o mesmo peso da frequência.\n\nO tempo de CPU resulta do produto entre número de instruções, CPI e período do clock. Na configuração atual, o período é 1 / 2,5 GHz = 0,4 ns, e o tempo é 2,4 × 1012 × 2,0 × 0,4 ns = 1.920 s, ou 32 minutos. O prazo de 25 minutos corresponde a 1.500 s.\n    Elevar a frequência para 3,0 GHz reduz o período para cerca de 0,333 ns e o tempo para 1.600 s, ou 26 minutos e 40 segundos: ganho real, porém insuficiente. Reduzir o CPI médio para 1,4 mantendo os 2,5 GHz leva a 2,4 × 1012 × 1,4 × 0,4 ns = 1.344 s, ou 22 minutos e 24 segundos, dentro da janela.\n    As demais opções atuam sobre fatores que não limitam esta carga. Núcleos adicionais não aceleram um fluxo sequencial, conforme a lei de Amdahl, porque a fração paralelizável é nula. O armazenamento também não é o recurso crítico: o processador permanece saturado, a fila de disco é nula e os dados já estão em memória.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-U1-Q04", "disciplina": "eag", "unidade": 1, "origem": {"questionario": "Quiz - Fundamentos Computacionais", "tipo": "quiz"}, "tema": "Virtualização: consolidação de ambientes e limites de desempenho", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Sistemas operacionais | Tema: Virtualização: consolidação de ambientes e limites de desempenho\n\n  \n\n    Uma transportadora mantém três ambientes de homologação, cada um exigindo um sistema operacional diferente, e um sistema de roteirização que processa o cálculo das rotas da madrugada com uso intensivo de CPU e memória. Hoje cada ambiente ocupa um servidor próprio, e os quatro equipamentos estão subutilizados fora dos horários de pico.\n    A diretoria vetou a compra de novos servidores no exercício. O servidor disponível para consolidação tem 128 GB de memória. Cada ambiente de homologação requer 24 GB; a roteirização requer 64 GB e tem janela de execução fixa, com prazo contratual de entrega das rotas às 5h.\n\n  \n  \n    Considerando as restrições de orçamento, de memória e de janela de processamento, a decisão adequada é", "alternativas": {"a": "consolidar os três ambientes de homologação como máquinas virtuais no servidor disponível e manter a roteirização executando diretamente sobre o hardware.", "b": "virtualizar também a roteirização no mesmo servidor, uma vez que a camada de virtualização intermedeia o acesso ao processador e eleva o desempenho da carga hospedada.", "c": "instalar os três ambientes de homologação sobre um mesmo sistema operacional no servidor disponível, separando-os por contas de usuário e diretórios distintos.", "d": "virtualizar os quatro sistemas no servidor disponível, reservando a cada máquina virtual a mesma quantidade de memória hoje instalada em seu servidor de origem."}, "corretas": ["a"], "explicacao": "Correta. A consolidação aproveita a ociosidade dos ambientes de homologação e preserva o isolamento entre sistemas operacionais distintos, enquanto a carga com janela fixa permanece sem a sobrecarga da camada de virtualização.\n\nA camada de virtualização divide os recursos da máquina física entre as instâncias e acrescenta sobrecarga de gerenciamento. Isso é vantajoso para cargas intermitentes, que raramente disputam recursos ao mesmo tempo, e desvantajoso para uma carga que precisa do máximo de CPU dentro de uma janela fixa.\n    Os três ambientes de homologação somam 72 GB e têm uso irregular: cabem com folga no servidor de 128 GB e ganham isolamento, já que cada máquina virtual roda seu próprio sistema operacional. A roteirização, com 64 GB e prazo contratual, é a carga que não se beneficia do compartilhamento. Separar as duas naturezas resolve o problema sem comprar equipamento.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-U1-Q05", "disciplina": "eag", "unidade": 1, "origem": {"questionario": "Quiz - Fundamentos Computacionais", "tipo": "quiz"}, "tema": "Funções do núcleo e camadas do sistema operacional", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Sistemas operacionais | Tema: Funções do núcleo e camadas do sistema operacional\n\n  \n\n    Uma startup de logística avalia em qual plataforma móvel concentrará o desenvolvimento de seu aplicativo. O tecnólogo em gestão da TI recebeu da diretoria o anúncio de atualização publicado por um fabricante e precisa separar o que é mudança de interface do que é mudança de arquitetura do sistema operacional.\n\n  \n  \n    Do anúncio do fabricante: “A versão traz nova tela inicial e nova tela de bloqueio, acionada quando o aparelho é suspenso. O aplicativo de fotos reconhece rostos e exibe imagens sobre um mapa. O assistente de linguagem natural foi aberto a desenvolvedores externos, o que permite acionar serviços de terceiros por comando de voz.”\n  \n  \n    A leitura tecnicamente correta do anúncio, quanto à arquitetura do sistema operacional, é a de que", "alternativas": {"a": "o núcleo teve suas funções básicas ampliadas, o que eleva a capacidade de processamento dos aplicativos independentemente da arquitetura do dispositivo.", "b": "o núcleo passou a residir em dispositivo externo à memória principal, o que libera espaço para a execução simultânea de mais processos.", "c": "as mudanças descritas pertencem às camadas de aplicação e de interface, enquanto o núcleo segue encarregado de escalonar processos e gerenciar a memória.", "d": "a gerência de memória deixou de ser tratada pelo módulo de escalonamento do núcleo, o que explica o ganho de desempenho relatado."}, "corretas": ["c"], "explicacao": "Correta. Tela inicial, galeria e assistente de voz são processos executados sobre os serviços do sistema. A divisão de responsabilidades do núcleo permanece inalterada.\n\nNenhum dos recursos anunciados é função de núcleo. Tela inicial, tela de bloqueio, reconhecimento de rostos e assistente de voz são aplicações e serviços de alto nível, executados como processos comuns sobre as interfaces que o sistema oferece.\n    O núcleo continua responsável pelo que sempre lhe coube: escalonar processos, gerenciar memória, controlar o acesso a dispositivos e intermediar as chamadas de sistema. Ampliar o conjunto de aplicativos não altera essa divisão, não aumenta a capacidade de processamento do dispositivo e não transfere a gerência de memória para fora do núcleo. O núcleo tampouco reside fora da memória principal: ele é carregado nela na inicialização e ali permanece.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-U2-Q01", "disciplina": "eag", "unidade": 2, "origem": {"questionario": "Quiz - Desenvolvimento de Soluções Digitais", "tipo": "quiz"}, "tema": "Consulta SQL com junção, agregação e agrupamento", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Banco de dados | Tema: Consulta SQL com junção, agregação e agrupamento\n\n  \n\n    Uma rede de farmácias registra suas vendas em três tabelas. tb_farmaceutico guarda o identificador e o nome de cada farmacêutico; tb_venda guarda o identificador da venda, a data e o farmacêutico responsável; tb_item_venda guarda os itens de cada venda, com quantidade e valor unitário. Uma venda sempre tem um ou mais itens.\n    A direção pediu um relatório com o ano, o nome do farmacêutico, a quantidade de vendas realizadas e o valor total vendido, no formato a seguir.\n\n  \n  Relatório solicitado\n  \n    \n      AnoFarmacêuticoQuantidade de vendasValor total\n      2025Ana Ribeiro41298 740,00\n      2025Bruno Teles37785 120,00\n      2026Ana Ribeiro26871 905,00\n    \n  \n  \n    Assinale a consulta SQL que produz corretamente o relatório solicitado.", "alternativas": {"a": "SELECT EXTRACT(YEAR FROM v.dt_venda) AS ano, f.ds_nome AS farmaceutico, COUNT(v.id_venda) AS qtd_vendas, SUM(i.qt_item * i.vl_unitario) AS total_vendas FROM tb_farmaceutico f INNER JOIN tb_venda v ON f.id_farmaceutico = v.id_farmaceutico INNER JOIN tb_item_venda i ON v.id_venda = i.id_venda GROUP BY EXTRACT(YEAR FROM v.dt_venda), f.ds_nome ORDER BY 1, 2;", "b": "SELECT EXTRACT(YEAR FROM v.dt_venda) AS ano, f.ds_nome AS farmaceutico, COUNT(DISTINCT v.id_venda) AS qtd_vendas, SUM(i.qt_item * i.vl_unitario) AS total_vendas FROM tb_farmaceutico f INNER JOIN tb_venda v ON f.id_farmaceutico = v.id_farmaceutico INNER JOIN tb_item_venda i ON v.id_venda = i.id_venda GROUP BY EXTRACT(YEAR FROM v.dt_venda), f.ds_nome ORDER BY 1, 2;", "c": "SELECT EXTRACT(YEAR FROM v.dt_venda) AS ano, f.ds_nome AS farmaceutico, COUNT(DISTINCT v.id_venda) AS qtd_vendas, SUM(i.qt_item * i.vl_unitario) AS total_vendas FROM tb_farmaceutico f INNER JOIN tb_venda v ON f.id_farmaceutico = v.id_farmaceutico INNER JOIN tb_item_venda i ON v.id_venda = i.id_venda GROUP BY v.dt_venda, f.ds_nome ORDER BY 1, 2;", "d": "SELECT EXTRACT(YEAR FROM v.dt_venda) AS ano, f.ds_nome AS farmaceutico, COUNT(DISTINCT v.id_venda) AS qtd_vendas, SUM(i.qt_item * i.vl_unitario) AS total_vendas FROM tb_farmaceutico f INNER JOIN tb_venda v ON f.id_farmaceutico = v.id_farmaceutico INNER JOIN tb_item_venda i ON v.id_venda = i.id_venda GROUP BY f.ds_nome ORDER BY 1, 2;"}, "corretas": ["b"], "explicacao": "Correta. O DISTINCT neutraliza a repetição de linhas provocada pela junção com os itens, a soma percorre todos os itens como deve, e o agrupamento repete exatamente as duas colunas não agregadas do SELECT.\n\nA consulta precisa resolver três exigências ao mesmo tempo: agrupar por ano e por farmacêutico, contar vendas e não itens, e somar o valor de todos os itens. A junção com tb_item_venda multiplica cada venda pelo número de itens que ela possui, e é justamente essa multiplicação que obriga ao uso de COUNT(DISTINCT v.id_venda). A soma não sofre com isso, porque cada item deve mesmo ser somado uma vez.\n    O agrupamento também precisa reproduzir exatamente as colunas não agregadas do SELECT. Agrupar pela data completa gera uma linha por dia, e omitir o ano do GROUP BY torna a consulta inválida na maioria dos SGBDs, entre eles PostgreSQL, Oracle, SQL Server e o MySQL configurado com ONLY_FULL_GROUP_BY. Vale registrar que a extração do ano foi escrita em sintaxe padrão (EXTRACT); funções como YEAR() existem no MySQL e no SQL Server, mas não pertencem ao padrão ANSI e comprometem a portabilidade da consulta.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-U2-Q02", "disciplina": "eag", "unidade": 2, "origem": {"questionario": "Quiz - Desenvolvimento de Soluções Digitais", "tipo": "quiz"}, "tema": "Estratégia de testes em sistema integrado e de alta concorrência", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Engenharia de software | Tema: Estratégia de testes em sistema integrado e de alta concorrência\n\n  \n\n    Uma instituição de ensino vai substituir seu sistema de matrícula on-line. O novo sistema tem as características a seguir.\n\n  \n  Características do sistema\n  \n    \n      integra-se ao sistema acadêmico, ao gateway de pagamento e ao serviço de emissão de boletos;\n      será entregue em incrementos quinzenais, com novas funcionalidades e ajustes nas já entregues;\n      concentra, nos cinco dias do período de matrícula, praticamente toda a demanda do semestre, com milhares de estudantes acessando o sistema ao mesmo tempo.\n    \n  \n  \n    Diante dessas características, a estratégia de testes deve priorizar testes de", "alternativas": {"a": "unidade, usabilidade e instalação, porque verificam cada função isolada, a experiência de uso e a implantação do sistema no ambiente definitivo da instituição.", "b": "caixa branca, mesa e alfa, porque percorrem a estrutura interna do código e permitem que a própria equipe valide o produto em ambiente controlado antes da entrega.", "c": "integração, regressão automatizada e carga, porque cobrem a comunicação com os serviços externos, o que já foi entregue e o comportamento do sistema no pico de acessos.", "d": "usabilidade, documentação e portabilidade, porque asseguram a clareza das telas, a qualidade dos manuais e a execução do sistema em diferentes navegadores."}, "corretas": ["c"], "explicacao": "Correta. Os três tipos respondem, um a um, às três características do sistema: as integrações, a entrega incremental com alteração do que já existe e a concentração da demanda no período de matrícula.\n\nCada característica do sistema aponta para um tipo de teste. As integrações com três serviços externos exigem teste de integração, que verifica a comunicação entre os módulos e com os sistemas de terceiros. A entrega em incrementos quinzenais, que altera funcionalidades já entregues, exige teste de regressão; como ele se repete a cada entrega, a automação no pipeline de integração contínua deixa de ser conveniência e vira condição de viabilidade. E a concentração da demanda em cinco dias exige teste de carga, que submete o sistema ao volume de acessos simultâneos esperado no pico.\n    Os demais tipos de teste não são inúteis, apenas não respondem aos riscos descritos no enunciado. A estratégia de testes deriva das características do sistema e do projeto, não de uma lista fixa aplicada a qualquer contexto.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-U2-Q03", "disciplina": "eag", "unidade": 2, "origem": {"questionario": "Quiz - Desenvolvimento de Soluções Digitais", "tipo": "quiz"}, "tema": "Modelo em cascata e desenvolvimento incremental: momento da validação", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Engenharia de software | Tema: Modelo em cascata e desenvolvimento incremental: momento da validação\n\n  \n\n    Uma autarquia municipal vai desenvolver um sistema de licenciamento de obras. A parte regulatória do escopo está fixada em lei e não admite interpretação da equipe: prazos, documentos exigidos e ordem dos trâmites estão escritos na norma. Já a interface de atendimento ao cidadão e os relatórios gerenciais da fiscalização não têm forma definida, e os próprios servidores afirmam que só saberão dizer o que precisam depois de usar uma primeira versão.\n    A equipe discute se adota o modelo em cascata ou o desenvolvimento incremental.\n\n  \n  \n    Com base nos dois modelos de processo de software, assinale a opção correta.", "alternativas": {"a": "O desenvolvimento incremental é o mais adequado à interface e aos relatórios, porque cada incremento é validado pelo cliente logo após ser construído, enquanto a cascata concentra a validação ao final.", "b": "O modelo em cascata é o mais adequado ao projeto inteiro, porque a documentação completa dos requisitos antes da implementação impede que o escopo mude no decorrer do desenvolvimento do sistema contratado.", "c": "O desenvolvimento incremental dispensa a atividade de especificação de requisitos, já que o cliente corrige o produto a cada entrega até que ele atenda às necessidades da autarquia e dos cidadãos.", "d": "Os dois modelos submetem o software à validação do cliente com a mesma frequência, e a diferença entre eles está apenas no volume de documentação produzida ao longo do processo de desenvolvimento."}, "corretas": ["a"], "explicacao": "Correta. O ponto está no momento da validação. A parte do escopo cujos requisitos só se revelam pelo uso se beneficia do retorno rápido do cliente a cada incremento, que é exatamente o que a sequência de fases da cascata adia.\n\nA diferença decisiva entre os dois modelos está no momento em que o cliente valida o que foi construído. No modelo em cascata, as atividades de especificação, projeto, implementação e validação ocorrem em fases distintas e sequenciais, de modo que o erro de entendimento cometido na especificação só aparece ao final. No desenvolvimento incremental, essas atividades se intercalam, e cada incremento devolve ao cliente algo utilizável, o que antecipa a descoberta do mal-entendido enquanto corrigi-lo ainda é barato.\n    Daí a escolha sugerida pelo caso: a parte regulatória tem requisitos estáveis, escritos em norma, e tolera bem um processo sequencial; a interface e os relatórios têm requisitos que só se revelam pelo uso e pedem incrementos. Nenhum dos dois modelos dispensa a especificação, e nenhum deles impede que os requisitos mudem.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-U2-Q04", "disciplina": "eag", "unidade": 2, "origem": {"questionario": "Quiz - Desenvolvimento de Soluções Digitais", "tipo": "quiz"}, "tema": "Integração de processos transacionais por sistema integrado de gestão", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Sistemas de informações gerenciais | Tema: Integração de processos transacionais por sistema integrado de gestão\n\n  \n\n    Uma distribuidora emite cerca de 40 000 notas fiscais por mês, cada uma com vários itens. O contas a receber e a contabilidade operam em sistemas distintos, que não trocam dados entre si. Hoje, a equipe financeira exporta os recebimentos para uma planilha, classifica cada cliente pelo código contábil e redigita os lançamentos no sistema contábil.\n    O fechamento atrasa em média doze dias, a conciliação acumula divergências e a direção não dispõe do saldo contábil atualizado para decidir sobre crédito a clientes. A diretoria quer eliminar a redigitação e passar a contar com o saldo no mesmo dia.\n\n  \n  \n    A situação descrita é um caso típico de problema a ser resolvido com", "alternativas": {"a": "uma solução de gestão eletrônica de documentos, que digitaliza, indexa e guarda as notas fiscais emitidas, tornando-as recuperáveis por cliente e por período de apuração.", "b": "um sistema integrado de gestão (ERP), em que o contas a receber e a contabilidade operam sobre a mesma base de dados e o recebimento gera o lançamento contábil.", "c": "um data warehouse, repositório orientado por assunto, integrado e não volátil, que consolida os dados dos dois sistemas para apoiar as decisões gerenciais da direção.", "d": "um conjunto de rotinas de automação robótica (RPA), que reproduz a digitação dos lançamentos no sistema contábil a partir da planilha que o financeiro exporta hoje."}, "corretas": ["b"], "explicacao": "Correta. A integração dos processos sobre uma base única elimina a redigitação, que é a causa do atraso e das divergências, e mantém o saldo contábil atualizado no momento em que a transação ocorre.\n\nO problema não é de análise nem de guarda de documentos: é de integração entre processos transacionais. O recebimento registrado no contas a receber precisa gerar o lançamento contábil correspondente sem intervenção manual, e isso se obtém com um sistema integrado de gestão (ERP), em que os módulos compartilham a mesma base de dados e atualizam o saldo no momento da transação.\n    Vale notar que o mesmo resultado pode ser obtido pela integração de sistemas especializados por meio de APIs, arranjo cada vez mais comum, e que a adoção de ERP hoje se dá predominantemente em nuvem, por assinatura e com adesão ao processo padrão do fornecedor. O que distingue a solução correta das demais é atacar a origem do retrabalho, e não os seus sintomas.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-U2-Q05", "disciplina": "eag", "unidade": 2, "origem": {"questionario": "Quiz - Desenvolvimento de Soluções Digitais", "tipo": "quiz"}, "tema": "Padronização de domínios e transformação na carga da plataforma analítica", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Tecnologias para inteligência de negócio | Tema: Padronização de domínios e transformação na carga da plataforma analítica\n\n  \n\n    Uma rede hospitalar vai implantar uma plataforma analítica para acompanhar indicadores assistenciais. Os dados virão de dois sistemas transacionais adquiridos de fornecedores diferentes, que seguirão em operação e continuarão atendendo às regras de cada unidade.\n    Na análise, descobriu-se que os dois sistemas registram o mesmo atributo de formas distintas, conforme o quadro a seguir. Outros sistemas da rede já consomem esses dados e dependem do formato atual de cada um.\n\n  \n  Representação do sexo do paciente nos sistemas de origem\n  \n    \n      Sistema de origemMasculinoFemininoNão informado\n      Sistema A (unidades próprias)MFcampo vazio\n      Sistema B (unidades conveniadas)129\n    \n  \n  \n    Nesse contexto, a providência correta no projeto da plataforma analítica é", "alternativas": {"a": "armazenar os dois formatos na tabela de fatos e deixar que cada relatório converta os códigos no momento da consulta, conforme a necessidade de quem o utiliza.", "b": "exigir dos dois fornecedores a alteração dos sistemas transacionais, de modo que ambos passem a adotar o mesmo código antes do início da carga na plataforma.", "c": "registrar a sigla do sistema de origem na tabela de fatos, de forma que cada usuário interprete o código do atributo conforme o sistema que o tiver gerado.", "d": "definir um domínio padronizado no projeto da plataforma e converter os códigos na etapa de transformação da carga, mantendo a origem como metadado de linhagem."}, "corretas": ["d"], "explicacao": "Correta. A padronização é decidida no projeto da plataforma e aplicada uma única vez na transformação, o que entrega dados conciliados a todos os consumidores. A origem permanece registrada como linhagem, para auditoria e rastreio.\n\nA plataforma analítica não pode impor seu formato aos sistemas de origem, que seguem em operação com regras próprias, nem repassar a conversão a quem consome os indicadores. A conciliação pertence à etapa de transformação do processo de carga, onde se aplica um domínio padronizado definido no projeto da plataforma. É indiferente que a transformação ocorra antes da carga, no modelo ETL, ou depois dela, no modelo ELT adotado pelas plataformas em nuvem: o que não pode é deixar de existir.\n    Guardar o sistema de origem continua sendo boa prática, mas como metadado de linhagem, que permite auditar de onde veio cada registro. Essa informação complementa a padronização e não a substitui, porque indicador calculado sobre códigos não conciliados produz contagens erradas, independentemente de se saber a origem de cada linha.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-U3-Q01", "disciplina": "eag", "unidade": 3, "origem": {"questionario": "Quiz - Gestão de Tecnologia e Projetos", "tipo": "quiz"}, "tema": "Gerenciamento de projetos (TAP, premissas, restrições e marcos)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Teoricamente, o termo de abertura de projetos (TAP) é atribuição do\npatrocinador. Nele, o gerente de projetos deveria ser nomeado. Entretanto, a realidade\naponta para um cenário bem diferente: os gerentes de projetos são comumente chamados para\nparticipar da elaboração do termo, mesmo em suas versões iniciais. Nesse momento, em boa\nparte das metodologias implantadas, é preciso elaborar um documento que sintetiza a visão do\nprojeto, contendo, total ou parcialmente, as seguintes sessões: justificativa; objetivos;\nrequisitos (visão); riscos (visão inicial); cronograma de marcos; orçamento resumido;\ndesignação do gerente de projetos e do patrocinador; premissas e restrições.\nUm patrocinador deseja apresentar um projeto de melhoria de processos de um\ndatacenter voltado para a recuperação de desastres. Nessa fase, o TAP está sendo\nfinalizado. As reuniões para aprovação do orçamento, que só será apreciado no fim do\nplanejamento, ocorrerão nos dois meses seguintes e, geralmente, duram dois dias\nconsecutivos, dado o grande número de projetos a serem apreciados. A diretoria já definiu\nque não será aprovado um orçamento acima de R$ 5 milhões para nenhum projeto isolado. A\nequipe de projetos espera receber todas as especificações até o fim do mês em curso para\nentregar o planejamento no prazo combinado.\nCom base nessa situação e considerando a necessidade de ajustar o TAP, avalie as\nafirmações a seguir.\n\nO valor de R$ 5 milhões representa uma restrição para o projeto.\nA aprovação do orçamento é um marco importante para esse projeto.\nA aprovação do orçamento deverá ser declarada no cronograma de marcos, informando-se um\nmarco com duração de dois dias.\n\nÉ correto o que se afirma em", "alternativas": {"a": "I, apenas.", "b": "I e II, apenas.", "c": "II e III, apenas.", "d": "I, II e III."}, "corretas": ["b"], "explicacao": "Correta. O teto de R$ 5 milhões é restrição e a aprovação do orçamento é marco.\n\nCobra a distinção entre premissa, restrição e marco, tratada na seção 3.2 do capítulo 10, e a propriedade de o marco ter duração zero.Fonte: ENADE 2017, questão 13. Adaptada para quatro alternativas; no original o gabarito era C.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-U3-Q02", "disciplina": "eag", "unidade": 3, "origem": {"questionario": "Quiz - Gestão de Tecnologia e Projetos", "tipo": "quiz"}, "tema": "ITIL 4 (boas práticas de serviços)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A ITIL (Information Technology Infrastructure Library) é um\nconjunto de boas práticas para a gestão de serviços de TI. Na versão em vigor, organiza o\nconhecimento em 34 práticas de gerenciamento, articuladas por um sistema de valor que\nconverte demanda e oportunidade em valor para o cliente. Sua adoção pode proporcionar ganhos\nna qualidade dos serviços e na redução de riscos e custos.\nA respeito da ITIL e de suas recomendações, assinale a opção\ncorreta.", "alternativas": {"a": "A implementação da prática de gerenciamento de nível de serviço é a atribuição principal da central de serviços, que representa a interface operacional entre a área de TI e seus usuários.", "b": "A prática de gerenciamento de incidentes exige ação proativa das equipes de suporte, que devem monitorar a infraestrutura para identificar possíveis falhas antes que elas ocorram.", "c": "Ganhos de desempenho no atendimento podem ser obtidos com uma base de erros conhecidos, que registra problemas já analisados, com a causa identificada e uma solução de contorno disponível, enquanto a correção definitiva ainda não foi implantada.", "d": "O escalonamento de um incidente não resolvido no primeiro nível transfere para a equipe acionada a responsabilidade pelo registro e pela comunicação com o usuário, encerrando a atuação da central de serviços."}, "corretas": ["c"], "explicacao": "Correta. Erro conhecido é problema analisado e ainda não resolvido; a solução de contorno é obtida pelo gerenciamento de problemas e aplicada pelo de incidentes.\n\nTrata de práticas preservadas nas três gerações da ITIL, tratadas nas seções 3.3 e 3.4 do capítulo 12. Atenção ao vocabulário: o que a geração v3 chamava de processo é hoje prática, e a central de serviços deixou de ser função.Fonte: inspirada no ENADE 2017, questão 14. Enunciado e alternativas editados para a versão vigente da ITIL; o gabarito original era D.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-U3-Q03", "disciplina": "eag", "unidade": 3, "origem": {"questionario": "Quiz - Gestão de Tecnologia e Projetos", "tipo": "quiz"}, "tema": "Liderança em projetos", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Pode-se definir liderança como a capacidade de influenciar um grupo para\nalcançar metas. A origem dessa influência pode ser formal, como a que é conferida por um\nalto cargo na organização. Como essas posições remetem a um certo grau de autoridade, uma\npessoa pode assumir um papel de liderança apenas em função do cargo que ocupa. Nem todos os\nlíderes são administradores e nem todos os executivos são líderes. O fato de a organização\nconferir a seus executivos alguns direitos formais não lhes assegura a capacidade de\nliderança eficaz. A liderança não sancionada, aquela capaz de influenciar os outros, que\nemerge fora da estrutura formal da organização, geralmente é tão importante quanto a\ninfluência formal, ou até mais.\nConsiderando essas informações, assinale a opção em que se caracteriza\ncorretamente a liderança na área de projetos.", "alternativas": {"a": "Gestores de projetos devem prezar pelo desenvolvimento das habilidades interpessoais dos membros de seu grupo, como a liderança e o trabalho em equipe, essenciais para o sucesso dos projetos e o alcance dos objetivos estratégicos.", "b": "Líderes com perfis mais autocráticos têm maior chance de sucesso no gerenciamento de projetos, visto que essa é uma atividade fundamental para que os objetivos estratégicos das organizações sejam alcançados.", "c": "Líderes devem manter o status quo, pois sua posição é resultado de uma escolha da administração que ele deve representar.", "d": "Líderes de projetos devem ter como características pessoais determinação, confiança e vontade, sendo-lhes dispensáveis as habilidades técnicas."}, "corretas": ["a"], "explicacao": "Correta. Liderança e trabalho em equipe são competências a desenvolver, e não atributos do cargo.\n\nÚnica questão de gestão de pessoas nas duas edições do exame. Dialoga com a seção 3.2 do capítulo 11, sobre liderança formal e informal.Fonte: ENADE 2017, questão 17, a partir de ROBBINS, S. P. Comportamento organizacional. Adaptada para quatro alternativas; o gabarito original era A.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-U3-Q04", "disciplina": "eag", "unidade": 3, "origem": {"questionario": "Quiz - Gestão de Tecnologia e Projetos", "tipo": "quiz"}, "tema": "Modelagem de processos (BPMN)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "O diagrama a seguir, em notação BPMN, representa graficamente o processo de\naquisição de matéria-prima de uma indústria, no qual apresenta-se o fluxo de trabalho entre\nseus setores e fornecedores. Destaca-se que, para atender normas de responsabilidade\nsocioambiental, a indústria trabalha somente com fornecedores homologados, ou seja, que\ncumprem requisitos técnicos e legais.\n\nCom base nessa situação e no processo representado, avalie as afirmações a\nseguir.\n\nO abastecimento do estoque e a autorização do pagamento ao fornecedor dependem da\naprovação resultante da conferência do material entregue no depósito.\nSomente depois de se distribuir a matéria-prima ao setor requisitante é que a\nautorização do pagamento será realizada.\nNo diagrama, são representados cinco momentos de decisão que, conforme seu resultado,\nestabelecem caminhos diferentes de prosseguimento do fluxo de atividades.\nA nota fiscal será recebida pelo depósito junto com a matéria-prima e será repassada ao\nfinanceiro somente depois da aprovação dessa matéria-prima.\nO processo seria otimizado se fosse criado e mantido um cadastro de fornecedores\nhomologados para se evitar a repetição das tarefas a cada requisição; com isso, somente\nnovos fornecedores exigiriam a execução de atividades de homologação.\n\nÉ correto apenas o que se afirma em", "alternativas": {"a": "I, III e IV.", "b": "I, IV e V.", "c": "II, III e V.", "d": "II, IV e V."}, "corretas": ["b"], "explicacao": "Correta. I e IV decorrem da aprovação na conferência; V propõe melhoria válida do processo.\n\nExercita a leitura de raias, gateways, fluxo de sequência e fluxo de mensagem, tratados nas seções 3.3 e 3.4 do capítulo 9.Fonte: ENADE 2017, Tecnologia em Gestão da Tecnologia da Informação, questão 18. Adaptada para quatro alternativas; no original o gabarito era C.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-U3-Q05", "disciplina": "eag", "unidade": 3, "origem": {"questionario": "Quiz - Gestão de Tecnologia e Projetos", "tipo": "quiz"}, "tema": "Computação em nuvem (SaaS e responsabilidade compartilhada)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A adoção de soluções baseadas em software como serviço (SaaS,\nSoftware as a Service) está consolidada nas organizações. São exemplos o Google\nWorkspace e o Salesforce.\nAcerca da arquitetura computacional de tecnologias baseadas em SaaS, avalie as\nasserções a seguir e a relação proposta entre elas.\nI. Os SaaS são soluções hospedadas na nuvem para uma grande quantidade\nde clientes, como uma alternativa ao processamento local.\nPORQUE\nII. Os softwares oferecidos como serviço são acessados pelos clientes\npor navegador ou por interface de programação, enquanto o gerenciamento da rede, dos\nsistemas operacionais, dos servidores e do armazenamento cabe ao provedor, restando ao\ncliente a responsabilidade por identidades, acessos, configurações e dados.\nA respeito dessas asserções, assinale a alternativa correta.", "alternativas": {"a": "As asserções I e II são proposições verdadeiras, e a II é uma justificativa correta da I.", "b": "As asserções I e II são proposições verdadeiras, mas a II não é uma justificativa correta da I.", "c": "A asserção I é uma proposição verdadeira, e a II é uma proposição falsa.", "d": "A asserção I é uma proposição falsa, e a II é uma proposição verdadeira."}, "corretas": ["a"], "explicacao": "Correta. A divisão de responsabilidade descrita em II é o que viabiliza substituir o processamento local, afirmado em I.\n\nA tabela de responsabilidade compartilhada da seção 3.8 do capítulo 12 detalha o que permanece com o cliente em cada modelo de serviço.Fonte: inspirada no ENADE 2021, questão 15. Enunciado e asserção II editados: marcas comerciais atualizadas, acesso por interface de programação acrescentado e responsabilidade do cliente explicitada. O gabarito original era A.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-U4-Q01", "disciplina": "eag", "unidade": 4, "origem": {"questionario": "Quiz - Estratégia, Processos e Responsabilidades", "tipo": "quiz"}, "tema": "Fragilidades organizacionais e princípios comprometidos", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Segurança da informação | Tema: Fragilidades organizacionais e princípios comprometidos\n\n  \n    Sabendo-se que, na área de segurança da informação, uma empresa pode apresentar inúmeras fragilidades, avalie as afirmações a seguir.\n    I.A instabilidade dos sistemas corporativos compromete a disponibilidade das informações.\n    II.Quando as informações presentes nas bases de dados corporativas possuem referência de sua fonte e/ou critério que permite sua validação, ocorre comprometimento em sua autenticidade.\n    III.Se a entrada de informações depende do atendimento de critérios de validação com base nos requisitos dos sistemas e nas regras de negócio, a integridade das informações é prejudicada.\n    IV.Compromete-se a confidencialidade da informação quando não há controle do seu uso pelos usuários, possibilitando a impressão e/ou cópia de informações do ambiente corporativo sem a identificação do usuário responsável ou da destinação de tal ação.\n  \n  \n    É correto apenas o que se afirma em", "alternativas": {"a": "I e IV.", "b": "II e III.", "c": "I, II e IV.", "d": "I, III e IV."}, "corretas": ["a"], "explicacao": "Correta. A instabilidade afeta a disponibilidade, e a falta de controle de uso afeta a confidencialidade. As afirmações II e III descrevem controles que preservam autenticidade e integridade, e não fragilidades.\n\nAs afirmações I e IV são verdadeiras. Sistemas instáveis impedem o uso da informação quando necessária, o que afeta a disponibilidade. Sem controle de uso, qualquer usuário pode copiar ou imprimir informação que não deveria circular, o que afeta a confidencialidade.\n    As afirmações II e III são falsas porque descrevem controles, e não fragilidades. A referência à fonte e o critério de validação permitem comprovar a origem da informação e preservam a autenticidade. A validação na entrada protege o conteúdo contra alteração indevida; é a sua ausência que compromete a integridade (Cap. 13, seções 3.1 e 5.1).", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-U4-Q02", "disciplina": "eag", "unidade": 4, "origem": {"questionario": "Quiz - Estratégia, Processos e Responsabilidades", "tipo": "quiz"}, "tema": "Alinhamento estratégico entre TI e negócio", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Gestão estratégica organizacional | Tema: Alinhamento estratégico entre TI e negócio\n\n  \n\n    As corporações que compreendem a importância da Tecnologia da Informação (TI) e do seu valor agregado entendem que os recursos de infraestrutura de TI precisam estar alinhados à estratégia de negócio. Esse alinhamento pode ser alcançado e mantido por meio de práticas de Governança de Tecnologia da Informação que estabeleçam papéis, controles e direções, assim como o atendimento a demandas de regulamentação e de negócio, gerenciando as expectativas de todos os interessados.\n\n  \n  ARAÚJO, A. P.; COSTA, I.; GONÇALVES, R. F. Gestão da Produção, Operações e Sistemas. Gepros, Bauru, ano 8, n. 3, p. 99-111, jul./set. 2013 (adaptado).\n  \n    Nesse contexto, considerando o alinhamento entre a TI e o planejamento estratégico das organizações, avalie as afirmações a seguir.\n    I.O alinhamento estratégico da TI com o negócio ocorre quando os investimentos e os projetos da TI contribuem para alcançar a missão, os objetivos e as estratégias organizacionais.\n    II.As tecnologias da informação podem estar a serviço de variados tipos de estratégias de negócio, por isso o planejamento estratégico da TI deve ser desenvolvido de forma independente, de modo a garantir flexibilidade no uso das tecnologias.\n    III.O apoio da alta administração aos projetos da TI é fator relevante que colabora para alcançar o alinhamento estratégico da TI com o negócio.\n    IV.Os projetos e as ações da TI nas organizações, quando alinhados ao negócio, colaboram também com o atendimento de demandas legais, sociais e ambientais a que a organização está sujeita.\n  \n  \n    É correto apenas o que se afirma em", "alternativas": {"a": "I e III.", "b": "I, II e IV.", "c": "I, III e IV.", "d": "I, II, III e IV."}, "corretas": ["c"], "explicacao": "Correta. O alinhamento depende da contribuição da TI para os objetivos organizacionais, do patrocínio da alta administração e do atendimento às obrigações legais e socioambientais. O planejamento independente da TI, descrito em II, é sintoma de desalinhamento.\n\nAs afirmações I, III e IV são verdadeiras. Alinhamento é a correspondência entre as decisões de TI e os objetivos do negócio (I). Patrocínio e envolvimento da alta administração estão entre as condições que o sustentam (III). Cada objetivo de TI deve ser rastreável a um objetivo organizacional ou a uma obrigação legal ou regulatória, e critérios ambientais e sociais passaram a integrar a decisão de investimento (IV).\n    A afirmação II é falsa. Um plano de TI elaborado isoladamente não reflete as prioridades reais do negócio, não tem autoridade para mudanças que atravessam departamentos e não garante os recursos necessários. Planejar a TI de forma independente é sintoma de desalinhamento (Cap. 14, seções 3.3, 3.4 e 3.8).", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-U4-Q03", "disciplina": "eag", "unidade": 4, "origem": {"questionario": "Quiz - Estratégia, Processos e Responsabilidades", "tipo": "quiz"}, "tema": "Controles gerais de TI e auditoria", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Governança de TI | Tema: Controles gerais de TI e auditoria\n\n  \n\n    Um auditor de TI deve ter um forte entendimento das técnicas de controle interno para cobrir muitas das tecnologias e processos presentes na empresa e, para tal, deve usar os controles gerais de TI, que cobrem todos os aspectos das operações de TI, como atividades de processamento, acesso a programas e dados, desenvolvimento e alterações de programas, controles de rede e muitos outros. Esses controles estão organizados em uma hierarquia dividida em três grupos: Controles Gerais de Governança, Controles Gerais de Gerenciamento e Controles Gerais de Ambiente Técnico.\n\n  \n  MOELLER, R. IT audit, control, and security. New Jersey: John Wiley & Sons, 2010 (adaptado).\n  \n    A respeito dos controles gerais de TI, avalie as afirmações a seguir.\n    I.Fazem parte do grupo de Governança de TI os controles que envolvem a garantia de princípios, políticas e processos eficazes de gerenciamento e segurança.\n    II.Fazem parte do grupo de Gerenciamento de TI os controles que cobrem áreas como desenvolvimento de sistemas, aquisição de software, documentação e procedimentos de controle.\n    III.Fazem parte do grupo de Ambiente Técnico de TI os controles que permitem uma compreensão da organização, de seus procedimentos de controle estabelecidos e dos deveres e responsabilidades especializados de qualquer operação.\n  \n  \n    É correto o que se afirma em", "alternativas": {"a": "I, apenas.", "b": "I e II, apenas.", "c": "II e III, apenas.", "d": "I, II e III."}, "corretas": ["b"], "explicacao": "Correta. Governança abrange políticas, princípios e gestão de riscos; gerenciamento abrange desenvolvimento, aquisição e documentação. Já a compreensão da organização e de suas responsabilidades, descrita em III, pertence à governança, e não ao ambiente técnico.\n\nA afirmação I é verdadeira: o nível de governança reúne políticas aprovadas pela direção, estrutura de decisão, gestão de riscos e definição de responsabilidades. A afirmação II é verdadeira: o nível de gerenciamento trata do ciclo de vida de sistemas e serviços, com desenvolvimento e aquisição, gestão de mudanças, acessos e documentação.\n    A afirmação III é falsa. Compreender a organização, seus procedimentos de controle e as responsabilidades de cada operação pertence ao nível de governança. O ambiente técnico cobre a configuração e a operação da infraestrutura: parâmetros de sistemas operacionais e bancos de dados, segurança de rede, rotinas de backup e monitoramento (Cap. 15, seção 3.7 e Figura 15.2).", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-U4-Q04", "disciplina": "eag", "unidade": 4, "origem": {"questionario": "Quiz - Estratégia, Processos e Responsabilidades", "tipo": "quiz"}, "tema": "Arranjos decisórios e alinhamento estratégico", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Governança de TI | Tema: Arranjos decisórios e alinhamento estratégico\n\n  \n\n    A unidade de Tecnologia da Informação (TI) de uma determinada empresa é vista como ruim, pois não produz níveis de serviço adequados. Há alguns meses, após a fusão dessa empresa com outra do mesmo ramo, foi nomeado um novo executivo, que se sente preocupado com o desempenho da unidade de TI e pretende melhorá-lo. Uma questão contínua é que novos produtos da empresa são introduzidos sem que a equipe de TI seja avisada, o que força situações que exigem construção de infraestrutura e elaboração dos sistemas de suporte necessários. Pelo fato de os produtos da empresa acumularem muitos dados e haver muitos clientes, um novo produto pode implicar um aumento repentino da demanda por serviços e infraestrutura de TI. É caro e difícil satisfazer essa demanda para esse fim específico, e os resultados alcançados têm gerado insatisfação contínua em relação à unidade de TI.\n\n  \n  HUNTER, R.; WESTERMAN, G. O verdadeiro valor de TI. São Paulo: M. Books, 2011 (adaptado).\n  \n    Com base nessa situação, avalie as asserções a seguir e a relação proposta entre elas.\n    I.A criação de um comitê composto exclusivamente pelo pessoal da área de TI, com autonomia para tomar as decisões que afetam as demandas por serviços e infraestrutura de TI, seria uma opção acertada.\n    PORQUE\n    II.A empresa possui um arranjo decisório inadequado para suas expectativas; a pouca credibilidade da área de TI e a falta de envolvimento dessa área nas decisões comprometem o alinhamento estratégico entre a TI e o negócio, problema relacionado à governança de TI.\n  \n  \n    A respeito dessas asserções, assinale a opção correta.", "alternativas": {"a": "As asserções I e II são proposições verdadeiras, e a II é uma justificativa correta da I.", "b": "As asserções I e II são proposições verdadeiras, mas a II não é uma justificativa correta da I.", "c": "A asserção I é uma proposição verdadeira, e a II é uma proposição falsa.", "d": "A asserção I é uma proposição falsa, e a II é uma proposição verdadeira."}, "corretas": ["d"], "explicacao": "Correta. Um comitê exclusivo da TI configura monarquia de TI e não resolve o desalinhamento; a asserção II descreve corretamente o problema como falha no arranjo decisório, objeto da governança de TI.\n\nA asserção I é falsa. Um comitê formado só por profissionais de TI configura monarquia de TI. Em decisões sobre necessidades de aplicações e investimentos, esse arranjo tende a produzir soluções desalinhadas, porque quem define o valor esperado é a área de negócio. A correção consiste em uma instância compartilhada, com representantes do negócio e da alta administração, e critérios explícitos de priorização.\n    A asserção II é verdadeira. Novos produtos lançados sem que a TI seja avisada revelam decisões tomadas sem a participação da área técnica, um sintoma típico de desalinhamento. Definir quem decide, em cada domínio, e com base em quê é atribuição da governança de TI (Cap. 15, seção 3.3; Cap. 14, seção 3.3).", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-U4-Q05", "disciplina": "eag", "unidade": 4, "origem": {"questionario": "Quiz - Estratégia, Processos e Responsabilidades", "tipo": "quiz"}, "tema": "Privacidade da informação em códigos de ética", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Ética, tecnologia e sociedade | Tema: Privacidade da informação em códigos de ética\n\n  \n\n    Decidir o que é certo ou errado nem sempre é fácil ou simples. Por essa razão, muitas empresas e organizações profissionais desenvolvem seus próprios códigos de ética. Um código de ética é um conjunto de princípios destinados a guiar a tomada de decisões pelos membros da organização. A diversidade e o uso cada vez mais difundido de aplicações de TI criaram diversos aspectos éticos. Esses aspectos podem se encaixar em categorias relacionadas à privacidade da informação, que envolve coletar, armazenar e disseminar informações sobre pessoas.\n\n  \n  TURBAN, E.; RAINER, K. J.; POTTER, R. E. Introdução a sistemas de informação: uma abordagem gerencial. Rio de Janeiro: Elsevier, 2007 (adaptado).\n  \n    Considerando a categoria privacidade do código de ética, avalie as afirmações a seguir.\n    I.O código de ética determina quem é responsável pela autenticidade, fidelidade e exatidão das informações coletadas.\n    II.O código de ética estabelece que tipo de vigilância um empregador pode exercer sobre seus empregados.\n    III.O código de ética orienta como o acesso aos canais de informação deve ser alocado.\n    IV.O código de ética define quais informações devem ser divulgadas aos usuários de sistemas de informação.\n    V.O código de ética determina que informações devem ser mantidas em bancos de dados e qual o nível de segurança dessas informações.\n  \n  \n    É correto apenas o que se afirma em", "alternativas": {"a": "I, II e III.", "b": "I, II e IV.", "c": "II, IV e V.", "d": "III, IV e V."}, "corretas": ["c"], "explicacao": "Correta. Limites ao monitoramento de empregados, transparência sobre os dados e decisão sobre quais dados manter e com que segurança são questões de privacidade. As afirmações I e III tratam de acurácia e de propriedade.\n\nA formulação de Mason, conhecida pela sigla PAPA, organiza as questões éticas em sistemas de informação em privacidade, acurácia, propriedade e acessibilidade. A categoria privacidade trata de que informações sobre uma pessoa podem ser coletadas, por quem e com que finalidade. Pertencem a ela os limites ao monitoramento de empregados (II), a transparência sobre os dados coletados e compartilhados (IV) e a coleta limitada ao necessário, com proteção contra acesso indevido (V).\n    A afirmação I trata de acurácia, que diz respeito a quem responde pela exatidão da informação. A afirmação III trata de propriedade, que diz respeito a quem pertencem a informação, o software e os canais de transmissão (Cap. 16, seções 2 e 3.3).", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-US-Q01", "disciplina": "eag", "unidade": "simulado", "origem": {"questionario": "4º Simulado Preparatório (ENADE)", "tipo": "simulado"}, "tema": "Políticas públicas de cuidado", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Equidade nas relações étnico-raciais, geracionais, de classe, de gênero e de sexualidade | Tema: Políticas públicas de cuidado\n\n  \n    TEXTO I\n    O trabalho de cuidado não remunerado é pouco visível e raramente reconhecido como trabalho. A responsabilidade por ele recai, de forma desproporcional, sobre as famílias e, dentro delas, sobre as mulheres, em especial as mulheres negras e as de baixa renda, mesmo quando também exercem trabalho remunerado. Os homens, por sua vez, permanecem pouco responsabilizados por essas tarefas.\n    MINISTÉRIO DO DESENVOLVIMENTO E ASSISTÊNCIA SOCIAL (MDS). Eixos: Brasil que Cuida. 2026 (adaptado).\n    TEXTO II\n    A Política Nacional de Cuidados, instituída pela Lei nº 15.069/2024, garante o direito a cuidar, a ser cuidado e ao autocuidado. Entre seus objetivos está promover a corresponsabilização de gênero, entre homens e mulheres no interior das famílias, e a corresponsabilização social, entre famílias, comunidade, setor privado e Estado. Quem precisa de cuidados deve ter acesso a serviços de qualidade independentemente de origem ou renda, e quem cuida deve poder fazê-lo sem sobrecarga nem prejuízo à sua autonomia.\n    MINISTÉRIO DO DESENVOLVIMENTO E ASSISTÊNCIA SOCIAL (MDS). Política Nacional de Cuidados. 2026 (adaptado).\n  \n\n  Fonte: MDS. Eixos: Brasil que Cuida (2026); MDS. Política Nacional de Cuidados (2026). Textos adaptados. Disponível em: https://www.gov.br/mds/pt-br/acoes-e-programas/brasil-que-cuida/politica; https://www.gov.br/mds/pt-br/acoes-e-programas/brasil-que-cuida/plano/eixos. Acesso em: 11 nov. 2026.\n\n  \n    Considerando os dois textos, a ação pública que responde ao diagnóstico do Texto I e, ao mesmo tempo, aos objetivos do Texto II é", "alternativas": {"a": "conceder auxílio financeiro às mulheres que deixam o emprego para cuidar, em tempo integral, de familiares dependentes em suas casas.", "b": "promover campanha que valorize a dedicação materna ao cuidado como expressão de uma vocação feminina natural.", "c": "ampliar vagas em creches priorizando áreas de menor custo por vaga, independentemente do perfil de renda local.", "d": "instalar serviços públicos de cuidado em bairros de baixa renda, com ações de divisão do cuidado entre os sexos."}, "corretas": ["d"], "explicacao": "Correta. Combina oferta pública de cuidado em territórios de baixa renda com redistribuição das tarefas entre homens e mulheres, atendendo ao diagnóstico e aos dois eixos de corresponsabilização.\n\nO Texto I localiza a sobrecarga nas mulheres, sobretudo negras e de baixa renda; o Texto II exige corresponsabilização social (Estado provendo serviços) e de gênero (homens assumindo tarefas). Só D combina oferta pública em territórios de baixa renda com redistribuição entre homens e mulheres.\n  \n  \n\n  \n    Fonte: MDS. Eixos: Brasil que Cuida (2026); MDS. Política Nacional de Cuidados (2026). Textos adaptados. Disponível em: https://www.gov.br/mds/pt-br/acoes-e-programas/brasil-que-cuida/politica; https://www.gov.br/mds/pt-br/acoes-e-programas/brasil-que-cuida/plano/eixos. Acesso em: 11 nov. 2026.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-US-Q02", "disciplina": "eag", "unidade": "simulado", "origem": {"questionario": "4º Simulado Preparatório (ENADE)", "tipo": "simulado"}, "tema": "Sociobioeconomia e dados abertos", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Mudanças climáticas e questões socioambientais | Tema: Sociobioeconomia e dados abertos\n\n  \n    O Programa Nacional de Sociobioeconomia (Prospera), instituído pela Portaria GM/MMA nº 1.508/2025, busca promover a sociobioeconomia de forma territorializada, com uso sustentável e conservação da biodiversidade e com prosperidade para povos e comunidades tradicionais, por meio de ações como qualificação da produção e agregação de valor nas cadeias produtivas.\n    Segundo o Ministério do Meio Ambiente e Mudança do Clima, os dados abertos sobre bioeconomia permitem acompanhar indicadores de manejo florestal sustentável, cadeias produtivas da sociobiodiversidade, agroextrativismo, povos e comunidades tradicionais e conservação ambiental, apoiando a tomada de decisão baseada em evidências. O quadro reproduz parte desse catálogo.\n  \n  Quadro 1: conjuntos do catálogo de dados abertos sobre bioeconomia\n\n\nConjunto de dadosÓrgãoO que informa\nProdução da extração vegetal e silviculturaSFBProdução da extração vegetal e da silvicultura e valor da produção de produtos florestais madeireiros e não madeireiros.\nPlanos de Manejo Florestal Sustentável ComunitáriosICMBioPlanos executados por populações tradicionais beneficiárias de Reservas Extrativistas, Florestas Nacionais e Reservas de Desenvolvimento Sustentável.\nIFN: Uso dos recursos, importância e rendaSFBUso dos recursos, importância e renda, a partir do levantamento socioambiental do Inventário Florestal Nacional.\nPrograma Bolsa VerdeMMAQuantitativo de beneficiários. O catálogo registra descontinuidade no MMA em 2018; o programa foi recriado em 2023.\nFlorestas plantadasSFBÁrea de floresta plantada, segundo a pesquisa PEVS/IBGE.\nProdutos Madeireiros ProcessadosSFBValor e quantidade de produção de produtos madeireiros primários e secundários.\n\n\n  Fonte: Elaboração própria com base em: MINISTÉRIO DO MEIO AMBIENTE E MUDANÇA DO CLIMA (MMA). Dados Ambientais - Bioeconomia. 25 maio 2026, atualizado em 29 maio 2026; MMA. Programa Nacional de Sociobioeconomia (Prospera). 2026. MMA. Bolsa Verde: programa de apoio à conservação ambiental. 2025. Textos adaptados. Disponível em: https://www.gov.br/mma/pt-br/composicao/sbc/dpeb/programa-nacional-de-sociobioeconomia-prospera; https://www.gov.br/mma/pt-br/acesso-a-informacao/informacoes-ambientais/conjunto-de-dados-ambientais/dados-ambientais-bioeconomia. Acesso em: 11 nov. 2026.\n\n  \n    Para acompanhar, com dados abertos, as dimensões de renda, uso sustentável da floresta e participação de povos e comunidades tradicionais previstas no Prospera, sem pretender medir o impacto causal do programa, a combinação mais pertinente de conjuntos de dados é", "alternativas": {"a": "Florestas plantadas e Produtos Madeireiros Processados, que medem a expansão da área produtiva e o valor total da produção florestal do país.", "b": "Programa Bolsa Verde e Florestas plantadas, que informam os beneficiários de renda e a área com cobertura florestal plantada no país.", "c": "Produção da extração vegetal, Planos de Manejo Comunitários e IFN de uso dos recursos e renda, cruzando produção, manejo e renda.", "d": "Produtos Madeireiros Processados e Programa Bolsa Verde, que associam o valor da produção florestal à renda das famílias."}, "corretas": ["c"], "explicacao": "Correta. Reúne produção extrativista, manejo comunitário por populações tradicionais em unidades de uso sustentável e uso dos recursos associado à renda, cobrindo as três dimensões.\n\nO comando pede indicadores das três dimensões, não prova de impacto. C reúne produção extrativista (cadeias), manejo comunitário por populações tradicionais em unidades de uso sustentável (floresta em pé) e uso dos recursos associado à renda.\n  \n  \n\n  \n    Fonte: Elaboração própria com base em: MINISTÉRIO DO MEIO AMBIENTE E MUDANÇA DO CLIMA (MMA). Dados Ambientais - Bioeconomia. 25 maio 2026, atualizado em 29 maio 2026; MMA. Programa Nacional de Sociobioeconomia (Prospera). 2026. MMA. Bolsa Verde: programa de apoio à conservação ambiental. 2025. Textos adaptados. Disponível em: https://www.gov.br/mma/pt-br/composicao/sbc/dpeb/programa-nacional-de-sociobioeconomia-prospera; https://www.gov.br/mma/pt-br/acesso-a-informacao/informacoes-ambientais/conjunto-de-dados-ambientais/dados-ambientais-bioeconomia. Acesso em: 11 nov. 2026.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-US-Q03", "disciplina": "eag", "unidade": "simulado", "origem": {"questionario": "4º Simulado Preparatório (ENADE)", "tipo": "simulado"}, "tema": "Crianças e adolescentes no ambiente digital", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Ética, democracia, cidadania e direitos humanos | Tema: Crianças e adolescentes no ambiente digital\n\n  \n    Em vigor desde 17 de março de 2026, o Estatuto Digital da Criança e do Adolescente (Lei nº 15.211/2025), conhecido como ECA Digital, estabelece regras para redes sociais, jogos eletrônicos, aplicativos e outros serviços digitais dirigidos a crianças e adolescentes ou de acesso provável por esse público. Entre elas estão: a proibição do uso de perfilamento para direcionar publicidade a crianças e adolescentes; restrições a mecanismos que estimulam o uso compulsivo, como limites a recursos de rolagem contínua voltados ao público infantojuvenil e às caixas de recompensa em jogos; e a obrigação de oferecer mecanismos para que os usuários comuniquem violações aos direitos de crianças e adolescentes.\n    Uma rede social hipotética de compartilhamento de vídeos, com perfis e interação entre usuários, muitos deles adolescentes, avalia quatro propostas de redesenho de sua interface e de sua comunicação com esse público.\n  \n\n  Fonte: MDHC. ECA Digital: conheça as regras de proteção de crianças e adolescentes no ambiente online. 21 ago. 2026; AGÊNCIA GOV (via MDHC). ECA Digital completa um ano e estabelece maior proteção para crianças e adolescentes. 17 set. 2026. Textos adaptados. Disponível em: https://www.gov.br/mdh/pt-br/assuntos/noticias/2026/defeso-eleitoral/agosto/eca-digital-conheca-as-regras-de-protecao-de-criancas-e-adolescentes-no-ambiente-online; https://agenciagov.ebc.com.br/noticias/202609/1-ano-de-eca-digital-o-que-mudou-para-criancas-e-adolescentes. Acesso em: 11 nov. 2026.\n\n  \n    Considerando os recursos de comunicação envolvidos e seus impactos sobre o público adolescente, a proposta coerente com o ECA Digital é", "alternativas": {"a": "manter a rolagem contínua e acrescentar avisos em linguagem acessível sobre os riscos do uso prolongado da plataforma.", "b": "limitar a rolagem contínua, retirar anúncios baseados no comportamento do usuário e criar canal visível para denúncias.", "c": "manter anúncios definidos pelo histórico de navegação, apresentados em linguagem lúdica e identificados com clareza como publicidade paga.", "d": "reunir as denúncias de violações em formulário extenso, disponível apenas aos responsáveis legais pelos usuários adolescentes da rede."}, "corretas": ["b"], "explicacao": "Correta. Altera os próprios recursos que produzem o impacto: limita a rolagem contínua, elimina a publicidade dirigida por perfilamento e torna acessível ao usuário o canal de denúncia.\n\nB altera os próprios recursos que produzem o impacto: reduz o mecanismo de uso compulsivo (rolagem contínua), elimina a publicidade dirigida por perfilamento e torna acessível ao usuário o canal de comunicação de violações, como exige a lei.\n  \n  \n\n  \n    Fonte: MDHC. ECA Digital: conheça as regras de proteção de crianças e adolescentes no ambiente online. 21 ago. 2026; AGÊNCIA GOV (via MDHC). ECA Digital completa um ano e estabelece maior proteção para crianças e adolescentes. 17 set. 2026. Textos adaptados. Disponível em: https://www.gov.br/mdh/pt-br/assuntos/noticias/2026/defeso-eleitoral/agosto/eca-digital-conheca-as-regras-de-protecao-de-criancas-e-adolescentes-no-ambiente-online; https://agenciagov.ebc.com.br/noticias/202609/1-ano-de-eca-digital-o-que-mudou-para-criancas-e-adolescentes. Acesso em: 11 nov. 2026.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-US-Q04", "disciplina": "eag", "unidade": "simulado", "origem": {"questionario": "4º Simulado Preparatório (ENADE)", "tipo": "simulado"}, "tema": "Estratégia Nacional de Cibersegurança", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Ciência, tecnologia e inovação | Tema: Estratégia Nacional de Cibersegurança\n\n  \n    A Estratégia Nacional de Cibersegurança (E-Ciber), instituída pelo Decreto nº 12.573/2025, organiza-se em quatro eixos: proteção e conscientização do cidadão e da sociedade; segurança e resiliência dos serviços essenciais e das infraestruturas críticas; cooperação e integração entre órgãos e entidades públicas e privadas; e soberania nacional e governança. No segundo eixo, o objetivo é oferecer à sociedade instrumentos efetivos de prevenção e resposta a incidentes cibernéticos. Entre as ações previstas estão o estímulo a mecanismos de mitigação de riscos, como seguros contra incidentes, para prestadores de serviços essenciais e operadores de infraestruturas críticas, e o incentivo a exercícios e simulações setoriais e multissetoriais regulares. Cabe ao Comitê Nacional de Cibersegurança propor o Plano Nacional, que detalhará as ações estratégicas.\n    Uma companhia municipal hipotética de abastecimento de água, prestadora de serviço essencial, decidiu alinhar sua gestão de riscos à E-Ciber antes da publicação do Plano Nacional.\n  \n\n  Fonte: GABINETE DE SEGURANÇA INSTITUCIONAL (GSI). E-Ciber: Estratégia Nacional de Cibersegurança. 2026; BRASIL. Decreto nº 12.573, de 4 de agosto de 2025. Textos adaptados. Disponível em: https://www.gov.br/gsi/pt-br/assuntos/seguranca-da-informacao-e-cibernetica/estrategia-nacional-de-ciberseguranca-eciber; https://sintse.tse.jus.br/documentos/2025/Ago/5/diario-oficial-da-uniao-secao-1/decreto-no-12-573-de-4-de-agosto-de-2025-institui-a-estrategia-nacional-de-ciberseguranca. Acesso em: 11 nov. 2026.\n\n  \n    Nesse contexto, a decisão mais coerente com a estratégia é", "alternativas": {"a": "participar de exercícios setoriais periódicos de resposta a incidentes e avaliar a contratação de seguro contra incidentes cibernéticos.", "b": "adiar qualquer medida até a publicação do Plano Nacional, pois a estratégia ainda não indica ações para infraestruturas críticas.", "c": "limitar a atuação a campanhas de orientação aos consumidores, ação típica do eixo voltado ao cidadão e à sociedade.", "d": "transferir ao Comitê Nacional de Cibersegurança a gestão dos riscos da companhia, já que esse órgão propõe o plano nacional."}, "corretas": ["a"], "explicacao": "Correta. Aplica duas ações expressamente previstas no eixo de serviços essenciais e infraestruturas críticas, sem depender da publicação do Plano Nacional.\n\nA aplica duas ações expressamente previstas no eixo de serviços essenciais e não depende da publicação do Plano Nacional.\n  \n  \n\n  \n    Fonte: GABINETE DE SEGURANÇA INSTITUCIONAL (GSI). E-Ciber: Estratégia Nacional de Cibersegurança. 2026; BRASIL. Decreto nº 12.573, de 4 de agosto de 2025. Textos adaptados. Disponível em: https://www.gov.br/gsi/pt-br/assuntos/seguranca-da-informacao-e-cibernetica/estrategia-nacional-de-ciberseguranca-eciber; https://sintse.tse.jus.br/documentos/2025/Ago/5/diario-oficial-da-uniao-secao-1/decreto-no-12-573-de-4-de-agosto-de-2025-institui-a-estrategia-nacional-de-ciberseguranca. Acesso em: 11 nov. 2026.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-US-Q05", "disciplina": "eag", "unidade": "simulado", "origem": {"questionario": "4º Simulado Preparatório (ENADE)", "tipo": "simulado"}, "tema": "Acordos comerciais do Mercosul", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Processos de globalização e política internacional | Tema: Acordos comerciais do Mercosul\n\n  \n    Segundo o Ministério do Desenvolvimento, Indústria, Comércio e Serviços (MDIC), o acordo de livre comércio entre o Mercosul e a Associação Europeia de Livre Comércio (EFTA), formada por Suíça, Noruega, Islândia e Liechtenstein, reforça a estratégia brasileira de diversificar mercados e parceiros. A EFTA reúne cerca de 15 milhões de habitantes e PIB de cerca de US$ 1,4 trilhão. No Brasil, o acordo foi internalizado por decreto publicado em setembro de 2026, mas as preferências começam a valer em cada país em datas distintas.\n  \n  Quadro 1: início da aplicação das preferências e tarifa de referência para café torrado\n\n\nPaís da EFTAInício da aplicação das preferências para o BrasilTarifa de referência para café torrado antes da aplicação das preferências\nIslândia1º de outubro de 202610%\nNoruega1º de novembro de 2026Não informada\nSuíçaDepende da conclusão da internalização no país7%\nLiechtensteinDepende da conclusão da internalização no país7%\n\n  \n    O uso das preferências exige o cumprimento das regras de origem do acordo. Para café torrado, o MDIC prevê reduções tarifárias imediatas para a maior parte dos códigos tarifários.\n  \n\n  Fonte: Elaboração própria com base em: MDIC. MDIC publica manuais para orientar empresas sobre o Acordo MERCOSUL-EFTA. 1º set. 2026; MDIC. Acordo Mercosul-EFTA entra em vigor; MDIC lança painel para ampliar acesso às novas oportunidades. set. 2026. Disponível em: https://www.gov.br/mdic/pt-br/assuntos/noticias/2026-periodo-eleitoral/setembro/mdic-publica-manuais-para-orientar-empresas-sobre-o-acordo-mercosul-efta/; https://www.gov.br/mdic/pt-br/assuntos/noticias/2026-periodo-eleitoral/setembro/acordo-mercosul-efta-entra-em-vigor-mdic-lanca-painel-para-ampliar-acesso-as-novas-oportunidades. Acesso em: 11 nov. 2026.\n\n  \n    Com base nas informações, em outubro de 2026, as preferências tarifárias do acordo", "alternativas": {"a": "estavam em vigor nas relações com a Suíça, mercado com a menor tarifa de referência para café torrado entre os informados.", "b": "só entrariam em vigor depois que os quatro países da EFTA concluíssem a internalização do acordo.", "c": "estavam em vigor nas relações com a Noruega, pois passaram a valer com a internalização do acordo no Brasil.", "d": "estavam em vigor nas relações com a Islândia, enquanto Suíça e Liechtenstein dependiam da internalização no próprio país."}, "corretas": ["d"], "explicacao": "Em outubro de 2026, só a Islândia aplicava as preferências (desde 1º/10). A Noruega começou em 1º/11; Suíça e Liechtenstein dependiam de internalização. O acordo diversifica mercados de forma escalonada, país a país.\n  \n  \n\n  \n    Fonte: Elaboração própria com base em: MDIC. MDIC publica manuais para orientar empresas sobre o Acordo MERCOSUL-EFTA. 1º set. 2026; MDIC. Acordo Mercosul-EFTA entra em vigor; MDIC lança painel para ampliar acesso às novas oportunidades. set. 2026. Disponível em: https://www.gov.br/mdic/pt-br/assuntos/noticias/2026-periodo-eleitoral/setembro/mdic-publica-manuais-para-orientar-empresas-sobre-o-acordo-mercosul-efta/; https://www.gov.br/mdic/pt-br/assuntos/noticias/2026-periodo-eleitoral/setembro/acordo-mercosul-efta-entra-em-vigor-mdic-lanca-painel-para-ampliar-acesso-as-novas-oportunidades. Acesso em: 11 nov. 2026.", "por_que_erradas": {"c": "Incorreta. Confunde internalização no Brasil com início da aplicação na Noruega, que ocorre em 1º/11 (confusão entre etapas)."}, "fonte_gabarito": "oficial"}, {"id": "EAG-US-Q06", "disciplina": "eag", "unidade": "simulado", "origem": {"questionario": "4º Simulado Preparatório (ENADE)", "tipo": "simulado"}, "tema": "Estratégias de aquisição de sistemas", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Sistemas de informações gerenciais | Tema: Estratégias de aquisição de sistemas\n\n  \n    Uma distribuidora de produtos de limpeza que abastece 1.800 pontos de venda decidiu informatizar a roteirização das entregas. A diretoria trata a regra de roteirização como diferencial competitivo: ela combina janelas de recebimento dos clientes, restrições municipais de circulação de caminhões e prioridade pela margem do pedido. A área de logística revisa essa regra a cada trimestre. Pedidos e cadastro de clientes estão no ERP da empresa, e a solução precisa operar em até quatro meses.\n    O levantamento registrou quatro caminhos:\n  \n  Quadro 1: caminhos de aquisição levantados\n\n\nCaminhoPrazo de implantaçãoAjuste da regra de roteirizaçãoIntegração com o ERP\nSaaS de roteirização6 semanasAlgoritmo padrão do fornecedor, sem parametrização da regraAPI do ERP\nLicença de software com customização3 mesesFornecedor customiza sob demanda, em ciclos semestraisAPI do ERP\nDesenvolvimento próprio9 mesesEquipe interna altera o código quando a regra mudaAPI do ERP\nPlataforma de baixo código3 mesesÁrea de logística parametriza a regra com componentes prontosConector nativo às APIs do ERP\n\n\n  \n    Considerando a estratégia de aquisição e as condições informadas, a decisão que integra a roteirização ao processo que diferencia a empresa é", "alternativas": {"a": "contratar o SaaS, porque a assinatura reduz o investimento inicial e entrega a roteirização bem antes do prazo, liberando a equipe de TI para outras demandas.", "b": "desenvolver a solução internamente, porque a regra é diferencial competitivo e o domínio do código permite ajustá-la sempre que a logística a revisar.", "c": "adotar a plataforma de baixo código, porque a logística parametriza a regra a cada revisão e o conector mantém pedidos e cadastro sincronizados com o ERP.", "d": "adquirir a licença com customização, porque o fornecedor adapta o produto à regra da empresa e a implantação cabe nos quatro meses exigidos."}, "corretas": ["c"], "explicacao": "Correta. A plataforma de baixo código cabe no prazo, permite que a própria logística parametrize a regra a cada revisão trimestral e se integra ao ERP por conector nativo.\n\nCompetência I, habilidade I.5 (implementar estratégias de gestão da TI, integrando recursos tecnológicos e processos organizacionais para gerar vantagem competitiva). Conhecimento mobilizado: estratégias de aquisição de sistemas (SaaS, licença, baixo código e desenvolvimento próprio) e sua relação com processos que diferenciam a empresa. Caminho de resolução: a regra de roteirização é diferencial e muda a cada trimestre, então a empresa precisa controlar o ajuste dela sem depender de terceiros; a integração com o ERP e o prazo de quatro meses fecham o espaço de soluções. Cruzando a tabela, cada caminho incorreto viola uma única condição, e apenas o baixo código atende às três.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-US-Q07", "disciplina": "eag", "unidade": "simulado", "origem": {"questionario": "4º Simulado Preparatório (ENADE)", "tipo": "simulado"}, "tema": "Rotinas recursivas", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Algoritmos | Tema: Rotinas recursivas\n\n  \n    A controladoria de uma indústria implementou uma rotina recursiva que consolida o orçamento da hierarquia de centros de custo. A regra de consolidação estabelece que o orçamento consolidado de um centro é o seu orçamento próprio somado ao orçamento consolidado de cada centro subordinado. Antes da implantação, o gestor rastreou a execução da chamada consolidar(Diretoria) para verificar se a rotina cumpre a regra. A função filhos(c) devolve os subordinados de cada centro na ordem listada na figura, da esquerda para a direita.\n  \n  função consolidar(c): inteiro\n   se não temFilhos(c) então\n      escreva(nome(c), \" = \", orcamento(c))\n      retorne orcamento(c)\n   fim-se\n   total <- orcamento(c)\n   para cada f em filhos(c), na ordem listada, faça\n      total <- total + consolidar(f)\n   fim-para\n   escreva(nome(c), \" = \", total)\n   retorne total\nfim\n  Figura 1: hierarquia de centros de custo e orçamento próprio de cada um\n\n\n  \n    A sequência de mensagens escritas pela rotina, na ordem em que ocorrem, é", "alternativas": {"a": "Vendas = 20; Marketing = 10; Comercial = 60; Logística = 25; Operações = 65; Diretoria = 175.", "b": "Diretoria = 175; Comercial = 60; Vendas = 20; Marketing = 10; Operações = 65; Logística = 25.", "c": "Vendas = 20; Marketing = 10; Comercial = 90; Logística = 25; Operações = 90; Diretoria = 230.", "d": "Comercial = 30; Operações = 40; Diretoria = 120."}, "corretas": ["a"], "explicacao": "Competência II, habilidade II.3 (aplicar metodologias, ferramentas e boas práticas para implementar soluções tecnológicas). Conhecimento mobilizado: recursão, caso-base e ordem de retorno na pilha de chamadas. Caminho de resolução: a rotina escreve cada centro só depois de somar os subordinados, então as folhas aparecem antes dos pais. Rastreio: Vendas (folha) escreve 20; Marketing escreve 10; Comercial soma 30 + 20 + 10 = 60; Logística escreve 25; Operações soma 40 + 25 = 65; Diretoria soma 50 + 60 + 65 = 175, igual à soma dos seis orçamentos. A rotina cumpre a regra.", "por_que_erradas": {"b": "Incorreta. Escreve na ordem das chamadas, como se a mensagem saísse ao empilhar; a rotina escreve ao desempilhar."}, "fonte_gabarito": "oficial"}, {"id": "EAG-US-Q08", "disciplina": "eag", "unidade": "simulado", "origem": {"questionario": "4º Simulado Preparatório (ENADE)", "tipo": "simulado"}, "tema": "Gestão de riscos em projeto híbrido", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Gerência de projetos | Tema: Gestão de riscos em projeto híbrido\n\n  \n    Uma rede de lojas de materiais de construção implanta um novo ERP em projeto híbrido: a infraestrutura segue fases preditivas com marcos, e os módulos de vendas, estoque e fiscal saem em entregas iterativas quinzenais. No planejamento da implantação, o gerente do projeto classifica as ameaças com a taxonomia abaixo.\n  \n  Quadro 1: taxonomia de respostas a ameaças\n\n\nRespostaQuando se aplica\nEscalarA ameaça está fora do escopo do projeto ou a resposta excede a autoridade do gerente; o nível de programa, portfólio ou outra parte da organização assume a ameaça.\nEvitarO plano muda para eliminar a ameaça ou proteger o projeto de seu impacto.\nTransferirA responsabilidade pelo impacto passa a um terceiro, por contrato ou seguro.\nMitigarAções reduzem a probabilidade ou o impacto da ameaça.\nAceitarA ameaça é reconhecida sem ação proativa, podendo haver reserva de contingência.\n\n  \n    O registro de riscos contém quatro ameaças:\n    R1 (probabilidade alta, impacto alto): a integração do módulo de estoque com as balanças das lojas pode falhar; o gerente pode antecipar um teste em loja-piloto.\n    R2 (probabilidade média, impacto médio): o fornecedor dos servidores pode atrasar a entrega; o contrato já prevê multa por atraso.\n    R3 (probabilidade média, impacto alto): mudança na regulamentação tributária pode alterar as regras do módulo fiscal. A mesma mudança afeta o e-commerce e o sistema de frente de caixa, outros dois projetos do portfólio, e a decisão sobre como adequar os três sistemas cabe ao comitê de portfólio.\n    R4 (probabilidade baixa, impacto médio): usuários-chave das lojas podem deixar a empresa durante a implantação; o gerente pode treinar substitutos.\n  \n\n  Fonte: Taxonomia elaborada com base em PMI. Guia PMBOK (adaptado).\n\n  \n    Com base na taxonomia e no registro, a resposta que o gerente deve planejar é", "alternativas": {"a": "escalar R1 ao patrocinador, por ser a ameaça de maior probabilidade e impacto, e manter as demais sob responsabilidade da equipe do projeto.", "b": "transferir R3 ao fornecedor do ERP, por cláusula que o obrigue a atualizar o módulo fiscal, tratando a cláusula como a resposta do projeto à ameaça.", "c": "aceitar R3, por ser ameaça cuja causa está fora do controle do gerente, e reservar contingência de prazo para a adequação do módulo fiscal.", "d": "escalar R3 ao comitê de portfólio, que passa a responder pela adequação comum aos três sistemas, e manter o risco no registro para monitorar o módulo fiscal."}, "corretas": ["d"], "explicacao": "Correta. A decisão sobre R3 excede a autoridade do gerente e pertence ao comitê de portfólio; acompanhar o efeito local no registro complementa o escalonamento.\n\nCompetência I, habilidade I.1 (princípios e boas práticas para planejamento e coordenação da implantação de sistemas de informação). Conhecimento mobilizado: estratégias de resposta a ameaças, com foco no escalonamento. Caminho de resolução: o critério da taxonomia é a autoridade sobre a resposta, não a gravidade. R1, R2 e R4 têm resposta dentro da autoridade do gerente (teste em loja-piloto, acompanhamento do fornecedor, treinamento de substitutos). A multa de R2 compensa financeiramente o atraso, mas não transfere ao fornecedor o efeito no cronograma, que continua com o projeto. R3 afeta três projetos, e o próprio registro atribui a decisão ao comitê de portfólio: é caso de escalar. Manter R3 no registro para acompanhar efeitos locais é ação complementar legítima.\n  \n  \n\n  \n    Fonte: Taxonomia elaborada com base em PMI. Guia PMBOK (adaptado).", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-US-Q09", "disciplina": "eag", "unidade": "simulado", "origem": {"questionario": "4º Simulado Preparatório (ENADE)", "tipo": "simulado"}, "tema": "Tecnologias de apoio ao gerenciamento de processos", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Processos organizacionais | Tema: Tecnologias de apoio ao gerenciamento de processos\n\n  \n    O quadro a seguir resume tecnologias que apoiam o gerenciamento de processos de negócio (BPM).\n  \n  Quadro 1: tecnologias de apoio ao gerenciamento de processos de negócio\n\n\nTecnologiaFunçãoContribuição ao BPM\nBPMSPlataforma de modelagem, execução, controle e monitoramento de processosTransforma o modelo em fluxo executável, distribui tarefas, aplica regras e registra cada instância\nServiços e APIsFuncionalidades expostas como serviços reutilizáveis, hoje publicados como interfaces de programação (APIs) e, quando o sistema é decomposto, como microsserviçosPermite que o processo invoque funções de sistemas distintos sem integrações ponto a ponto, dando flexibilidade para recompor processos\nBAMMonitoramento da atividade de negócio em tempo real, função hoje também exercida por plataformas de observabilidade e de análise em tempo realAcompanha indicadores durante a execução e dispara alertas quando limites são ultrapassados, apoiando a correção imediata\nRPAAutomação de tarefas repetitivas por robôs que operam as interfaces existentesAutomatiza etapas em sistemas sem interface de integração disponível; combinada com modelos de linguagem, passa a tratar também etapas que dependem de interpretar texto, como triar uma solicitação ou extrair dados de um documento\nMineração de processosReconstrói o processo real a partir de registros de eventos dos sistemasRevela divergências entre o processo desenhado e o executado\n\n  \n    Uma seguradora de automóveis executa em BPMS o processo de abertura de sinistro, que usa quatro sistemas: apólices, regras de cobertura, agendamento de vistoria na rede de oficinas e pagamentos. Os quatro sistemas oferecem interfaces de integração documentadas. O processo atende três canais, aplicativo, central telefônica e portal dos corretores, e cada canal acessa os quatro sistemas por integrações ponto a ponto próprias, num total de 12 conexões.\n    A área de processos confirmou, pelo histórico das demandas de TI, que os atrasos nas mudanças do processo decorrem da manutenção dessas conexões. A diretoria quer lançar em dois meses um fluxo simplificado para danos em vidros, sem vistoria, e prevê abrir o processo a parceiros de assistência 24 horas no próximo ano.\n  \n\n  Fonte: Quadro elaborado com base na literatura de gestão de processos de negócio (adaptado).\n\n  \n    Considerando o quadro e a situação, a iniciativa tecnológica que remove a causa dos atrasos e prepara o processo para as mudanças previstas é", "alternativas": {"a": "implantar robôs de RPA que operem as telas dos quatro sistemas em cada canal, transferindo os dados entre as etapas sem depender das equipes de integração.", "b": "expor as funções dos quatro sistemas como APIs reutilizáveis, invocadas pelo processo no BPMS e pelos três canais, para que novos fluxos e parceiros usem as mesmas funções.", "c": "modelar no BPMS uma versão do processo para cada canal e outra para o fluxo de vidros, cada uma com conexões próprias aos quatro sistemas, para isolar as mudanças.", "d": "aplicar mineração de processos aos registros de eventos dos quatro sistemas, para reconstruir o processo executado e localizar as divergências em relação ao modelo."}, "corretas": ["b"], "explicacao": "Competência I, habilidade I.4 (analisar processos de negócio para diagnóstico de oportunidades de melhoria e proposição de soluções tecnológicas). Conhecimento mobilizado: funções e contribuições das tecnologias de apoio ao BPM, com foco em serviços e APIs. Caminho de resolução: o diagnóstico já está feito, e os atrasos vêm da manutenção de 12 integrações ponto a ponto. As mudanças previstas, um novo fluxo e novos parceiros, exigem reutilizar as mesmas funções em combinações diferentes. Pelo quadro, essa é a contribuição de serviços e APIs: o processo invoca funções de sistemas distintos sem integrações ponto a ponto e ganha flexibilidade para ser recomposto. Os sistemas têm interfaces documentadas, o que afasta a condição que justificaria RPA, e o BPMS já executa o processo.\n  \n  \n\n  \n    Fonte: Quadro elaborado com base na literatura de gestão de processos de negócio (adaptado).", "por_que_erradas": {"c": "Incorreta. Usa o BPMS, que a seguradora já tem, para multiplicar versões do processo com conexões próprias, o que aumenta o número de integrações em vez de reduzi-lo."}, "fonte_gabarito": "oficial"}, {"id": "EAG-US-Q10", "disciplina": "eag", "unidade": "simulado", "origem": {"questionario": "4º Simulado Preparatório (ENADE)", "tipo": "simulado"}, "tema": "Big data e armazenamento de dados", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Tecnologias para inteligência de negócio | Tema: Big data e armazenamento de dados\n\n  \n    Uma empresa de telemetria monitora frotas de caminhões. Cada veículo envia eventos de sensores a cada cinco segundos, em fluxo contínuo, em três formatos: leituras em JSON, registros do barramento do motor e imagens de câmera. Os formatos não mudaram desde a implantação, mas a frota atendida triplicou em um ano e hoje passa de 12 mil veículos.\n    Os eventos alimentam um data warehouse relacional instalado em um único servidor. A carga atrasa várias horas por dia, e o servidor já recebeu duas ampliações de processador e memória neste ano; o modelo atual está no limite de expansão do fabricante. A equipe estuda migrar o armazenamento para uma arquitetura distribuída, com particionamento dos dados e réplicas em vários nós.\n  \n\n  \n    A característica do big data que motiva a mudança e a função de cada técnica na nova arquitetura são:", "alternativas": {"a": "volume e velocidade dos eventos excedem um único servidor; o particionamento divide dados e gravações entre nós, e a replicação mantém cópias que preservam o acesso se um nó falhar.", "b": "volume e velocidade dos eventos excedem um único servidor; a replicação divide as gravações entre as cópias, e o particionamento mantém o acesso aos dados se um nó falhar.", "c": "volume e velocidade dos eventos excedem a configuração atual; uma nova ampliação de processador e memória resolve o limite, e particionamento e replicação ficam para quando a frota dobrar.", "d": "a variedade dos formatos esgota a capacidade do servidor; o particionamento separa os eventos por formato de origem, e a replicação mantém cópias que preservam o acesso se um nó falhar."}, "corretas": ["a"], "explicacao": "Competência II, habilidade II.1 (fundamentos e arquiteturas de comunicação e armazenamento de dados). Conhecimento mobilizado: características do big data e funções do particionamento e da replicação. Caminho de resolução: os formatos não mudaram e a frota triplicou, então o problema é volume e velocidade. O servidor já está no limite de expansão, o que descarta nova ampliação vertical. Particionar divide dados e gravações entre nós (escala e paralelismo); replicar guarda cópias que mantêm o acesso quando um nó falha (disponibilidade).", "por_que_erradas": {"d": "Incorreta. Atribui à variedade um problema de volume, contra o dado de que os formatos não mudaram."}, "fonte_gabarito": "oficial"}, {"id": "EAG-US-Q11", "disciplina": "eag", "unidade": "simulado", "origem": {"questionario": "4º Simulado Preparatório (ENADE)", "tipo": "simulado"}, "tema": "Consultas SQL", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Banco de dados | Tema: Consultas SQL\n\n  \n    A área comercial de um atacadista quer contatar os clientes que não fizeram pedido em 2026, inclusive os que nunca compraram. O banco de dados tem o esquema abaixo.\n  \n  Figura 1: esquema relacional do atacadista\n\n  \n    O analista de dados preparou quatro versões da consulta e precisa escolher a que atende à solicitação.\n  \n\n  \n    A consulta SQL que retorna exatamente os clientes solicitados pela área comercial é", "alternativas": {"a": "SELECT DISTINCT c.id_cliente FROM Cliente c JOIN Pedido p ON p.id_cliente = c.id_cliente WHERE p.ano <> 2026;", "b": "SELECT c.id_cliente FROM Cliente c WHERE NOT EXISTS ( SELECT 1 FROM Pedido p WHERE p.ano = 2026 );", "c": "SELECT c.id_cliente FROM Cliente c WHERE NOT EXISTS ( SELECT 1 FROM Pedido p WHERE p.id_cliente = c.id_cliente AND p.ano = 2026 );", "d": "SELECT c.id_cliente FROM Cliente c LEFT JOIN Pedido p ON p.id_cliente = c.id_cliente WHERE p.id_pedido IS NULL;"}, "corretas": ["c"], "explicacao": "Competência II, habilidade II.3. Conhecimento mobilizado: formulação de consulta SQL com anti-junção, subconsulta correlacionada e posição do filtro. Caminho de resolução: a solicitação pede os clientes para os quais não existe pedido de 2026, inclusive os que nunca compraram. O NOT EXISTS precisa ser correlacionado, ligando cada pedido ao cliente da consulta externa, e o filtro de ano precisa ficar dentro da subconsulta. Instância de teste: o cliente 1 pediu em 2026 e em 2025, o cliente 2 só em 2025 e o cliente 3 nunca pediu. A consulta C retorna os clientes 2 e 3; a A retorna 1 e 2; a B não retorna nenhum cliente; a D retorna só o cliente 3.", "por_que_erradas": {"b": "Incorreta. A subconsulta não é correlacionada: verifica se existe algum pedido de 2026 em toda a tabela, e o resultado sai vazio para todos os clientes."}, "fonte_gabarito": "oficial"}, {"id": "EAG-US-Q12", "disciplina": "eag", "unidade": "simulado", "origem": {"questionario": "4º Simulado Preparatório (ENADE)", "tipo": "simulado"}, "tema": "Saúde do trabalhador e normas regulamentadoras", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Gestão de pessoas | Tema: Saúde do trabalhador e normas regulamentadoras\n\n  \n    A Norma Regulamentadora nº 1 (NR-1), do Ministério do Trabalho e Emprego, estabelece as disposições gerais de segurança e saúde no trabalho. Seu capítulo 1.5 obriga a organização a manter o gerenciamento de riscos ocupacionais (GRO), documentado no Programa de Gerenciamento de Riscos (PGR). Na redação da Portaria MTE nº 1.419/2024, exigível desde 26 de maio de 2026, o capítulo passou a dispor:\n  \n  1.5.3.1.4 O gerenciamento de riscos ocupacionais deve abranger os riscos que decorrem dos agentes físicos, químicos, biológicos, riscos de acidentes e riscos relacionados aos fatores ergonômicos, incluindo os fatores de risco psicossociais relacionados ao trabalho.\n  1.5.7.1 O PGR deve conter, no mínimo, os seguintes documentos: a) inventário de riscos; e b) plano de ação.\n  \n    Na área de TI de uma operadora de planos de saúde, cada analista cumpre em média três plantões de sobreaviso por mês, e as sprints passaram de três para duas semanas sem redução do escopo planejado. Em doze meses, os afastamentos por esgotamento profissional subiram de dois para sete. O gestor da área apresentou à diretoria um plano com três medidas: assinatura de aplicativo de meditação para a equipe, trilha técnica de carreira e bônus para entregas dentro do prazo.\n  \n\n  Fonte: BRASIL. Ministério do Trabalho e Emprego. Norma Regulamentadora nº 1 (NR-1), itens 1.5.3.1.4 e 1.5.7.1, na redação da Portaria MTE nº 1.419/2024, exigível desde 26/05/2026.\n\n  \n    Considerando os dispositivos transcritos, a avaliação correta do plano do gestor é:", "alternativas": {"a": "o plano atende à norma, porque as três medidas cuidam da saúde mental da equipe e demonstram a atenção da organização ao esgotamento profissional.", "b": "o plano atende à norma, porque a trilha técnica reduz a rotatividade e, ao reter os analistas experientes, controla na origem a causa dos afastamentos por esgotamento.", "c": "o plano é uma ação voluntária adequada, porque o inventário de riscos abrange agentes do ambiente físico e acidentes, categorias em que o esgotamento profissional da equipe não se enquadra.", "d": "o plano não atende à norma, porque os fatores psicossociais de plantões e metas devem ser avaliados e, se confirmados, tratados no inventário e no plano de ação, com medidas sobre a organização do trabalho."}, "corretas": ["d"], "explicacao": "Correta. Exige avaliar os fatores psicossociais e tratá-los no inventário e no plano de ação com medidas sobre a organização do trabalho.\n\nCompetência I, habilidade I.3 (requisitos regulatórios e conformidade). Conhecimento mobilizado: fatores de risco psicossociais no gerenciamento de riscos ocupacionais da NR-1. Caminho de resolução: o item 1.5.3.1.4 inclui os fatores de risco psicossociais no gerenciamento de riscos ocupacionais, e o item 1.5.7.1 exige inventário de riscos e plano de ação. Plantões frequentes e metas comprimidas são fatores ligados à organização do trabalho; a conformidade exige avaliá-los e, confirmados como riscos, registrá-los no inventário e tratá-los com medidas sobre essa organização, acompanhadas ao longo do tempo. Meditação e trilha técnica podem complementar o plano, mas não substituem essas medidas. O bônus por prazo tende a intensificar a pressão por entrega.\n  \n  \n\n  \n    Fonte: BRASIL. Ministério do Trabalho e Emprego. Norma Regulamentadora nº 1 (NR-1), itens 1.5.3.1.4 e 1.5.7.1, na redação da Portaria MTE nº 1.419/2024, exigível desde 26/05/2026.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-US-Q13", "disciplina": "eag", "unidade": "simulado", "origem": {"questionario": "4º Simulado Preparatório (ENADE)", "tipo": "simulado"}, "tema": "Desempenho de processos modelados em BPMN", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Processos organizacionais | Tema: Desempenho de processos modelados em BPMN\n\n  \n    Uma empresa de saneamento mapeou em BPMN o processo de solicitação de compra.\n  \n  Figura 1: processo de solicitação de compra em BPMN\n\n  \n    A solicitação corrigida é sempre aprovada na reanálise, de modo que o retrabalho ocorre no máximo uma vez. A equipe de processos avalia duas melhorias, que não podem ser implantadas juntas neste ciclo:\n    Melhoria A: lista de verificação no registro, que reduz as devoluções de 30% para 10%.\n    Melhoria B: notificação automática ao solicitante, que elimina 1,0 h de espera na correção.\n  \n\n  \n    O tempo médio de ciclo atual do processo e a melhoria que mais o reduz são:", "alternativas": {"a": "tempo médio atual de 7,0 h; a melhoria B reduz mais, levando o tempo médio a 4,6 h.", "b": "tempo médio atual de 4,9 h; a melhoria A reduz mais, levando o tempo médio a 4,3 h.", "c": "tempo médio atual de 4,9 h; a melhoria B reduz mais, levando o tempo médio a 3,9 h.", "d": "tempo médio atual de 5,3 h; a melhoria A reduz mais, levando o tempo médio a 4,3 h."}, "corretas": ["b"], "explicacao": "Correta. Pondera o retrabalho pela probabilidade de devolução e compara corretamente o efeito das duas melhorias.\n\nCompetência I, habilidade I.4. Conhecimento mobilizado: leitura de BPMN com gateway exclusivo e cálculo do tempo médio de ciclo ponderado pela probabilidade. Caminho de resolução: caminho principal 0,5 + 1,5 + 1,0 + 1,0 = 4,0 h. O ramo de retrabalho soma 3,0 h e ocorre em 30% dos casos, uma única vez. Atual: 4,0 + 0,3 × 3,0 = 4,9 h. Com A: 4,0 + 0,1 × 3,0 = 4,3 h (ganho de 0,6 h). Com B: 4,0 + 0,3 × 2,0 = 4,6 h (ganho de 0,3 h). A melhoria A reduz mais.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-US-Q14", "disciplina": "eag", "unidade": "simulado", "origem": {"questionario": "4º Simulado Preparatório (ENADE)", "tipo": "simulado"}, "tema": "Segurança na comunicação web", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Redes de computadores | Tema: Segurança na comunicação web\n\n  \n    Uma agência de viagens migrou o portal de reservas para um provedor de nuvem. O navegador do cliente se conecta a um balanceador de carga, que encerra a sessão TLS, inspeciona o conteúdo HTTP com regras de firewall de aplicação e encaminha cada requisição a um dos servidores de aplicação. A rede entre o balanceador e os servidores é compartilhada com outros clientes do provedor. A captura de tráfego feita pela equipe de operações registrou:\n  \n  Quadro 1: protocolos observados na captura de tráfego\n\n\nTrechoProtocolos observados\nNavegador até o balanceadorTCP na porta 443; TLS 1.3, com certificado válido para o domínio do portal; HTTP dentro da sessão TLS\nBalanceador até o servidor de aplicaçãoTCP na porta 8080; HTTP\n\n  \n    A política de segurança da agência exige que os dados de pagamento trafeguem cifrados em todo o caminho até o servidor de aplicação. O firewall de aplicação deve continuar inspecionando as requisições.\n  \n\n  \n    Considerando a arquitetura e a política de segurança, a avaliação correta da configuração é:", "alternativas": {"a": "a política está atendida, porque o cadeado exibido pelo navegador indica que a comunicação segue cifrada desde o navegador até o servidor de aplicação.", "b": "a política está atendida, porque o TCP do trecho interno garante, com confirmação e retransmissão, que os dados de pagamento cheguem íntegros ao servidor.", "c": "a política não está atendida, porque o TLS protege só até o balanceador; é preciso nova sessão TLS do balanceador aos servidores.", "d": "a política não está atendida, e basta configurar os servidores de aplicação para receber o HTTP do balanceador na porta 443, padrão do tráfego cifrado."}, "corretas": ["c"], "explicacao": "Competência II, habilidade II.5 (analisar aplicação de princípios de segurança da informação para proteção de ativos e gestão de riscos). Conhecimento mobilizado: composição do HTTPS (HTTP dentro de TLS sobre TCP), alcance da proteção do TLS e papéis distintos do TLS, do TCP e da porta. Caminho de resolução: no primeiro trecho, o HTTP trafega dentro da sessão TLS, e as garantias de confidencialidade, integridade e autenticidade do servidor valem até o balanceador, onde a sessão termina. No segundo trecho, a captura registra apenas TCP e HTTP: os dados de pagamento trafegam em texto claro numa rede compartilhada. Como o firewall precisa ler o HTTP, o balanceador deve continuar encerrando a sessão do navegador e abrir uma nova sessão TLS com os servidores, o que mantém a inspeção e a cifragem em todo o caminho.", "por_que_erradas": {"b": "Incorreta. Confunde confiabilidade com proteção criptográfica: o TCP confirma, ordena e retransmite segmentos, mas não cifra os dados nem os protege contra leitura ou adulteração intencional."}, "fonte_gabarito": "oficial"}, {"id": "EAG-US-Q15", "disciplina": "eag", "unidade": "simulado", "origem": {"questionario": "4º Simulado Preparatório (ENADE)", "tipo": "simulado"}, "tema": "Modelagem dimensional", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Tecnologias para inteligência de negócio | Tema: Modelagem dimensional\n\n  \n    Uma rede de supermercados mantém o data mart de vendas modelado conforme o diagrama a seguir. O catálogo tem cerca de 2 milhões de produtos, e a classificação de marcas, subcategorias e categorias é revista com frequência; a equipe de dados quer atualizar cada classificação em um único lugar. As consultas ao data mart são feitas por analistas de dados, familiarizados com SQL.\n  \n  Figura 1: modelo dimensional do data mart de vendas\n\n\n  \n    O esquema representado no diagrama e a característica que ele favorece são:", "alternativas": {"a": "floco de neve, cujas dimensões normalizadas em hierarquias reduzem a redundância, ao custo de mais junções e de consultas mais complexas.", "b": "estrela, cujas dimensões desnormalizadas tornam as consultas mais simples e rápidas, ao custo de redundância nas dimensões.", "c": "floco de neve, cujas dimensões normalizadas em hierarquias tornam as consultas mais simples e rápidas, por reduzir o tamanho das tabelas.", "d": "estrela, que concentra na tabela fato os atributos descritivos e reduz a redundância, por dispensar as tabelas de dimensão."}, "corretas": ["a"], "explicacao": "Correta. Identifica o floco de neve pelas dimensões normalizadas em hierarquias e associa a ele a menor redundância, com o custo de mais junções.\n\nCompetência II, habilidade II.1 (conhecer fundamentos e arquiteturas relacionadas ao armazenamento de dados). Conhecimento mobilizado: esquemas estrela e floco de neve e o equilíbrio entre redundância e complexidade das consultas. Caminho de resolução: no diagrama, a tabela fato liga-se a dimensões que, por sua vez, se ligam a outras tabelas (produto a subcategoria e categoria, produto a marca, loja a cidade e região, data a mês). Dimensões normalizadas em hierarquias caracterizam o floco de neve, que reduz a redundância e permite atualizar cada classificação em um único lugar, como quer a equipe, ao custo de mais junções. O custo é aceitável porque as consultas são feitas por analistas familiarizados com SQL.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-US-Q16", "disciplina": "eag", "unidade": "simulado", "origem": {"questionario": "4º Simulado Preparatório (ENADE)", "tipo": "simulado"}, "tema": "Planejamento de entregas com Scrum", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Gerência de projetos | Tema: Planejamento de entregas com Scrum\n\n  \n    Uma software house desenvolve, com Scrum, o aplicativo de agendamento de uma rede de clínicas. O contrato fixa a entrega dos itens vinculados à Meta do Produto em quatro sprints; qualquer alteração de escopo ou prazo exige aditivo negociado entre o patrocinador da software house e a diretoria da rede. Os itens restantes do Product Backlog somam 130 pontos, estimados pelos Developers. A velocidade das últimas cinco sprints foi:\n  \n  Quadro 1: pontos concluídos por sprint\n\n\nSprint12345\nPontos concluídos3428312532\n\n  \n    A equipe usa a média e a menor velocidade para estimar uma faixa do que cabe nas próximas quatro sprints.\n  \n\n  \n    A conduta que trata adequadamente a previsão e atribui cada decisão a quem responde por ela é:", "alternativas": {"a": "apresentar ao cliente a entrega dos 130 pontos em quatro sprints, com base na velocidade de 34 pontos já alcançada pelo time, mantendo a ordenação atual do backlog.", "b": "os Developers apresentam a faixa de 100 a 120 pontos; o Scrum Master define os itens que saem da entrega e comunica ao cliente a nova composição do escopo.", "c": "os Developers apresentam a faixa de 100 a 120 pontos; o Product Owner retira os itens de menor valor e comunica ao cliente o escopo reduzido como compromisso já firmado.", "d": "os Developers apresentam a faixa de 100 a 120 pontos; o Product Owner reordena o backlog pelo valor, e o patrocinador negocia com a rede o aditivo de escopo ou prazo."}, "corretas": ["d"], "explicacao": "Correta. Apresenta a previsão como faixa e atribui estimativa, ordenação e renegociação a quem responde por cada uma.\n\nCompetência I, habilidade I.1. Conhecimento mobilizado: previsão por velocidade e responsabilizações do Guia do Scrum (2020). Caminho de resolução: média das velocidades (34 + 28 + 31 + 25 + 32) / 5 = 30 pontos; menor: 25. Em quatro sprints, a faixa vai de 100 a 120 pontos, abaixo dos 130 restantes. O Guia do Scrum atribui o dimensionamento aos Developers e a ordenação do Product Backlog ao Product Owner; o contrato, pelo enunciado, só muda por aditivo entre patrocinador e cliente. Velocidade e pontos são práticas complementares, não prescrições do Guia.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-US-Q17", "disciplina": "eag", "unidade": "simulado", "origem": {"questionario": "4º Simulado Preparatório (ENADE)", "tipo": "simulado"}, "tema": "Escalonamento de processos", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Sistemas operacionais | Tema: Escalonamento de processos\n\n  \n    O servidor de uma plataforma de ensino a distância tem um único processador virtual e escalona os processos pela política FCFS (first come, first served, o primeiro a chegar é o primeiro atendido), que executa cada processo até o fim, na ordem de chegada, sem preempção. Ele atende consultas interativas dos tutores, curtas, e gera relatórios de desempenho das turmas, longos, disparados várias vezes ao dia. O monitoramento registra uso médio de CPU de 45%, mas o tempo de resposta das consultas ultrapassa a meta sempre que um relatório entra na fila antes delas.\n    Consultas chegam continuamente durante o expediente, e o relatório não pode ser adiado indefinidamente. A equipe avalia alternativas como a política SJF (shortest job first, a menor tarefa primeiro), que executa primeiro o processo com o menor tempo de CPU, e o Round Robin. Cada troca de contexto consome cerca de 0,1 ms. O quadro mostra a fila de prontos em um desses momentos, na ordem de chegada; nos cálculos, desconsidere o custo das trocas de contexto.\n  \n  Quadro 1: fila de prontos no momento observado\n\n\nProcessoTipoTempo de CPU restante\nRrelatório24 ms\nC1consulta2 ms\nC2consulta2 ms\nC3consulta2 ms\n\n\n  \n    A política de escalonamento adequada aos requisitos e a justificativa correta são:", "alternativas": {"a": "SJF, que leva a espera média das consultas a 2 ms, a menor entre as políticas, e conclui o relatório logo depois das três consultas da fila.", "b": "Round Robin com quantum de 4 ms, que reduz a espera média das consultas de 26 ms para 6 ms e mantém o relatório recebendo fatias até concluir.", "c": "Round Robin com quantum de 0,1 ms, que dá a cada consulta acesso quase imediato à CPU e reduz o tempo de resposta sem custo adicional ao servidor.", "d": "FCFS mantido com ampliação do processador, pois a espera média de 26 ms das consultas decorre do volume de trabalho, e não da política adotada."}, "corretas": ["b"], "explicacao": "Correta. A preempção por quantum tira as consultas de trás do relatório, reduz a espera média a 6 ms e garante fatias periódicas ao relatório, com custo de troca de contexto pequeno diante de um quantum de 4 ms.\n\nCompetência II, habilidade II.4 (monitorar o desempenho das operações de TI com base em métricas e padrões). Conhecimento mobilizado: políticas de escalonamento (FCFS, SJF e Round Robin), efeito comboio, inanição e custo da troca de contexto. Caminho de resolução: no FCFS, as consultas esperam o relatório inteiro: esperas de 24, 26 e 28 ms, média de 26 ms. Com Round Robin e quantum de 4 ms, o relatório usa 4 ms, as consultas executam em seguida (esperas de 4, 6 e 8 ms, média de 6 ms) e o relatório termina em 30 ms, em vez de 24 ms. O uso de CPU de 45% mostra que a demora vem da política, não da capacidade. O SJF dá a menor espera no quadro, mas, com chegada contínua de consultas, pode adiar o relatório indefinidamente. Um quantum igual ao custo da troca de contexto gastaria cerca de metade da CPU trocando processos.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-US-Q18", "disciplina": "eag", "unidade": "simulado", "origem": {"questionario": "4º Simulado Preparatório (ENADE)", "tipo": "simulado"}, "tema": "Inteligência artificial em sistemas de gestão", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Sistemas de informações gerenciais | Tema: Inteligência artificial em sistemas de gestão\n\n  \n    Uma fabricante de equipamentos odontológicos avalia ativar no CRM um assistente de IA com três funções:\n    Função 1: responder, em linguagem natural, perguntas sobre o histórico de compras de cada cliente e a situação das negociações.\n    Função 2: simular cenários de desconto e mostrar o efeito de cada um na margem do pedido.\n    Função 3: aplicar automaticamente descontos acima da alçada do vendedor quando o modelo estimar chance de fechamento superior a 80%.\n    A política comercial exige aprovação registrada do gerente regional para qualquer desconto acima da alçada do vendedor. A diretoria declarou dois objetivos para a iniciativa: proteger a margem e manter a rastreabilidade das decisões comerciais.\n  \n\n  \n    A avaliação da proposta quanto ao alinhamento com os objetivos e a política da organização é:", "alternativas": {"a": "a proposta deve ser ajustada: consulta e simulação apoiam a decisão e podem ser ativadas, mas o desconto acima da alçada deve depender de aprovação registrada do gerente.", "b": "a proposta é adequada: o assistente opera dentro do CRM, sistema transacional que registra cada operação, o que já assegura a rastreabilidade exigida pela diretoria.", "c": "a proposta é adequada: a aplicação automática acelera o fechamento das vendas, e o modelo só concede desconto quando a chance de fechar o pedido é alta.", "d": "a proposta deve ser rejeitada: respostas e simulações geradas por IA substituem o julgamento do vendedor e do gerente sobre as condições comerciais."}, "corretas": ["a"], "explicacao": "Correta. Mantém as funções de apoio e condiciona a execução acima da alçada à aprovação registrada do gerente.\n\nCompetência I, habilidade I.2 (modelos e estratégias de alinhamento da TI aos objetivos organizacionais). Conhecimento mobilizado: distinção entre apoio à decisão e execução de decisão, alçada decisória e rastreabilidade. Caminho de resolução: a avaliação parte da natureza de cada decisão, não do rótulo do sistema. Consulta e simulação informam o vendedor e o gerente sem decidir por eles. A terceira função executa uma decisão acima da alçada sem a aprovação registrada exigida pela política, o que ameaça a margem e a rastreabilidade da decisão.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-US-Q19", "disciplina": "eag", "unidade": "simulado", "origem": {"questionario": "4º Simulado Preparatório (ENADE)", "tipo": "simulado"}, "tema": "Estratégia de testes automatizados", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Engenharia de software | Tema: Estratégia de testes automatizados\n\n  \n    Uma empresa de logística mantém o sistema de rastreamento de entregas, integrado a dois serviços externos: o das transportadoras parceiras e o de emissão de nota fiscal. A equipe libera versões toda semana e mantém a suíte de testes automatizados abaixo.\n  \n  Quadro 1: composição da suíte de testes automatizados\n\n\nNívelTestesTempo de execuçãoFalhas intermitentes no último mês\nUnidade1202 min0\nIntegração e contrato6012 min3\nSistema, ponta a ponta pela interface9002 h 40 min47\n\n  \n    A suíte completa leva quase três horas e, por isso, roda só à noite. Quando um teste falha, a equipe gasta em média meio período para localizar o componente defeituoso. A gerência quer que a suíte rode a cada alteração integrada, em até 20 minutos, que uma falha indique o componente em que o defeito nasceu e que a proteção contra regressões não diminua.\n  \n\n  \n    Considerando o princípio da pirâmide de testes, a mudança na suíte mais adequada para alcançar os objetivos da gerência é", "alternativas": {"a": "ampliar os testes de sistema pela interface, que reproduzem o uso real e dão a proteção mais confiável, e paralelizar sua execução para caber nos 20 minutos.", "b": "eliminar os testes de integração e contrato, que dependem dos serviços parceiros, e manter apenas os de unidade e os de sistema para reduzir o tempo de execução.", "c": "levar a testes de unidade as regras hoje verificadas pela interface, cobrir os parceiros com testes de integração e contrato e manter poucos testes ponta a ponta.", "d": "manter a composição da suíte, executá-la completa apenas antes de cada liberação semanal e reservar as execuções a cada alteração aos testes de unidade."}, "corretas": ["c"], "explicacao": "Correta. Recompõe a pirâmide: regras de negócio em testes de unidade, comunicação com os parceiros em integração e contrato e poucos testes ponta a ponta, o que encurta a execução, ajuda a localizar o defeito e preserva a proteção contra regressões.\n\nCompetência II, habilidade II.3 (aplicar metodologias, ferramentas e boas práticas para implementar soluções tecnológicas). Conhecimento mobilizado: pirâmide de testes e consequências de sua inversão. Caminho de resolução: a pirâmide prevê muitos testes de unidade, rápidos e precisos para localizar o defeito; uma camada intermediária de integração e contrato; e poucos testes de sistema, lentos, caros e sensíveis a mudanças de interface. A tabela mostra a pirâmide invertida, com 900 testes de sistema contra 120 de unidade. A inversão explica os sintomas: os testes de sistema consomem 2 h 40 min das quase três horas, concentram 47 das 50 falhas intermitentes e acusam a falha sem indicar onde ela nasceu. Só a recomposição da pirâmide ataca as causas dos três problemas; os tempos da nova suíte e a cobertura dos cenários críticos precisam ser confirmados depois da mudança.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "EAG-US-Q20", "disciplina": "eag", "unidade": "simulado", "origem": {"questionario": "4º Simulado Preparatório (ENADE)", "tipo": "simulado"}, "tema": "Teste de mesa", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Eixo: Algoritmos | Tema: Teste de mesa\n\n  \n    Uma distribuidora de insumos hospitalares controla o estoque de um item crítico pela política de ponto de pedido. Ao fim de cada dia, se o saldo ficar abaixo de 20 unidades, ela emite um pedido de lote de 30 unidades, que entra no estoque no dia seguinte. O saldo inicial é de 40 unidades. A rotina abaixo, em Java, simula essa política para os cinco dias de demanda prevista. Antes de usá-la no planejamento, o analista de suprimentos fez o teste de mesa da rotina.\n  \n  int saldo = 40, emTransito = 0, pedidos = 0;\nint[] demanda = {12, 8, 9, 15, 10};\nfor (int d = 0; d < demanda.length; d++) {\n    saldo = saldo - demanda[d] + emTransito;\n    emTransito = 0;\n    if (saldo < 20) {\n        emTransito = 30;\n        pedidos++;\n    }\n}\n\n  \n    A tabela que registra corretamente os valores de saldo, emTransito e pedidos ao fim de cada iteração do laço é", "alternativas": {"a": "dsaldoemTransitopedidos 02800 120301 24101 32601 416302", "b": "dsaldoemTransitopedidos 02800 12000 241301 32601 446302", "c": "dsaldoemTransitopedidos 02800 12000 211301 326301 446301", "d": "dsaldoemTransitopedidos 02800 12000 211301 32601 416302"}, "corretas": ["d"], "explicacao": "Competência II, habilidade II.3 (aplicar metodologias, ferramentas e boas práticas para implementar soluções tecnológicas). Conhecimento mobilizado: teste de mesa de laço com condição, acumulador e variável de estado que afeta a iteração seguinte. Caminho de resolução: acompanhar o valor de cada variável ao fim de cada iteração. Em d = 0, saldo = 40 - 12 + 0 = 28, sem pedido. Em d = 1, saldo = 28 - 8 = 20; como 20 não é menor que 20, não há pedido. Em d = 2, saldo = 20 - 9 = 11, abaixo do ponto de pedido: emTransito recebe 30 e pedidos passa a 1. Em d = 3, saldo = 11 - 15 + 30 = 26, e emTransito volta a 0. Em d = 4, saldo = 26 - 10 = 16: novo pedido, com emTransito igual a 30 e pedidos igual a 2. As alternativas A e D terminam no mesmo estado final, de modo que só o rastreio completo as distingue.", "por_que_erradas": {"c": "Incorreta. Omite a linha emTransito = 0, e o lote passa a ser somado em todas as iterações seguintes; com isso, o saldo não cai abaixo de 20 no último dia."}, "fonte_gabarito": "oficial"}, {"id": "GOV-U1-Q01", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.4 Quiz", "tipo": "quiz"}, "tema": "Governança de TI (conceito e alinhamento)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Casos como o da ENRON mostram que a governança é fundamental. Em particular, a governança de TI surgiu da necessidade de melhorar atuação da TI no negócio principal da empresa. Das alternativas abaixo, qual delas está incorreta quanto à governança de TI?", "alternativas": {"a": "Busca otimizar processos e eficiência.", "b": "Busca garantir a continuidade do negócio por meio de um correto alinhamento estratégico.", "c": "Melhora a efetividade da relação da TI com o restante da empresa.", "d": "A TI nem sempre precisa estar alinhada aos objetivos empresariais, em função de sua necessidade de autonomia."}, "corretas": ["d"], "explicacao": "A questão pede a alternativa INCORRETA. A essência da governança de TI é justamente garantir que a TI esteja SEMPRE alinhada aos objetivos do negócio. Dizer que ela 'nem sempre precisa estar alinhada' para ter autonomia contradiz o conceito.", "por_que_erradas": {"a": "Correta sobre governança de TI: ela busca otimizar processos e eficiência.", "b": "Correta: o alinhamento estratégico garante a continuidade do negócio.", "c": "Correta: melhora a relação da TI com as demais áreas."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U1-Q02", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.4 Quiz", "tipo": "quiz"}, "tema": "Gestão x governança", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Os termos “gestão” e “governança” podem ser confusos para algumas pessoas. Na prática, o correto é dizer que:", "alternativas": {"a": "a gestão considera, já a governança desconsidera os riscos.", "b": "o gerenciamento de TI trata de questões presentes, enquanto a governança trata de demandas atuais e futuras da corporação, com a finalidade de garantir a perenidade e o crescimento da empresa.", "c": "não há nenhuma diferença entre governança e gestão, pois correspondem ao mesmo objeto.", "d": "ambas existem, mas não há conexão entre elas, pois atuam de forma totalmente independente."}, "corretas": ["b"], "explicacao": "Gestão (gerenciamento) cuida do presente, da operação do dia a dia. Governança olha para as demandas atuais e futuras, direcionando e monitorando a gestão para garantir a perenidade e o crescimento da empresa. São diferentes, mas conectadas.", "por_que_erradas": {"a": "As duas consideram riscos; a governança, inclusive, supervisiona a gestão de riscos.", "c": "Há diferença clara: governança avalia, dirige e monitora; gestão planeja, constrói, entrega e monitora.", "d": "Elas são interdependentes: a gestão presta contas à governança."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U1-Q03", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.4 Quiz", "tipo": "quiz"}, "tema": "Aspectos da governança de TIC", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A governança de TIC tem vários aspectos. Um desses aspectos trata da supervisão do capital investido, o uso e a alocação dos recursos de TI visando assegurar a existência do que for necessário para funcionar, e a busca pelo alinhamento com objetivos estratégicos e necessidades de negócios, atuais e futuras. Estamos falando de:", "alternativas": {"a": "gerenciamento da imagem.", "b": "gerenciamento de riscos.", "c": "gerenciamento da comunicação.", "d": "gerenciamento de recursos."}, "corretas": ["d"], "explicacao": "Supervisionar o capital investido, o uso e a alocação dos recursos de TI para que exista o necessário para funcionar é o gerenciamento de RECURSOS.", "por_que_erradas": {"a": "Gerenciamento da imagem trata da reputação, não da alocação de recursos.", "b": "Gerenciamento de riscos trata de ameaças e eventos danosos.", "c": "Gerenciamento da comunicação trata do fluxo de informação."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U1-Q04", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.4 Quiz", "tipo": "quiz"}, "tema": "Gestão e governança diante da complexidade", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Os sistemas de informação têm experimentado um aumento de complexidade, o que traz mais problemas tanto para a gestão quanto para a governança. Em razão disso, a gestão e a governança precisam:", "alternativas": {"a": "manter os usuários sob controle, evitando maiores demandas.", "b": "restringir ao máximo o uso de recursos.", "c": "alinhar adequadamente ações, para que as necessidades sejam atendidas de maneira eficiente.", "d": "atender, apenas quando concordarem, com as demandas dos usuários."}, "corretas": ["c"], "explicacao": "Com sistemas mais complexos, gestão e governança precisam alinhar suas ações para atender às necessidades de forma eficiente, e não restringir ou controlar os usuários.", "por_que_erradas": {"a": "Controlar usuários para evitar demanda vai contra o papel da TI de atender o negócio.", "b": "Restringir ao máximo o uso de recursos prejudica a operação; o objetivo é uso racional.", "d": "Atender só 'quando concordarem' ignora a priorização baseada no negócio."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U1-Q05", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.4 Quiz", "tipo": "quiz"}, "tema": "Comunicação entre gestão e governança", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A gestão e a governança precisam de uma comunicação adequada para que a informação flua de forma eficiente. Sobre essa comunicação, é incorreto afirmar que:", "alternativas": {"a": "se processa apenas em canais formais.", "b": "é necessária em empresas pequenas e grandes.", "c": "se mal conduzida, pode gerar decisões equivocadas.", "d": "ela mais atrapalha do que ajuda."}, "corretas": ["d"], "explicacao": "A questão pede a INCORRETA. A comunicação é essencial para a informação fluir e para decisões corretas; dizer que ela 'mais atrapalha do que ajuda' é falso.", "por_que_erradas": {"a": "Também é falsa: a comunicação acontece por canais formais e informais. Por isso a questão é ambígua, mas a d é a mais claramente incorreta.", "b": "Correta: toda empresa precisa de comunicação.", "c": "Correta: comunicação ruim leva a decisões equivocadas."}, "fonte_gabarito": "especialista", "observacao": "Questão ambígua: as alternativas a e d são afirmações falsas. Marcada a d por ser a mais evidentemente incorreta. Confirmar no gabarito oficial."}, {"id": "GOV-U1-Q06", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.8 Quiz", "tipo": "quiz"}, "tema": "Gestão x governança (prestação de contas)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A gestão é responsável pelas operações do dia a dia e naturalmente deve prestar contas do que faz à governança. Esse mecanismo de repasse de informações é conhecido como:", "alternativas": {"a": "retorno.", "b": "auditoria.", "c": "feedback.", "d": "backup."}, "corretas": ["a"], "explicacao": "O mecanismo pelo qual a gestão presta contas à governança é o retorno (em inglês, 'feedback').", "por_que_erradas": {"c": "O feedback é o mecanismo pelo qual a gestão presta contas à governança."}, "fonte_gabarito": "oficial", "observacao": "O gabarito oficial é 'retorno', mas o próprio feedback do Moodle diz que 'o feedback é o mecanismo pelo qual a gestão presta contas'. 'Retorno' e 'feedback' são sinônimos; na prova, siga o gabarito: retorno."}, {"id": "GOV-U1-Q07", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.8 Quiz", "tipo": "quiz"}, "tema": "Atividades da governança (COBIT: EDM)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Há uma separação clara entre as atividades de gestão e governança. No caso de governança, conforme o COBIT, as atividades são:", "alternativas": {"a": "avaliar, adquirir e liberar.", "b": "estabelecer, gerenciar e auditar.", "c": "dimensionar, avaliar e cobrar.", "d": "avaliar, dirigir e monitorar."}, "corretas": ["d"], "explicacao": "Sim, as atividades da governança são avaliar, dirigir e monitorar.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U1-Q08", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.8 Quiz", "tipo": "quiz"}, "tema": "Atividades da gestão (COBIT)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A gestão presta contas das suas atividades, que são monitoradas pela governança. No caso da gestão, as atividades principais são:", "alternativas": {"a": "incluir, consultar, alterar e excluir.", "b": "avaliar, inserir, assessorar e auditar.", "c": "planejar, construir, entregar e monitorar.", "d": "planejar, deletar, inserir e alterar."}, "corretas": ["c"], "explicacao": "As atividades da gestão são, de fato, planejar, construir, entregar e monitorar.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U1-Q09", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.8 Quiz", "tipo": "quiz"}, "tema": "Papel da governança", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "O papel da governança é assegurar que a organização esteja na direção correta, alinhada aos objetivos estratégicos, missão, visão e valores da empresa. Podemos dizer, então, que:", "alternativas": {"a": "a governança supervisiona tudo, exceto risco.", "b": "A governança supervisiona a conformidade e estratégia no longo prazo.", "c": "a governança supervisiona as ações diárias, apenas.", "d": "a governança supervisiona apenas aspectos financeiros."}, "corretas": ["b"], "explicacao": "Sim, a governança supervisiona a conformidade e estratégia no longo prazo.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U1-Q10", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.8 Quiz", "tipo": "quiz"}, "tema": "Gestão x governança (atividade em comum)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Na sua atividade conjunta e alinhada, a gestão e governança atuam de forma complementar, mas alinhada. Uma das atividades tem o mesmo nome para ambas, embora com foco diferenciado. Estamos falando de:", "alternativas": {"a": "entregar.", "b": "monitorar.", "c": "dirigir.", "d": "avaliar."}, "corretas": ["b"], "explicacao": "Sim, a atividade comum à governança e gestão é monitorar, mas com focos diferentes.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U1-Q11", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.9 Lacunas", "tipo": "lacunas"}, "tema": "Gestão x governança (lacunas)", "tipo": "lacunas", "multipla_resposta": false, "enunciado": "Complete as lacunas do texto.", "texto_lacunas": "Toda empresa precisa da tecnologia da informação. Hoje em dia, a tecnologia se transformou em {{1}} , e não um mero luxo. Pequenos negócios, que eram gerenciados de forma manual, passaram a ser informatizados, mesmo que em baixa escala.No caso das grandes empresas, o cenário é ainda mais significativo: o dia a dia é realizado pela gestão, e a gestão é monitorada pela {{2}} . A governança, entre outros, se preocupa com conformidade, segurança, viabilidade e alinhamento das atividades ao planejamento {{3}} . Esse alinhamento é fundamental para que a empresa possa se manter ativa, utilizando os seus {{4}} de forma otimizada e eficiente.", "opcoes_lacunas": ["funcionários, ativos, recursos", "governança", "operacional", "necessidade"], "corretas": ["necessidade", "governança", "operacional", "funcionários, ativos, recursos"], "explicacao": "A TI virou NECESSIDADE (não luxo). A gestão faz o dia a dia e é monitorada pela GOVERNANÇA, que cuida de conformidade, segurança, viabilidade e alinhamento ao planejamento OPERACIONAL, para que a empresa use seus FUNCIONÁRIOS, ATIVOS e RECURSOS de forma otimizada.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U1-Q12", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.11 Encadeamento", "tipo": "associacao"}, "tema": "Atividades da gestão (planejar, construir, entregar, monitorar)", "tipo": "associacao", "multipla_resposta": false, "enunciado": "Em relação às diversas atividades relacionadas à gerência e gestão, cada uma delas tem uma atuação específica. Analise os quadros a seguir e associe cada um com a sua função específica.", "pares": [{"item": "Nesta atividade, que ocorre após o planejamento, é realizada a solução que se deseja, por exemplo: o desenvolvimento e teste de um novo software.", "resposta": "Construção."}, {"item": "Nesta atividade, que ocorre após o desenvolvimento e teste, é feita a implantação de um novo software.", "resposta": "Entrega."}, {"item": "Depois da entrega feita, é necessário acompanhar o desempenho e uso da solução.", "resposta": "Monitoramento."}, {"item": "Nesta atividade, a gestão se preocupa em definir o que vai ser construído, por exemplo: um software de apoio. Essa definição deve ser feita antes mesmo da realização, ou seja, é necessário estruturar passos para que a realização possa acontecer.", "resposta": "Planejamento."}], "opcoes_associacao": ["Entrega.", "Monitoramento.", "Planejamento.", "Construção."], "corretas": ["Construção.", "Entrega.", "Monitoramento.", "Planejamento."], "explicacao": "Ordem das atividades da gestão: PLANEJAMENTO (definir o que será feito) → CONSTRUÇÃO (desenvolver e testar) → ENTREGA (implantar) → MONITORAMENTO (acompanhar desempenho e uso).", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U1-Q13", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.12 Quiz", "tipo": "quiz"}, "tema": "Propósitos da governança (economicidade)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A governança atua com vários propósitos e um deles se refere ao fato de buscar o maior retorno possível com os menores custos. Esse aspecto é chamado de:", "alternativas": {"a": "feedback.", "b": "economicidade.", "c": "agilidade.", "d": "estratégia."}, "corretas": ["b"], "explicacao": "O aspecto “custo” se relaciona com economicidade.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U1-Q14", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.12 Quiz", "tipo": "quiz"}, "tema": "Eficácia x eficiência", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Dois conceitos muito claros são utilizados para balizar a atuação da governança e gestão: a eficácia e a eficiência. Na prática, elas significam respectivamente:", "alternativas": {"a": "fazer com custo não otimizado e fazer, se possível, de forma correta.", "b": "fazer sem considerar conformidade, e fazer considerando os custos.", "c": "fazer corretamente e fazer corretamente da forma mais otimizada.", "d": "fazer corretamente, e fazer sem considerar conformidade."}, "corretas": ["c"], "explicacao": "A eficácia se preocupa em fazer certo, já a eficiência busca fazer o certo de forma otimizada.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U1-Q15", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.12 Quiz", "tipo": "quiz"}, "tema": "Qualidade da informação", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "É absolutamente fundamental que a informação tenha qualidade. Dentre as alternativas abaixo, qual não se relaciona com qualidade da informação?", "alternativas": {"a": "Consistência.", "b": "Precisão.", "c": "Relevância.", "d": "Entrega tardia."}, "corretas": ["d"], "explicacao": "A entrega tardia prejudica a qualidade da informação.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U1-Q16", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.12 Quiz", "tipo": "quiz"}, "tema": "Compliance", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Como são conhecidos o alinhamento e o cumprimento de leis e normas?", "alternativas": {"a": "Eficiência.", "b": "Compliance.", "c": "Normatização.", "d": "Eficácia."}, "corretas": ["b"], "explicacao": "O compliance se refere ao alinhamento e cumprimento de leis e normas.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U1-Q17", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.12 Quiz", "tipo": "quiz"}, "tema": "Comunicação", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A informação precisa fluir de forma adequada, para que as decisões possam ser tomadas de forma eficiente. Por isso, é necessário gerenciar bem a:", "alternativas": {"a": "compliance.", "b": "eficácia.", "c": "comunicação.", "d": "eficiência."}, "corretas": ["c"], "explicacao": "A comunicação faz a informação fluir de forma adequada.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U1-Q18", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.13 Avaliação Final - Unidade 1", "tipo": "avaliacao_final"}, "tema": "Controle e governança", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A mudança é uma constante universal. Ela se aplica a todos, não somente ao mundo da tecnologia. Contudo, com o avanço das tecnologias digitais, vive-se uma mudança acelerada, que está criando vários cenários que dificultam a gestão da TI. É necessário agir antes dos problemas acontecerem e, caso aconteçam, a resposta precisa ser adequada. Quanto a esse cenário atual, assinale a alternativa incorreta.", "alternativas": {"a": "Os custos associados ao controle são superiores aos custos de não controlar.", "b": "A governança é um instrumento de controle da gestão.", "c": "A alocação imprópria de recursos costuma decorrer da falta de controle.", "d": "O retorno sobre o investimento precisa ser superavitário."}, "corretas": ["a"], "explicacao": "A questão pede a INCORRETA. Os custos de NÃO controlar (fraudes, desperdício, alocação imprópria) costumam ser bem maiores que os custos do controle; por isso a governança existe.", "por_que_erradas": {"b": "Correta: a governança é um instrumento de controle da gestão.", "c": "Correta: falta de controle leva a alocação imprópria de recursos.", "d": "Correta: o retorno sobre o investimento deve ser positivo."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U1-Q19", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.13 Avaliação Final - Unidade 1", "tipo": "avaliacao_final"}, "tema": "Retorno sobre o investimento (ROI)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A TI costuma ter orçamentos altíssimos. Um antivírus, por exemplo, pode custar mais de 1 milhão de reais. Por isso, a governança analisa questões associadas ao quanto vale a pena aquela TI, que é conhecida como:", "alternativas": {"a": "custo de pessoal.", "b": "valores das licenças.", "c": "custo de atualização.", "d": "retorno sobre o investimento."}, "corretas": ["d"], "explicacao": "Avaliar 'quanto vale a pena' um investimento de TI é medir o retorno sobre o investimento (ROI): o benefício gerado em relação ao custo.", "por_que_erradas": {"a": "Custo de pessoal é só uma parcela do custo, não a análise de valor.", "b": "Valor das licenças é custo, não retorno.", "c": "Custo de atualização é custo, não retorno."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U1-Q20", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.13 Avaliação Final - Unidade 1", "tipo": "avaliacao_final"}, "tema": "Caso ENRON e Sarbanes-Oxley (SOX)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "O caso ENRON trouxe um alerta para a necessidade de regulamentação em vários setores, por causa de problemas associados a gestões fraudulentas e fraudes financeiras. Para melhorar essa regulamentação, foi criada a:", "alternativas": {"a": "Lei Geral de Proteção de Dados (LGPD).", "b": "Lei de Software.", "c": "Lei de Responsabilidade Fiscal.", "d": "Lei Sarbanes-Oxley."}, "corretas": ["d"], "explicacao": "Após fraudes contábeis como Enron e WorldCom, os EUA criaram a Lei Sarbanes-Oxley (SOX, 2002), que exige controles internos, transparência financeira e responsabilização dos executivos.", "por_que_erradas": {"a": "A LGPD (2018, Brasil) trata de dados pessoais, não de fraudes contábeis.", "b": "A Lei de Software (Brasil) trata de propriedade intelectual de programas.", "c": "A Lei de Responsabilidade Fiscal (Brasil) trata de finanças públicas."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U1-Q21", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.13 Avaliação Final - Unidade 1", "tipo": "avaliacao_final"}, "tema": "Importância da governança", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A implantação da governança (não apenas de TI) se mostra cada vez mais como uma necessidade nas empresas. Ela dificulta fraudes, decisões que beneficiam os gestores em detrimento dos acionistas e favorece o cumprimento de normas e ações baseadas em boas práticas. Sobre a governança, assinale a alternativa incorreta.", "alternativas": {"a": "Ela traz impactos sobre a gestão e todos os mecanismos de administração.", "b": "A governança busca diminuir o conflito de interesses.", "c": "A governança acaba por impor métodos e práticas que melhoram a eficiência operacional.", "d": "A governança é necessária apenas em empresas privadas."}, "corretas": ["d"], "explicacao": "A questão pede a INCORRETA. A governança é necessária em qualquer organização: privada, pública ou do terceiro setor. Dizer 'apenas em empresas privadas' é falso.", "por_que_erradas": {"a": "Correta: impacta a gestão e a administração.", "b": "Correta: reduz conflitos de interesse entre gestores e acionistas.", "c": "Correta: impõe boas práticas que melhoram a eficiência."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U1-Q22", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.13 Avaliação Final - Unidade 1", "tipo": "avaliacao_final"}, "tema": "Gestão de riscos", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A governança, dentre outras atribuições, busca gerenciar fatores que colocam a empresa ou a instituição em uma situação possivelmente danosa. Essa atividade, que também envolve a gestão, é conhecida como:", "alternativas": {"a": "gestão de riscos.", "b": "gestão de pessoal.", "c": "gestão de cursos.", "d": "gestão de marketing."}, "corretas": ["a"], "explicacao": "Gerenciar fatores que podem colocar a organização em situação danosa é a gestão de riscos.", "por_que_erradas": {"b": "Gestão de pessoal trata de colaboradores.", "c": "'Gestão de cursos' não é um conceito da governança.", "d": "Gestão de marketing trata de mercado e imagem."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U1-Q23", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.13 Avaliação Final - Unidade 1", "tipo": "avaliacao_final"}, "tema": "Finalidade da TI", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Praticamente todas as empresas utilizam tecnologia da informação. Desde a pequena empresa, com um único computador e uma impressora de nota fiscal, até as grandes empresas com mais de mil computadores. Em todas elas existem investimentos, e obviamente a tecnologia da informação tem uma finalidade, que é:", "alternativas": {"a": "distribuir hardware e software.", "b": "garantir informação de qualidade.", "c": "desenvolver sistemas.", "d": "informatizar a empresa."}, "corretas": ["b"], "explicacao": "A finalidade da TI é garantir informação de qualidade para apoiar decisões e operações. Hardware, software e sistemas são meios para isso.", "por_que_erradas": {"a": "Distribuir hardware e software é meio, não fim.", "c": "Desenvolver sistemas é meio para gerar informação.", "d": "Informatizar é meio; o objetivo é a informação de qualidade."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U1-Q24", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.13 Avaliação Final - Unidade 1", "tipo": "avaliacao_final"}, "tema": "Papel da gestão", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Gestão e governança andam de braços dados – sem uma a outra corre riscos de não fazer certo. Considerando os papéis de cada uma, dizemos que o papel da gestão é:", "alternativas": {"a": "instalar, torcer e rezar.", "b": "implantar, monitorar e planejar.", "c": "dirigir, monitorar e comprar.", "d": "planejar, executar e controlar."}, "corretas": ["d"], "explicacao": "Entre as opções, a que descreve o papel da gestão é planejar, executar e controlar (ciclo administrativo clássico, próximo do 'planejar, construir, entregar e monitorar' do COBIT).", "por_que_erradas": {"a": "Alternativa jocosa, sem fundamento.", "b": "Mistura atividades fora de ordem: monitorar antes de planejar.", "c": "Dirigir e monitorar são atividades da GOVERNANÇA; 'comprar' não é função-base."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U1-Q25", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.13 Avaliação Final - Unidade 1", "tipo": "avaliacao_final"}, "tema": "Atividades da governança (avaliar)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Na sua atuação, a governança verifica o que está acontecendo, isto é, ela verifica se o que está sendo feito corresponde ao esperado, principalmente com medidas que permitem analisar o desempenho da TI. Essa atividade é conhecida como:", "alternativas": {"a": "comprar.", "b": "planejar.", "c": "vender.", "d": "avaliar."}, "corretas": ["d"], "explicacao": "Verificar se o que está sendo feito corresponde ao esperado, com medidas de desempenho, é AVALIAR, uma das três atividades da governança (avaliar, dirigir, monitorar).", "por_que_erradas": {"a": "Comprar não é atividade da governança.", "b": "Planejar é atividade da gestão.", "c": "Vender não é atividade da governança."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U1-Q26", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.13 Avaliação Final - Unidade 1", "tipo": "avaliacao_final"}, "tema": "Frameworks (COBIT)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A governança se apoia em frameworks, e existem vários deles, mas um é especialmente feito para a governança. Como é conhecido esse framework?", "alternativas": {"a": "COBIT.", "b": "SOX.", "c": "PHP.", "d": "ITIL."}, "corretas": ["a"], "explicacao": "O COBIT é o framework feito especificamente para governança (e gestão) de TI.", "por_que_erradas": {"b": "SOX é uma lei americana, não um framework.", "c": "PHP é uma linguagem de programação.", "d": "ITIL é voltado ao gerenciamento de serviços de TI."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U1-Q27", "disciplina": "gov", "unidade": 1, "origem": {"questionario": "1.13 Avaliação Final - Unidade 1", "tipo": "avaliacao_final"}, "tema": "Frameworks (ITIL)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A área de serviços de TIC é muito importante, e o desempenho da área deve ser monitorado. Em especial, existe um modelo de boas práticas que, dentre outras, avalia o desempenho com indicadores, como SLA. Estamos falando do:", "alternativas": {"a": "ITIL.", "b": "COBIT.", "c": "SOX.", "d": "PHP."}, "corretas": ["a"], "explicacao": "O ITIL é o conjunto de boas práticas de gerenciamento de serviços de TI, que mede desempenho com indicadores como o SLA (acordo de nível de serviço).", "por_que_erradas": {"b": "COBIT é voltado à governança.", "c": "SOX é lei.", "d": "PHP é linguagem de programação."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U2-Q01", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.4 Quiz", "tipo": "quiz"}, "tema": "Planejamento estratégico (missão)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Toda empresa, instituição, repartição ou órgão de governo tem sua existência associada a um propósito, que diz quem ela é e o que pretende fazer. Esse conceito se relaciona com:", "alternativas": {"a": "missão.", "b": "valor.", "c": "mercado.", "d": "visão."}, "corretas": ["a"], "explicacao": "A missão está diretamente associada ao propósito da empresa.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U2-Q02", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.4 Quiz", "tipo": "quiz"}, "tema": "Planejamento estratégico (valores)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Uma determinada empresa defende, na sua concepção e comportamento, que sempre atuará de forma ética. Mas, em um dado momento, um gerente resolveu usar software pirata. O que foi atingido nesse caso?", "alternativas": {"a": "O valor de mercado da empresa.", "b": "O conjunto de valores da empresa.", "c": "A imagem da empresa.", "d": "O valor dos produtos da empresa."}, "corretas": ["b"], "explicacao": "Se a empresa se propõe a trabalhar de forma ética, a pirataria vai contra os valores da empresa.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U2-Q03", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.4 Quiz", "tipo": "quiz"}, "tema": "Planejamento estratégico institucional (PEI)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "O planejamento estratégico institucional (PEI) é fundamental para garantir a perenidade da instituição durante toda a sua existência. Sobre ele, é errado dizer que:", "alternativas": {"a": "nem sempre precisa estar alinhado aos objetivos da empresa.", "b": "deve ser amplamente divulgado com os colaboradores.", "c": "deve ser aprimorado sempre que necessário.", "d": "traz um norte às ações da empresa."}, "corretas": ["a"], "explicacao": "O PEI tem que estar alinhado aos objetivos da empresa.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U2-Q04", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.4 Quiz", "tipo": "quiz"}, "tema": "Análise SWOT", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Existe uma ferramenta extremamente útil que é usada para diagnosticar a empresa, com suas forças, fraquezas, oportunidades e ameaças. Trata-se de qual ferramenta?", "alternativas": {"a": "Balancete financeiro.", "b": "Análise de mercado.", "c": "Análise SWOT.", "d": "Análise de produto."}, "corretas": ["c"], "explicacao": "A análise SWOT é uma ferramenta que diagnostica forças, fraquezas, oportunidades e ameaças.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U2-Q05", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.4 Quiz", "tipo": "quiz"}, "tema": "Cinco forças de Porter", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Toda empresa está submetida a forças externas que a tornam suscetível a variações no mercado em si. Existe um gráfico que ilustra essas forças, como fornecedores, clientes e novos produtos. Esse artefato é chamado de:", "alternativas": {"a": "diagrama de fluxo de dados.", "b": "modelo relacional.", "c": "diagrama E-R.", "d": "modelo de forças de Porter."}, "corretas": ["d"], "explicacao": "O modelo de forças de Porter analisa o ambiente em que a empresa está inserida.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U2-Q06", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.8 Quiz", "tipo": "quiz"}, "tema": "Auditoria (tipos)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A auditoria é fundamental em qualquer sistema de governança. Quanto a quem realiza a auditoria, existem duas categorias, que são:", "alternativas": {"a": "interna e externa.", "b": "simples e complexa.", "c": "gratuita e paga.", "d": "local e global."}, "corretas": ["a"], "explicacao": "Quanto a quem realiza, a auditoria pode ser INTERNA (feita pela própria organização) ou EXTERNA (feita por terceiros independentes).", "por_que_erradas": {"b": "Simples/complexa não é classificação de auditoria.", "c": "Gratuita/paga não é classificação.", "d": "Local/global não é classificação."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U2-Q07", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.8 Quiz", "tipo": "quiz"}, "tema": "Auditoria (escopo)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Cada auditoria tem sua abrangência, ou seja, os seus limites. Não se audita tudo de uma só vez. A abrangência de uma auditoria é conhecida conceitualmente como:", "alternativas": {"a": "agente.", "b": "escopo.", "c": "critério.", "d": "local."}, "corretas": ["b"], "explicacao": "A abrangência, ou os limites, de uma auditoria é o seu ESCOPO.", "por_que_erradas": {"a": "Agente é quem audita.", "c": "Critério é a referência usada para comparar (norma, política).", "d": "Local não define abrangência."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U2-Q08", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.8 Quiz", "tipo": "quiz"}, "tema": "Auditoria (constatações)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Toda auditoria encontra informações, indicadores e evidências que representam fatos ou registros, que são conhecidos como:", "alternativas": {"a": "constatações.", "b": "escopos.", "c": "critérios.", "d": "valores."}, "corretas": ["a"], "explicacao": "Fatos, registros e evidências encontrados pela auditoria são as CONSTATAÇÕES (achados).", "por_que_erradas": {"b": "Escopo é a abrangência.", "c": "Critério é a referência de comparação.", "d": "Valores não é termo técnico de auditoria."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U2-Q09", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.8 Quiz", "tipo": "quiz"}, "tema": "Normas (ISO)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A entidade não governamental independente, que desenvolve e publica normas internacionais para uma ampla variedade de áreas, é conhecida como:", "alternativas": {"a": "PMBOK.", "b": "ITIL.", "c": "COBIT.", "d": "ISO."}, "corretas": ["d"], "explicacao": "A ISO (International Organization for Standardization) é a entidade não governamental independente que publica normas internacionais.", "por_que_erradas": {"a": "PMBOK é guia de gerenciamento de projetos do PMI.", "b": "ITIL é conjunto de boas práticas de serviços de TI.", "c": "COBIT é framework de governança da ISACA."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U2-Q10", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.8 Quiz", "tipo": "quiz"}, "tema": "Segurança da informação (tríade CID)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A segurança da informação é um dos pilares do COBIT, que se relaciona com a governança. Com base nisso, quais são os princípios básicos da segurança da informação?", "alternativas": {"a": "Integridade, externalidade e assiduidade.", "b": "Conformabilidade, verificabilidade e assiduidade.", "c": "Confidencialidade, integridade e disponibilidade.", "d": "Assiduidade, verificabilidade e confidencialidade."}, "corretas": ["c"], "explicacao": "Os princípios básicos da segurança da informação são Confidencialidade, Integridade e Disponibilidade (tríade CID/CIA).", "por_que_erradas": {"a": "Externalidade e assiduidade não são princípios de segurança.", "b": "Termos inventados.", "d": "Assiduidade e verificabilidade não fazem parte da tríade."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U2-Q11", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.10 Quiz", "tipo": "quiz"}, "tema": "Domínios da governança (conformidade)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Dentre os diversos domínios da governança de TI, considerando o COBIT 2019, um deles reforça a necessidade de cumprir leis, normas e procedimentos, de modo que a governança possa ser efetiva. Esse domínio se refere a:", "alternativas": {"a": "gestão de pessoas.", "b": "gestão financeira.", "c": "gestão de ativos.", "d": "gestão de conformidade."}, "corretas": ["d"], "explicacao": "A gestão de conformidade se refere ao cumprimento de normas e dispositivos legais.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U2-Q12", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.10 Quiz", "tipo": "quiz"}, "tema": "Entrega de valor", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A governança tem um foco muito importante no que diz respeito ao retorno efetivo que a TI traz à empresa. Esse retorno é chamado de:", "alternativas": {"a": "entrega de produtos.", "b": "entrega de recursos.", "c": "entrega financeira.", "d": "entrega de valor."}, "corretas": ["d"], "explicacao": "A entrega de valor se refere ao retorno que a TI traz ao negócio.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U2-Q13", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.10 Quiz", "tipo": "quiz"}, "tema": "Princípios da TI (visão holística)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Ao atuar, a TI é balizada por princípios que a norteiam e que devem ser considerados por todos os stakeholders no desenvolvimento de suas atividades. Um deles trata da visão da empresa como um todo, não apenas um conjunto de partes. Com base nisso, assinale a alternativa que indica esse princípio.", "alternativas": {"a": "Uso racional de recursos.", "b": "Gestão da demanda.", "c": "Atendimento de qualidade.", "d": "Integração e visão holística."}, "corretas": ["d"], "explicacao": "A visão holística traz a percepção de que a empresa é um todo com suas partes interagindo entre si.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U2-Q14", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.10 Quiz", "tipo": "quiz"}, "tema": "Princípios da TI (limites éticos)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Na atuação da TI, não se pode jamais atuar considerando que os fins justifiquem os meios. Há um princípio que norteia essa visão, que é o de:", "alternativas": {"a": "gestão da demanda.", "b": "gestão de portfólio.", "c": "uso racional de recursos.", "d": "atuação dentro dos limites éticos."}, "corretas": ["d"], "explicacao": "A atuação dentro dos limites éticos é um princípio de TI que norteia a sua ação, considerando que os fins não justificam os meios, se estes últimos não são apropriados.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U2-Q15", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.10 Quiz", "tipo": "quiz"}, "tema": "Gestão de portfólio", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Em muitas situações, a empresa tem sistemas construídos que precisa alterar, e tem sistemas que sequer foram construídos. Nesse tipo de cenário, os usuários lutam entre si para conseguir a prioridade que desejam. Mas a TI e a governança precisam tratar dessa priorização, em uma atuação conhecida como:", "alternativas": {"a": "gestão de pessoal.", "b": "gestão de recursos.", "c": "gestão de versões.", "d": "gestão de portfólio."}, "corretas": ["d"], "explicacao": "A gestão de portfólio trata da priorização entre sistemas.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U2-Q16", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.11 Lacunas", "tipo": "lacunas"}, "tema": "Gestão de recursos e conformidade (lacunas)", "tipo": "lacunas", "multipla_resposta": false, "enunciado": "Complete as lacunas do texto.", "texto_lacunas": "Infelizmente, não há empresa que possa dizer que tem recursos infinitos. Em razão disso, é necessário que haja um gerenciamento de {{1}} para que os objetivos sejam alcançados de forma eficiente e eficaz. Mas não basta apenas ser lucrativo e dar retorno, é preciso que isso seja feito em {{2}} com as normas e leis existentes, atuando de forma {{3}} com desempenho {{4}} .", "opcoes_lacunas": ["recursos, disponibilidade", "conformidade", "ética, correta, apropriada", "adequado, satisfatório"], "corretas": ["recursos, disponibilidade", "conformidade", "ética, correta, apropriada", "adequado, satisfatório"], "explicacao": "Como os recursos não são infinitos, é preciso gerenciar RECURSOS. E não basta dar lucro: é preciso estar em CONFORMIDADE com normas e leis, atuar de forma ÉTICA e com desempenho ADEQUADO.", "por_que_erradas": {}, "fonte_gabarito": "especialista"}, {"id": "GOV-U2-Q17", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.12 Encadeamento", "tipo": "associacao"}, "tema": "Princípios e domínios da TI (associação)", "tipo": "associacao", "multipla_resposta": false, "enunciado": "Em relação aos diversos princípios, domínios e aspectos relacionados à atuação da TI, cada um tem seu foco. Analise as sentenças a seguir e associe cada uma com a sua função específica.", "pares": [{"item": "A governança busca fazer com que haja uma devida priorização entre as atividades relacionadas ao atendimento das necessidades dos usuários.", "resposta": "Gestão de demanda."}, {"item": "Neste aspecto, a gestão se concentra em fazer com que a TI atue seguindo normas e leis.", "resposta": "Garantia de conformidade."}, {"item": "Neste princípio, a governança se preocupa com o retorno que a TI traz ao negócio, fazendo com que os gastos sejam apropriados e sem desperdício.", "resposta": "Uso racional de recursos."}, {"item": "Neste domínio, a governança entende que não há dinheiro infinito, sendo necessário gerenciar o que se tem.", "resposta": "Gestão de recursos."}], "opcoes_associacao": ["Gestão de demanda.", "Uso racional de recursos.", "Garantia de conformidade.", "Gestão de recursos."], "corretas": ["Gestão de demanda.", "Garantia de conformidade.", "Uso racional de recursos.", "Gestão de recursos."], "explicacao": "Priorizar o atendimento das necessidades dos usuários = GESTÃO DE DEMANDA. Seguir normas e leis = GARANTIA DE CONFORMIDADE. Retorno sem desperdício = USO RACIONAL DE RECURSOS. 'Não há dinheiro infinito' = GESTÃO DE RECURSOS.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U2-Q18", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.13 Avaliação Final - Unidade 2", "tipo": "avaliacao_final"}, "tema": "Planejamento estratégico (missão, visão e valores)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Quando constituídas, as empresas devem nascer com objetivos e propósitos. No planejamento estratégico institucional, isso se consubstancia em:", "alternativas": {"a": "visão, valores e funções.", "b": "missão, visão e valores.", "c": "missão, formação e construção.", "d": "missão, objetivos e parâmetros."}, "corretas": ["b"], "explicacao": "Os objetivos e propósitos da organização no PEI se expressam em MISSÃO (por que existe), VISÃO (onde quer chegar) e VALORES (como se comporta).", "por_que_erradas": {"a": "Falta a missão; 'funções' não é elemento do PEI.", "c": "Formação e construção não são elementos do PEI.", "d": "Objetivos e parâmetros vêm depois, derivados da missão e visão."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U2-Q19", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.13 Avaliação Final - Unidade 2", "tipo": "avaliacao_final"}, "tema": "Análise SWOT", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Ao buscar se situar diante do mercado, as empresas analisam o mercado buscando entender suas forças, fraquezas, oportunidades e ameaças. Existe uma ferramenta apropriada para isso. Assinale a alternativa que apresenta corretamente essa ferramenta.", "alternativas": {"a": "Análise financeira.", "b": "Análise de conformidade.", "c": "Análise SWOT.", "d": "Análise legal."}, "corretas": ["c"], "explicacao": "Forças, fraquezas (internas), oportunidades e ameaças (externas) = análise SWOT (Strengths, Weaknesses, Opportunities, Threats).", "por_que_erradas": {"a": "Análise financeira olha números contábeis.", "b": "Análise de conformidade verifica aderência a normas.", "d": "Análise legal verifica aspectos jurídicos."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U2-Q20", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.13 Avaliação Final - Unidade 2", "tipo": "avaliacao_final"}, "tema": "Cinco forças de Porter", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Toda empresa se situa em um ambiente que tem organizações concorrentes, pressão de fornecedores, ameaça de novos entrantes e de produtos substitutos, em que essas forças são conhecidas como:", "alternativas": {"a": "forças de Porter.", "b": "forças de ambiente.", "c": "forças de produto.", "d": "forças de SWOT."}, "corretas": ["a"], "explicacao": "Concorrentes, fornecedores, novos entrantes, produtos substitutos (e clientes) formam as Cinco Forças de Porter.", "por_que_erradas": {"b": "'Forças de ambiente' não é o nome do modelo.", "c": "'Forças de produto' não existe como modelo.", "d": "SWOT é outra ferramenta (forças, fraquezas, oportunidades, ameaças)."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U2-Q21", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.13 Avaliação Final - Unidade 2", "tipo": "avaliacao_final"}, "tema": "Etapas do planejamento estratégico", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "O planejamento estratégico institucional tem fases bem definidas, que o tornam extremamente importante em qualquer empresa. Ele inicia com a definição de missão, visão e valores. Após isso, o que é realizado?", "alternativas": {"a": "Uma análise de cenário.", "b": "Implementação imediata.", "c": "Monitoramento e avaliação.", "d": "Elaboração de plano de ação."}, "corretas": ["a"], "explicacao": "Depois de definir missão, visão e valores, faz-se a ANÁLISE DE CENÁRIO (ambiente interno e externo, ex.: SWOT, Porter), para então definir objetivos, plano de ação e monitoramento.", "por_que_erradas": {"b": "Implementar sem analisar o cenário é precipitado.", "c": "Monitoramento é a última etapa.", "d": "O plano de ação vem depois da análise e dos objetivos."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U2-Q22", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.13 Avaliação Final - Unidade 2", "tipo": "avaliacao_final"}, "tema": "Objetivos estratégicos", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Os fins a serem perseguidos pela organização para o cumprimento de sua missão institucional e o alcance de sua visão de futuro são conhecidos como:", "alternativas": {"a": "objetivos financeiros.", "b": "objetivos SWOT.", "c": "objetivos estratégicos.", "d": "objetivos legais."}, "corretas": ["c"], "explicacao": "Os fins que a organização persegue para cumprir a missão e alcançar a visão são os OBJETIVOS ESTRATÉGICOS.", "por_que_erradas": {"a": "Objetivos financeiros são só um tipo de objetivo.", "b": "'Objetivos SWOT' não existe.", "d": "Objetivos legais não é o termo do PEI."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U2-Q23", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.13 Avaliação Final - Unidade 2", "tipo": "avaliacao_final"}, "tema": "PEI x PETIC", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "O planejamento estratégico de TIC (PETIC) tem um relacionamento direto com o planejamento estratégico institucional (PEI). É correto dizer que:", "alternativas": {"a": "só é possível construir o PETIC depois de construir o PEI.", "b": "o PETIC é feito antes do PEI.", "c": "o PEI depende do PETIC para ser feito.", "d": "ambos são feitos ao mesmo tempo."}, "corretas": ["a"], "explicacao": "O PETIC (planejamento estratégico de TIC) deriva do PEI: a TI planeja como apoiar a estratégia do negócio, portanto só pode ser feito DEPOIS do PEI.", "por_que_erradas": {"b": "Fazer o PETIC antes inverte a lógica do alinhamento.", "c": "O PEI não depende do PETIC; é o contrário.", "d": "Precisam ser sequenciais, pois um orienta o outro."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U2-Q24", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.13 Avaliação Final - Unidade 2", "tipo": "avaliacao_final"}, "tema": "Desvio de governança", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Em muitas situações, a governança acaba por não acontecer como deveria. Monitoramentos não são feitos ou ações não apropriadas são tomadas, o que se configura como:", "alternativas": {"a": "incoerência entre PEI e PETIC.", "b": "desvio de governança.", "c": "PEI construído sem parâmetros apropriados.", "d": "falta de ação assertiva."}, "corretas": ["b"], "explicacao": "Quando monitoramentos não são feitos ou ações inadequadas são tomadas, há DESVIO DE GOVERNANÇA: a governança não acontece como deveria.", "por_que_erradas": {"a": "Incoerência PEI x PETIC é problema de alinhamento de planos.", "c": "PEI sem parâmetros é falha de planejamento.", "d": "'Falta de ação assertiva' é genérico, não o termo técnico."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U2-Q25", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.13 Avaliação Final - Unidade 2", "tipo": "avaliacao_final"}, "tema": "Auditoria", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A auditoria é um instrumento fundamental da governança, pois é usada para monitoramento e verificação de conformidade, entre outros. Com base nisso, assinale a alternativa correta sobre auditoria.", "alternativas": {"a": "Serve apenas para confirmar o que já existe, sem maiores consequências.", "b": "Deve ser feita tanto com auditorias internas quanto externas, para garantir mais independência.", "c": "É vista mais como um empecilho do que como uma solução de melhoria.", "d": "É um gasto desnecessário."}, "corretas": ["b"], "explicacao": "Auditorias internas e externas se complementam; a externa traz mais independência e imparcialidade. A auditoria é instrumento de melhoria, não gasto inútil.", "por_que_erradas": {"a": "A auditoria gera recomendações e ações corretivas.", "c": "É instrumento de melhoria.", "d": "É investimento em controle e conformidade."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U2-Q26", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.13 Avaliação Final - Unidade 2", "tipo": "avaliacao_final"}, "tema": "Normas de segurança (família ISO 27000)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A segurança da informação é um dos aspectos de maior preocupação por parte da governança. Além disso, existe uma série ISO que é diretamente relacionada com a segurança. Qual série é essa?", "alternativas": {"a": "ISO 27000.", "b": "ISO 10000.", "c": "ISO 9001.", "d": "ISO 14001."}, "corretas": ["a"], "explicacao": "A família ISO/IEC 27000 (27001, 27002...) trata de segurança da informação.", "por_que_erradas": {"b": "ISO 10000 trata de diretrizes de gestão da qualidade.", "c": "ISO 9001 trata de gestão da qualidade.", "d": "ISO 14001 trata de gestão ambiental."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U2-Q27", "disciplina": "gov", "unidade": 2, "origem": {"questionario": "2.13 Avaliação Final - Unidade 2", "tipo": "avaliacao_final"}, "tema": "Segurança da informação (confidencialidade)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Ao realizar uma auditoria em uma empresa, o auditor encontrou um sério problema: todos os usuários tinham a mesma senha e o mesmo login. Essa é uma séria inconformidade, que coloca em risco o princípio de segurança da informação, conhecido como:", "alternativas": {"a": "confidencialidade.", "b": "assiduidade.", "c": "usabilidade.", "d": "acessibilidade."}, "corretas": ["a"], "explicacao": "Com o mesmo login e senha para todos, não há como restringir o acesso a quem é autorizado nem saber quem fez o quê: a CONFIDENCIALIDADE fica comprometida (e também a rastreabilidade).", "por_que_erradas": {"b": "Assiduidade não é princípio de segurança.", "c": "Usabilidade é facilidade de uso.", "d": "Acessibilidade é inclusão de pessoas com deficiência."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U3-Q01", "disciplina": "gov", "unidade": 3, "origem": {"questionario": "3.5 Quiz", "tipo": "quiz"}, "tema": "COBIT (objetivos)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "O COBIT é um framework largamente utilizado em governança. Seu uso é disseminado e traz reais vantagens, mas, dentre as alternativas abaixo, há uma exceção. Assinale a alternativa incorreta sobre o objetivo do COBIT.", "alternativas": {"a": "Analisa os setores da empresa separadamente, sem considerar as suas interações.", "b": "Aplica um modelo integrado de gestão e governança.", "c": "Orienta a resultados.", "d": "Busca satisfazer as necessidades das partes interessadas."}, "corretas": ["a"], "explicacao": "Na verdade, o COBIT analisa os setores da empresa como um todo, considerando as suas interações.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U3-Q02", "disciplina": "gov", "unidade": 3, "origem": {"questionario": "3.5 Quiz", "tipo": "quiz"}, "tema": "COBIT (domínio EDM)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "O COBIT é organizado em domínios e objetivos de governança. Os objetivos de governança se agrupam no domínio:", "alternativas": {"a": "EDM (evaluate, direct and monitor), que é avaliar, dirigir e monitorar.", "b": "DSS (deliver, service and support), que é entregar, prestar serviço e dar suporte.", "c": "BAI (build, acquire and implement), que é construir, adquirir e implementar.", "d": "APO (align, plan and organize), que é alinhar, planejar e organizar."}, "corretas": ["a"], "explicacao": "O domínio EDM é de governança.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U3-Q03", "disciplina": "gov", "unidade": 3, "origem": {"questionario": "3.5 Quiz", "tipo": "quiz"}, "tema": "COBIT (EDM02)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "No domínio EDM (evaluate, direct and monitor) do COBIT, um dos objetivos busca garantir que haja uma entrega eficiente e equilibrada, para que os custos e benefícios sejam claros, transparentes e justificáveis, sendo suportados de forma eficaz e eficiente. Então qual é o objetivo citado?", "alternativas": {"a": "EDM05 – Engajamento garantido das partes interessadas.", "b": "EDM02 – Assegurar a entrega de benefícios.", "c": "EDM03 – Otimização de riscos garantida.", "d": "EDM01 – Implantar e manter uma estrutura de governança."}, "corretas": ["b"], "explicacao": "O objetivo EDM02 busca garantir que haja uma entrega eficiente e equilibrada, para que os custos e benefícios sejam claros, transparentes e justificáveis, sendo suportados de forma eficaz e eficiente.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U3-Q04", "disciplina": "gov", "unidade": 3, "origem": {"questionario": "3.5 Quiz", "tipo": "quiz"}, "tema": "COBIT (APO01)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "O domínio APO do COBIT tem um dos objetivos relacionados com a implementação de uma gestão consistente, com processos de gestão, estruturas organizacionais, papéis e responsabilidades. Estamos falando de:", "alternativas": {"a": "AP03 – Arquitetura corporativa gerenciada.", "b": "AP04 – Inovação gerenciada.", "c": "AP02 – Estratégia gerenciada.", "d": "AP01 – Estrutura de gestão de TI gerenciada."}, "corretas": ["d"], "explicacao": "O AP01 se relaciona com a implementação de uma gestão consistente, com processos de gestão, estruturas organizacionais, papéis e responsabilidades.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U3-Q05", "disciplina": "gov", "unidade": 3, "origem": {"questionario": "3.5 Quiz", "tipo": "quiz"}, "tema": "COBIT (BAI04)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "No domínio BAI do COBIT, um dos objetivos busca garantir que os serviços devem estar disponíveis, com desempenho e escalabilidade garantidas. Sendo assim, qual é esse objetivo?", "alternativas": {"a": "BAI01 – Programas gerenciados.", "b": "BAI04 – Disponibilidade e capacidade gerenciadas.", "c": "BAI08 – Conhecimento gerenciado.", "d": "BAI05 – Mudanças organizacionais gerenciadas."}, "corretas": ["b"], "explicacao": "O domínio BAI04 se refere à disponibilidade e capacidade gerenciadas e busca garantir que os serviços devem estar disponíveis, com desempenho e escalabilidade garantidas.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U3-Q06", "disciplina": "gov", "unidade": 3, "origem": {"questionario": "3.8 Quiz", "tipo": "quiz"}, "tema": "ITIL (características)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "O ITIL contém um conjunto de boas práticas e princípios relacionados com serviços e produtos, que tragam valor aos usuários. Com base nisso, assinale a alternativa incorreta.", "alternativas": {"a": "O ITIL possui princípios orientadores.", "b": "O ITIL depende da plataforma em que será implantado.", "c": "O ITIL é focado na melhoria de serviços.", "d": "O ITIL trata da cadeia de valor de serviço."}, "corretas": ["b"], "explicacao": "Não, o ITIL não depende de plataforma.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U3-Q07", "disciplina": "gov", "unidade": 3, "origem": {"questionario": "3.8 Quiz", "tipo": "quiz"}, "tema": "ITIL (utilidade x garantia)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A funcionalidade oferecida pelo produto ou serviço e que atende à necessidade de um ou mais usuários é conhecida como:", "alternativas": {"a": "foco na melhoria.", "b": "plataforma.", "c": "utilidade.", "d": "princípio orientador."}, "corretas": ["c"], "explicacao": "A utilidade está relacionada à funcionalidade oferecida pelo produto ou serviço e que atende à necessidade de um ou mais usuários.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U3-Q08", "disciplina": "gov", "unidade": 3, "origem": {"questionario": "3.8 Quiz", "tipo": "quiz"}, "tema": "ITIL (gerenciamento de incidentes)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Dentre as diversas práticas de gerenciamento do ITIL, uma se relaciona ao tratamento de problemas quando eles acontecem. Estamos falando de:", "alternativas": {"a": "gerenciamento de configuração.", "b": "gerenciamento de liberação.", "c": "gerenciamento de capacidade.", "d": "gerenciamento de incidentes."}, "corretas": ["d"], "explicacao": "O gerenciamento de incidentes trata dos problemas quando acontecem.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U3-Q09", "disciplina": "gov", "unidade": 3, "origem": {"questionario": "3.8 Quiz", "tipo": "quiz"}, "tema": "ITIL (gerenciamento de disponibilidade)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Em muitas situações, pode ser que um sistema fique fora do ar. Dentre as práticas de gerenciamento, uma delas trata desse problema, que é o:", "alternativas": {"a": "gerenciamento de fornecedores.", "b": "gerenciamento de disponibilidade.", "c": "gerenciamento de liberação.", "d": "gerenciamento de pessoal."}, "corretas": ["b"], "explicacao": "O gerenciamento de disponibilidade trata do fato dos sistemas estarem disponíveis para uso, ou seja, que não estejam fora do ar.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U3-Q10", "disciplina": "gov", "unidade": 3, "origem": {"questionario": "3.8 Quiz", "tipo": "quiz"}, "tema": "ITIL (tendências)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Em termos de tendências, seria errado dizer que o ITIL:", "alternativas": {"a": "tem sido cada vez mais utilizado em empresas que se preocupam com a governança.", "b": "busca cada vez maior integração com frameworks de governança.", "c": "tende a liberar novas versões sempre que necessário.", "d": "já evoluiu tudo o que podia, não cabendo mais atualizações."}, "corretas": ["d"], "explicacao": "Sempre há o que melhorar e atualizar.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U3-Q11", "disciplina": "gov", "unidade": 3, "origem": {"questionario": "3.9 Lacunas", "tipo": "lacunas"}, "tema": "ITIL 4 (gerenciamento de serviços, lacunas)", "tipo": "lacunas", "multipla_resposta": false, "enunciado": "Complete as lacunas do texto.", "texto_lacunas": "Do ponto de vista do ITIL 4, gerenciamento de {{1}} é definido como um conjunto de capacidades organizacionais especializadas que possibilita a entrega de {{2}} aos clientes na forma de serviços. Um serviço, portanto, é uma forma de {{3}} valor trazendo resultados que o {{4}} deseja.", "opcoes_lacunas": ["valor, resultados", "serviços, atividades", "cliente, usuário", "gerar, agregar, trazer"], "corretas": ["serviços, atividades", "valor, resultados", "gerar, agregar, trazer", "cliente, usuário"], "explicacao": "No ITIL 4, gerenciamento de SERVIÇOS é o conjunto de capacidades organizacionais que entrega VALOR aos clientes na forma de serviços. Um serviço é um meio de GERAR (cocriar) valor, entregando os resultados que o CLIENTE deseja.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U3-Q12", "disciplina": "gov", "unidade": 3, "origem": {"questionario": "3.10 Encadeamento", "tipo": "associacao"}, "tema": "ITIL 4 (quatro dimensões)", "tipo": "associacao", "multipla_resposta": false, "enunciado": "O ITIL aborda quatro dimensões do gerenciamento de serviço. Relacione cada uma com o texto equivalente.", "pares": [{"item": "Está relacionado com empresas externas que fornecem insumos e serviços.", "resposta": "Parceiros e fornecedores."}, {"item": "Relaciona-se com os recursos utilizados, em termos de versões e atualização tecnológica.", "resposta": "Informação e tecnologia."}, {"item": "Relaciona-se com o retorno obtido no uso da Tecnologia da Informação.", "resposta": "Fluxo e processo de valor."}, {"item": "Trata das questões de responsabilidade e hierarquia entre funcionários.", "resposta": "Organização e pessoas."}], "opcoes_associacao": ["Parceiros e fornecedores.", "Fluxo e processo de valor.", "Organização e pessoas.", "Informação e tecnologia."], "corretas": ["Parceiros e fornecedores.", "Informação e tecnologia.", "Fluxo e processo de valor.", "Organização e pessoas."], "explicacao": "As 4 dimensões do ITIL 4: ORGANIZAÇÕES E PESSOAS (papéis, hierarquia), INFORMAÇÃO E TECNOLOGIA (recursos e versões), PARCEIROS E FORNECEDORES (terceiros) e FLUXOS DE VALOR E PROCESSOS (como o valor é gerado).", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U3-Q13", "disciplina": "gov", "unidade": 3, "origem": {"questionario": "3.11 Avaliação Final - Unidade 3", "tipo": "avaliacao_final"}, "tema": "COBIT (implantação)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Nas suas mais diversas versões, o COBIT parte de uma premissa: atender à necessidade de desenvolver e trabalhar com modelos e melhores práticas, com a proposta de tornar padrão essa abordagem. A implantação de um framework como o COBIT tem várias características, exceto:", "alternativas": {"a": "mitigar riscos e otimizar processos da empresa.", "b": "alinhar a atuação às necessidades estratégicas da empresa.", "c": "implementar diretrizes e boas práticas de TI.", "d": "é simples e fácil de implantar."}, "corretas": ["d"], "explicacao": "A questão pede a EXCEÇÃO. Implantar COBIT traz mitigação de riscos, alinhamento estratégico e boas práticas, mas NÃO é simples nem fácil: exige planejamento, patrocínio e mudança cultural.", "por_que_erradas": {"a": "É uma característica real.", "b": "É uma característica real.", "c": "É uma característica real."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U3-Q14", "disciplina": "gov", "unidade": 3, "origem": {"questionario": "3.11 Avaliação Final - Unidade 3", "tipo": "avaliacao_final"}, "tema": "Frameworks (vantagens)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Os frameworks, como COBIT e ITIL, trazem diversas vantagens, sendo uma delas:", "alternativas": {"a": "dificultarem o gerenciamento.", "b": "aumentarem a complexidade.", "c": "aumentarem o risco de problemas.", "d": "serem independentes de plataforma."}, "corretas": ["d"], "explicacao": "COBIT e ITIL são independentes de plataforma: valem para qualquer tecnologia, fornecedor ou porte de empresa.", "por_que_erradas": {"a": "Eles facilitam o gerenciamento.", "b": "Eles organizam e reduzem a complexidade.", "c": "Eles reduzem riscos."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U3-Q15", "disciplina": "gov", "unidade": 3, "origem": {"questionario": "3.11 Avaliação Final - Unidade 3", "tipo": "avaliacao_final"}, "tema": "COBIT (abordagem holística)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "O uso de um framework como COBIT deve ter uma abordagem holística, ou seja:", "alternativas": {"a": "abranger toda a empresa.", "b": "reduzir os custos.", "c": "usar um modelo conceitual.", "d": "eliminar os riscos."}, "corretas": ["a"], "explicacao": "Abordagem holística = olhar a empresa como um todo, abrangendo todas as áreas e suas interações (é um princípio do COBIT).", "por_que_erradas": {"b": "Reduzir custos pode ser consequência, não o significado de holístico.", "c": "Usar modelo conceitual não define holístico.", "d": "Nenhum framework elimina riscos."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U3-Q16", "disciplina": "gov", "unidade": 3, "origem": {"questionario": "3.11 Avaliação Final - Unidade 3", "tipo": "avaliacao_final"}, "tema": "ITIL 4 (cadeia de valor de serviço)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Na cadeia de valor do ITIL, uma das atividades busca gerar o entendimento das partes, para que elas participem de forma ativa no atendimento das necessidades dos usuários. Ela é a atividade de:", "alternativas": {"a": "planejar.", "b": "desenho.", "c": "engajar.", "d": "melhorar."}, "corretas": ["c"], "explicacao": "Na cadeia de valor do ITIL 4 (planejar, melhorar, ENGAJAR, desenho e transição, obter/construir, entregar e suportar), ENGAJAR é a atividade que gera entendimento e envolvimento das partes interessadas.", "por_que_erradas": {"a": "Planejar cria entendimento compartilhado da visão e direção.", "b": "Desenho e transição garante que serviços atendam expectativas.", "d": "Melhorar busca melhoria contínua."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U3-Q17", "disciplina": "gov", "unidade": 3, "origem": {"questionario": "3.11 Avaliação Final - Unidade 3", "tipo": "avaliacao_final"}, "tema": "ITIL (gerenciamento de disponibilidade)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Os usuários precisam dos serviços na escala 24x7, ou seja, 24 horas por dia e 7 dias por semana. Para garantir isso, existe a prática de gerenciamento de serviço conhecida como:", "alternativas": {"a": "gerenciamento de conhecimento.", "b": "gerenciamento de fornecedores.", "c": "gerenciamento de capacidade.", "d": "gerenciamento de disponibilidade."}, "corretas": ["d"], "explicacao": "Garantir o serviço 24x7 é papel do gerenciamento de DISPONIBILIDADE.", "por_que_erradas": {"a": "Conhecimento gerencia informações e saberes.", "b": "Fornecedores gerencia terceiros.", "c": "Capacidade garante desempenho para a demanda atual e futura."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U3-Q18", "disciplina": "gov", "unidade": 3, "origem": {"questionario": "3.11 Avaliação Final - Unidade 3", "tipo": "avaliacao_final"}, "tema": "ITIL (gerenciamento de conhecimento)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A operação diária das empresas gera dados e informação. Essas informações, que são relevantes para o funcionamento, devem ser devidamente gerenciadas, e a prática de gerenciamento de serviço que trata disso é a:", "alternativas": {"a": "gerenciamento de capacidade.", "b": "gerenciamento de disponibilidade.", "c": "gerenciamento de conhecimento.", "d": "gerenciamento de fornecedores."}, "corretas": ["c"], "explicacao": "Gerenciar as informações e dados relevantes gerados na operação é o gerenciamento de CONHECIMENTO.", "por_que_erradas": {"a": "Capacidade trata de desempenho e dimensionamento.", "b": "Disponibilidade trata de o serviço estar no ar.", "d": "Fornecedores trata de terceiros."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U3-Q19", "disciplina": "gov", "unidade": 3, "origem": {"questionario": "3.11 Avaliação Final - Unidade 3", "tipo": "avaliacao_final"}, "tema": "ITIL (gerenciamento de capacidade)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Todo ambiente computacional tem uma evolução natural, na qual busca satisfazer às necessidades atuais e futuras quanto ao funcionamento e performance. A prática de gerenciamento que trata disso é a de:", "alternativas": {"a": "gerenciamento de capacidade.", "b": "gerenciamento de fornecedores.", "c": "gerenciamento de conhecimento.", "d": "gerenciamento de disponibilidade."}, "corretas": ["a"], "explicacao": "Atender às necessidades atuais e futuras de desempenho (dimensionar o ambiente) é o gerenciamento de CAPACIDADE.", "por_que_erradas": {"b": "Fornecedores trata de terceiros.", "c": "Conhecimento trata de informação.", "d": "Disponibilidade trata de manter o serviço acessível."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U3-Q20", "disciplina": "gov", "unidade": 3, "origem": {"questionario": "3.11 Avaliação Final - Unidade 3", "tipo": "avaliacao_final"}, "tema": "ITIL (gerenciamento de fornecedores)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Toda empresa demanda produtos e serviços de terceiros. O relacionamento com terceiros é tratada pela prática de:", "alternativas": {"a": "gerenciamento de disponibilidade.", "b": "gerenciamento de capacidade.", "c": "gerenciamento de fornecedores.", "d": "gerenciamento de conhecimento."}, "corretas": ["c"], "explicacao": "O relacionamento com terceiros é tratado pelo gerenciamento de FORNECEDORES.", "por_que_erradas": {"a": "Disponibilidade trata de uptime.", "b": "Capacidade trata de desempenho.", "d": "Conhecimento trata de informação."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U3-Q21", "disciplina": "gov", "unidade": 3, "origem": {"questionario": "3.11 Avaliação Final - Unidade 3", "tipo": "avaliacao_final"}, "tema": "ITIL (gerenciamento de demanda)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Em muitas situações, vários usuários solicitam sistemas novos, atualizações e todo tipo de serviço de TI, e normalmente quer que seu pedido seja atendido de forma imediata. Mas nem sempre dá para atender a todos. A prática do ITIL que trata disso é a de:", "alternativas": {"a": "gerenciamento de disponibilidade.", "b": "gerenciamento de conhecimento.", "c": "gerenciamento de demanda.", "d": "gerenciamento de fornecedores."}, "corretas": ["c"], "explicacao": "Priorizar pedidos quando não dá para atender todos ao mesmo tempo é o gerenciamento de DEMANDA.", "por_que_erradas": {"a": "Disponibilidade trata de uptime.", "b": "Conhecimento trata de informação.", "d": "Fornecedores trata de terceiros."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U3-Q22", "disciplina": "gov", "unidade": 3, "origem": {"questionario": "3.11 Avaliação Final - Unidade 3", "tipo": "avaliacao_final"}, "tema": "Gestão de pessoas na TI", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "No dia a dia da gestão, é necessário ter profissionais qualificados para atender às demandas de serviço dos usuários. Esse gerenciamento é feito pelo(a):", "alternativas": {"a": "gerenciamento de fornecedores.", "b": "gerenciamento de conhecimento.", "c": "gestão de recursos humanos.", "d": "gerenciamento de demanda."}, "corretas": ["c"], "explicacao": "Ter profissionais qualificados (contratar, treinar, alocar) é responsabilidade da gestão de RECURSOS HUMANOS (no ITIL 4, 'gerenciamento de força de trabalho e talentos').", "por_que_erradas": {"a": "Fornecedores trata de terceiros.", "b": "Conhecimento trata de informação.", "d": "Demanda trata de priorizar pedidos."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U4-Q01", "disciplina": "gov", "unidade": 4, "origem": {"questionario": "4.4 Quiz", "tipo": "quiz"}, "tema": "Implantação da governança (fases)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Na implementação de governança, várias são as fases necessárias. A primeira delas, sem dúvida, é:", "alternativas": {"a": "a implantação.", "b": "o planejamento.", "c": "a revisão da implantação.", "d": "a definição do programa de ação."}, "corretas": ["b"], "explicacao": "O planejamento é a primeira fase.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U4-Q02", "disciplina": "gov", "unidade": 4, "origem": {"questionario": "4.4 Quiz", "tipo": "quiz"}, "tema": "Implantação da governança (características)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A implementação da governança de TI tem várias fases, além de características que permeiam todo o processo. Então, sobre ela, é incorreto afirmar que:", "alternativas": {"a": "as lições aprendidas devem servir de base para melhorias.", "b": "é um processo rápido e simples.", "c": "demanda planejamento.", "d": "deve ser revisada periodicamente."}, "corretas": ["b"], "explicacao": "A implementação não é simples nem rápida.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U4-Q03", "disciplina": "gov", "unidade": 4, "origem": {"questionario": "4.4 Quiz", "tipo": "quiz"}, "tema": "Implantação da governança (apoio da alta gestão)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Por ser um processo que envolve planejamento e recursos, a implantação da governança demanda participação de várias instâncias da empresa. Dentre as afirmativas abaixo, qual se relaciona com a implantação e o apoio da alta gestão?", "alternativas": {"a": "A alta gestão não deve ser incomodada pelo processo, que deve ser implantado apenas no nível operacional.", "b": "A governança só deve ser implantada em um nível, notadamente o operacional.", "c": "O apoio da alta gestão é fundamental, pois traz legitimidade e recursos ao processo.", "d": "Apenas os níveis operacional e gerencial devem fazer parte do processo, em razão das atribuições."}, "corretas": ["c"], "explicacao": "O apoio da alta gestão é fundamental para o processo.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U4-Q04", "disciplina": "gov", "unidade": 4, "origem": {"questionario": "4.4 Quiz", "tipo": "quiz"}, "tema": "Implantação da governança (fase 2: diagnóstico)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Na fase 2 da implantação, é importante identificar os problemas de fraqueza relacionados à governança. Uma vez identificados, o correto é:", "alternativas": {"a": "ocultar os problemas, para não ter problemas com a alta gestão.", "b": "mapear esses problemas com cuidado, analisando sua gradação, criticidade e impacto.", "c": "identificar e arquivar, já que a identificação por si é suficiente.", "d": "apenas identificar, sem tomar medidas posteriores."}, "corretas": ["b"], "explicacao": "O mapeamento e a seleção são fundamentais para os passos seguintes serem tomados adequadamente.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U4-Q05", "disciplina": "gov", "unidade": 4, "origem": {"questionario": "4.4 Quiz", "tipo": "quiz"}, "tema": "Políticas", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Existem documentos que definem princípios ou normas sobre o assunto. Do que estamos falando?", "alternativas": {"a": "Roteiros.", "b": "Políticas.", "c": "Regras.", "d": "Proibições."}, "corretas": ["b"], "explicacao": "As políticas definem regras e normas sobre os assuntos.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U4-Q06", "disciplina": "gov", "unidade": 4, "origem": {"questionario": "4.8 Quiz", "tipo": "quiz"}, "tema": "Implantação da governança ('trem da governança')", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Em muitas situações, a implementação da governança é feita com o chamado \"trem da governança\". Ele se caracteriza por:", "alternativas": {"a": "um conjunto de eventos que, após terminarem, voltam o cenário praticamente a onde estava.", "b": "um conjunto continuado e consistente de ações na governança.", "c": "uma estrutura organizada de implantação de governança.", "d": "uma fórmula de sucesso na implantação de governança."}, "corretas": ["a"], "explicacao": "O 'trem da governança' é uma implantação feita como uma sequência de eventos (palestras, projetos pontuais) que, ao terminar, deixa tudo praticamente como estava, sem mudança real e duradoura.", "por_que_erradas": {"b": "O \"trem da governança\" se caracteriza pela descontinuidade das ações."}, "fonte_gabarito": "oficial"}, {"id": "GOV-U4-Q07", "disciplina": "gov", "unidade": 4, "origem": {"questionario": "4.8 Quiz", "tipo": "quiz"}, "tema": "Resistência à governança", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Em muitas situações, a implantação da governança sofre resistência dos funcionários, o que compromete os resultados. Assinale corretamente a alternativa que apresenta uma causa possível.", "alternativas": {"a": "A governança é um processo que traz perdas às pessoas.", "b": "Os funcionários ficam temerosos de perder importância.", "c": "A governança sempre traz redução de salários.", "d": "Normalmente a governança traz demissões."}, "corretas": ["b"], "explicacao": "Normalmente os funcionários ficam temerosos de perder importância.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U4-Q08", "disciplina": "gov", "unidade": 4, "origem": {"questionario": "4.8 Quiz", "tipo": "quiz"}, "tema": "Cultura de governança", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Em muitas empresas, há uma situação em que as pessoas não sabem o que é governança nem há qualquer sensibilização de pessoas quanto à importância da governança. Nesse caso, o que falta?", "alternativas": {"a": "Uma cultura de governança.", "b": "Sistemas apropriados.", "c": "Conformidade.", "d": "Normas e preceitos legais."}, "corretas": ["a"], "explicacao": "Nesse tipo de cenário, falta uma cultura de governança.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U4-Q09", "disciplina": "gov", "unidade": 4, "origem": {"questionario": "4.8 Quiz", "tipo": "quiz"}, "tema": "Financiamento da governança", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Em muitas situações, as empresas se recusam a gastar o necessário para implementar a governança. Nesse tipo de cenário, o comum é termos:", "alternativas": {"a": "falta de sistemas.", "b": "definição inadequada de papéis.", "c": "financiamento insuficiente.", "d": "falta de sensibilização."}, "corretas": ["c"], "explicacao": "Nesse caso, o financiamento é insuficiente.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U4-Q10", "disciplina": "gov", "unidade": 4, "origem": {"questionario": "4.8 Quiz", "tipo": "quiz"}, "tema": "Monitoramento e avaliação", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Em muitos casos, há a implementação da governança, mas nada é controlado, dados não são adquiridos adequadamente e medidas corretivas não são tomadas. Com base nisso, o que ocorre?", "alternativas": {"a": "Falta de monitoramento e avaliação.", "b": "Falta de sensibilização.", "c": "Financiamento insuficiente.", "d": "Definição inadequada de papéis."}, "corretas": ["a"], "explicacao": "Nesse tipo de cenário, o que há é a falta de monitoramento e avaliação.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U4-Q11", "disciplina": "gov", "unidade": 4, "origem": {"questionario": "4.9 Lacunas", "tipo": "lacunas"}, "tema": "Implantação da governança (lacunas)", "tipo": "lacunas", "multipla_resposta": false, "enunciado": "Complete as lacunas do texto.", "texto_lacunas": "O processo de implantação da governança tem {{1}} bem definidas. É importante tratar cada fase com cuidado e fazer a implantação considerando a empresa como um {{2}} . Após a implantação, é necessário aproveitar as {{3}} aprendidas para melhorar o processo de {{4}} da governança.", "opcoes_lacunas": ["lições, informações", "implantação, implementação, instituição", "todo, bloco", "fases, etapas, atividades"], "corretas": ["fases, etapas, atividades", "todo, bloco", "lições, informações", "implantação, implementação, instituição"], "explicacao": "A implantação tem FASES bem definidas, deve considerar a empresa como um TODO e, depois, usar as LIÇÕES aprendidas para melhorar o processo de IMPLANTAÇÃO (melhoria contínua).", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U4-Q12", "disciplina": "gov", "unidade": 4, "origem": {"questionario": "4.10 Encadeamento", "tipo": "associacao"}, "tema": "Políticas organizacionais (associação)", "tipo": "associacao", "multipla_resposta": false, "enunciado": "Diversas são as políticas implantadas nas empresas. Relacione cada uma dessas políticas com a sua finalidade.", "pares": [{"item": "Relaciona-se com o retorno obtido no uso da Tecnologia da Informação.", "resposta": "Fluxo e processo de valor."}, {"item": "Trata de normas que buscam garantir confidencialidade, integridade e disponibilidade.", "resposta": "Política de segurança da informação."}, {"item": "Busca tratar possíveis ameaças e ataques, gerenciando a possibilidade de ocorrência.", "resposta": "Política de gestão de riscos."}, {"item": "Procura manter a adequação e o compliance da empresa com normas e regulações.", "resposta": "Política de conformidade."}], "opcoes_associacao": ["Política de segurança da informação.", "Política de gestão de riscos.", "Fluxo e processo de valor.", "Política de conformidade."], "corretas": ["Fluxo e processo de valor.", "Política de segurança da informação.", "Política de gestão de riscos.", "Política de conformidade."], "explicacao": "Retorno da TI = FLUXO E PROCESSO DE VALOR. Confidencialidade, integridade e disponibilidade = POLÍTICA DE SEGURANÇA DA INFORMAÇÃO. Tratar ameaças e probabilidade de ocorrência = POLÍTICA DE GESTÃO DE RISCOS. Compliance com normas = POLÍTICA DE CONFORMIDADE.", "por_que_erradas": {}, "fonte_gabarito": "oficial"}, {"id": "GOV-U4-Q13", "disciplina": "gov", "unidade": 4, "origem": {"questionario": "4.11 Avaliação Final - Unidade 4", "tipo": "avaliacao_final"}, "tema": "Implantação da governança (planejamento)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A implantação da governança deve acontecer, em qualquer caso, após um planejamento adequado. Dentre as alternativas abaixo, qual delas é a mais provável de acontecer se não for realizado o planejamento de forma correta?", "alternativas": {"a": "Os objetivos tendem a não ser alcançados.", "b": "A implementação será mais rápida e eficaz.", "c": "Haverá uma redução de custos, já que se economizou em pessoal.", "d": "Haverá uma maior objetividade, com menos risco de erros na implantação."}, "corretas": ["a"], "explicacao": "Sem planejamento adequado, a tendência é os objetivos NÃO serem alcançados: faltam metas claras, recursos e sequência de ações.", "por_que_erradas": {"b": "Sem planejamento a implantação fica mais lenta e caótica.", "c": "Economizar no planejamento costuma gerar retrabalho e mais custo.", "d": "Sem planejamento há MAIS risco de erro."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U4-Q14", "disciplina": "gov", "unidade": 4, "origem": {"questionario": "4.11 Avaliação Final - Unidade 4", "tipo": "avaliacao_final"}, "tema": "Implantação da governança (alta gestão)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Em processos empresariais complexos, como a implementação da governança, é necessário que haja uma ação firme e decidida por parte da alta gestão, uma vez que:", "alternativas": {"a": "a alta gestão criará obstáculos à implantação.", "b": "é a alta gestão que realizará as atividades em nível operacional.", "c": "a alta gestão tem condições de direcionar as ações, dando-as legitimidade.", "d": "a alta gestão tenderá a reduzir os aportes financeiros necessários."}, "corretas": ["c"], "explicacao": "A alta gestão tem autoridade para direcionar as ações e dar LEGITIMIDADE ao processo, além de garantir recursos.", "por_que_erradas": {"a": "A alta gestão deve patrocinar, não criar obstáculos.", "b": "Quem executa no nível operacional são as equipes, não a alta gestão.", "d": "O papel esperado é garantir os aportes, não reduzi-los."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U4-Q15", "disciplina": "gov", "unidade": 4, "origem": {"questionario": "4.11 Avaliação Final - Unidade 4", "tipo": "avaliacao_final"}, "tema": "Implantação da governança (motivação)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Não se decide implantar a governança de qualquer maneira. Antes de mais nada, é um processo organizado que tem sua atuação baseada, principalmente:", "alternativas": {"a": "em tornar a gestão cada vez mais independente da governança.", "b": "a partir de eventos que geraram a sua necessidade.", "c": "em gerar ações que permitam ocultar a real situação da empresa.", "d": "em reduzir os custos ao máximo, mesmo se prejudicar a implantação."}, "corretas": ["b"], "explicacao": "A implantação é um processo organizado que parte dos eventos (problemas, fraudes, exigências legais, falhas) que geraram a sua necessidade.", "por_que_erradas": {"a": "Governança e gestão devem ser integradas, não independentes.", "c": "Governança busca transparência, não ocultar a situação.", "d": "Cortar custos prejudicando a implantação compromete o resultado."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U4-Q16", "disciplina": "gov", "unidade": 4, "origem": {"questionario": "4.11 Avaliação Final - Unidade 4", "tipo": "avaliacao_final"}, "tema": "Implantação da governança (fase 3: melhoria contínua)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "O foco da terceira fase da implantação da governança é bem evidente: o da melhoria contínua. Embora muitas empresas digam que têm esse foco, nem sempre é o que acontece, há mais discurso do que ação. Um dos motivos mais comuns é:", "alternativas": {"a": "a melhoria contínua sempre traz mais custos do que manter tudo como está.", "b": "a melhoria contínua é mais uma utopia do que uma realidade no ambiente empresarial.", "c": "a melhoria contínua é apenas um conceito sem aplicação prática.", "d": "nem sempre as pessoas aceitam que precisam melhorar seus processos."}, "corretas": ["d"], "explicacao": "A melhoria contínua costuma ficar só no discurso porque as pessoas resistem a admitir que precisam mudar seus processos: é uma barreira cultural e humana.", "por_que_erradas": {"a": "A melhoria contínua tende a REDUZIR custos no médio prazo.", "b": "Ela é prática comum (PDCA, Kaizen), não utopia.", "c": "Tem aplicação prática clara."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U4-Q17", "disciplina": "gov", "unidade": 4, "origem": {"questionario": "4.11 Avaliação Final - Unidade 4", "tipo": "avaliacao_final"}, "tema": "Implantação da governança (fatores de sucesso)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A implantação de governança não é simples, pois demanda diversas ações e comprometimento de stakeholders e líderes. Dentre as alternativas abaixo, qual é um fator de sucesso para que a implantação ocorra da melhor forma?", "alternativas": {"a": "Foco primordial em lucros.", "b": "Cultura organizacional.", "c": "Processos semi-estruturados.", "d": "Patrocínio da alta gestão."}, "corretas": ["d"], "explicacao": "O patrocínio da alta gestão é o principal fator crítico de sucesso: dá legitimidade, prioridade e recursos.", "por_que_erradas": {"a": "Foco primordial em lucros desvia do objetivo de governança.", "b": "A cultura organizacional pesa, mas é algo a ser construído; o fator de sucesso clássico é o patrocínio.", "c": "Processos semiestruturados atrapalham; o ideal são processos bem definidos."}, "fonte_gabarito": "especialista", "observacao": "A alternativa b (cultura organizacional) também é defensável; a d é a resposta mais clássica da literatura. Confirmar no gabarito oficial."}, {"id": "GOV-U4-Q18", "disciplina": "gov", "unidade": 4, "origem": {"questionario": "4.11 Avaliação Final - Unidade 4", "tipo": "avaliacao_final"}, "tema": "Cultura de governança (capacitação)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A compreensão da governança decorre, principalmente, do conhecimento da sua abrangência e de suas consequências. A melhor forma de promover essa criação de uma cultura de governança é:", "alternativas": {"a": "obrigar os funcionários a se capacitar por conta própria.", "b": "fazer palestras de participação opcional.", "c": "realizar capacitações planejadas dos colaboradores.", "d": "promover descontos salariais de quem não mostrar conhecimento de governança."}, "corretas": ["c"], "explicacao": "A melhor forma de criar uma cultura de governança é com capacitações PLANEJADAS dos colaboradores, conduzidas pela organização.", "por_que_erradas": {"a": "Obrigar a se capacitar por conta própria transfere a responsabilidade e gera resistência.", "b": "Palestras opcionais têm baixo alcance.", "d": "Punição salarial gera resistência e é inadequada."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U4-Q19", "disciplina": "gov", "unidade": 4, "origem": {"questionario": "4.11 Avaliação Final - Unidade 4", "tipo": "avaliacao_final"}, "tema": "Implantação da governança (comunicação)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Em uma dada empresa, foi realizado um programa com um planejamento de implantação de governança durante dois anos. Curiosamente, ao final, vários funcionários de nível operacional não tinham ideia de como isso afetaria o seu trabalho e muito menos como colaborar. Nesse tipo de situação, o que pode ter ocorrido?", "alternativas": {"a": "Excesso de gastos com promoções.", "b": "Falta de investimento.", "c": "Falta de participação da alta gestão.", "d": "Falta de transparência e comunicação."}, "corretas": ["d"], "explicacao": "Se o pessoal operacional não sabe como a governança afeta seu trabalho, faltou TRANSPARÊNCIA E COMUNICAÇÃO durante a implantação.", "por_que_erradas": {"a": "Não há indício de gastos com promoções.", "b": "O programa existiu por dois anos; o problema é informação, não verba.", "c": "Não há indício de ausência da alta gestão."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U4-Q20", "disciplina": "gov", "unidade": 4, "origem": {"questionario": "4.11 Avaliação Final - Unidade 4", "tipo": "avaliacao_final"}, "tema": "Comunicação de resultados (dashboards)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "A implementação de governança deve ser compreensível para todos os gestores. Nem todos costumam conhecer a fundo os conceitos de governança, mas isso pode ser resolvido com treinamentos apropriados. O mais importante é conseguir apresentar as mudanças e os resultados de forma visual simples e didática. Os instrumentos apropriados para esse tipo de apresentação são:", "alternativas": {"a": "texto corrido.", "b": "e-mails.", "c": "dashboards.", "d": "podcasts."}, "corretas": ["c"], "explicacao": "Para apresentar mudanças e resultados de forma visual, simples e didática, o instrumento ideal são DASHBOARDS (painéis com indicadores).", "por_que_erradas": {"a": "Texto corrido não é visual.", "b": "E-mails não são visuais nem consolidados.", "d": "Podcasts são áudio, não visuais."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U4-Q21", "disciplina": "gov", "unidade": 4, "origem": {"questionario": "4.11 Avaliação Final - Unidade 4", "tipo": "avaliacao_final"}, "tema": "Implantação da governança (objetivos inexequíveis)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Em muitas empresas, a governança acaba por não ser bem implementada, deixando várias lacunas entre o que se quer e o que de fato se conseguiu, em razão da disponibilidade financeira ou de tempo para implementação. Nesse tipo de situação, isso decorre basicamente de:", "alternativas": {"a": "definição de objetivos inexequíveis.", "b": "excesso de financiamento.", "c": "adesão da alta gestão.", "d": "comunicação apropriada."}, "corretas": ["a"], "explicacao": "Lacunas entre o que se quer e o que se conseguiu, por falta de dinheiro ou tempo, indicam objetivos INEXEQUÍVEIS: metas maiores que os recursos disponíveis.", "por_que_erradas": {"b": "Excesso de financiamento não causaria falta de recursos.", "c": "Adesão da alta gestão é fator de sucesso.", "d": "Comunicação apropriada é fator de sucesso."}, "fonte_gabarito": "especialista"}, {"id": "GOV-U4-Q22", "disciplina": "gov", "unidade": 4, "origem": {"questionario": "4.11 Avaliação Final - Unidade 4", "tipo": "avaliacao_final"}, "tema": "Implantação da governança (papéis e responsabilidades)", "tipo": "multipla_escolha", "multipla_resposta": false, "enunciado": "Em uma implantação recente de governança, uma empresa não teve resultados apropriados porque muitas pessoas realizaram trabalhos redundantes, enquanto outros trabalhos não foram realizados por falta de pessoas designadas para realizar. Então, o que houve nesse caso?", "alternativas": {"a": "Definição de objetivos inexequíveis.", "b": "Falta de participação da alta gestão.", "c": "Excesso de gastos com promoções.", "d": "Definição inadequada dos papéis e responsabilidades."}, "corretas": ["d"], "explicacao": "Trabalho redundante de uns e tarefas sem dono indicam definição inadequada de PAPÉIS E RESPONSABILIDADES (falta de uma matriz RACI, por exemplo).", "por_que_erradas": {"a": "Objetivos inexequíveis causam metas não atingidas por falta de recursos.", "b": "Não há indício de ausência da alta gestão.", "c": "Não há relação com gastos em promoções."}, "fonte_gabarito": "especialista"}]};
